window.__LEX={"G1000":"<h1>bole</h1>\n<p>Strong n° 1000 <i>Prononciation [bol-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un jet (de pierre), portée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βολή, ῆς (ἡ) :<br>   I</b> action de lancer, <i>d’où :</i><br><b>      1</b> jet d’un projectile (<i>pierre,</i> EUR. <i>Or. 59 ;</i> HDN <i>2, 6, 19 ; javelots,</i> OPP. <i>C. 3, 137 ; pierre et javelot,</i> THC. <i>5, 65 ; etc</i>.) ; jet de dés, SOPH. <i>fr. 381 ;</i><br><b>      2</b> <i>p. suite,</i> trait lancé : βολαὶ κεραύνιοι, ESCHL. <i>Sept. 430,</i> traits de la foudre ; <i>abs</i>. βολαί, EUR. <i>Ion 1135,</i> rayons du soleil ; βολαὶ ἡλίου, SOPH. <i>Aj. 877 ;</i> EUR. <i>Or. 1263,</i> la région d’où partent les rayons du soleil, l’orient ; βολὴ ὀφθαλμῶν, OD. <i>4, 150 ;</i> PHILSTR. <i>619 ;</i> βλεμμάτων, ESCHL. <i>fr. 238, etc</i>. regards qu’on lance ; <i>fig</i>. β. ἔρωτος, ANTH. <i>12, 160,</i> traits de l’amour ;<br><b>      3</b> <i>p. ext</i>. coup porté de loin (par une arme de trait, <i>p. opp. à</i> πληγή) OD. <i>17, 283 ;</i> HÉS. <i>Th. 683 ;</i> A. RH. <i>4, 201 ;</i><br><b>   II</b> action de laisser tomber, de perdre (ses fleurs), <i>en parl. d’une plante,</i> TH.<br><span><b>Étym</b>. βάλλω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βολη - βολή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1001":"<h1>bolizo</h1>\n<p>Strong n° 1001 <i>Prononciation [bol-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>lever le plomb, jeter une sonde\n<ol type=\"a\">\n<li>ligne et plomb avec lesquels les marins sondent la profondeur de la mer</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βολίζω</b> (<i>seul. part. ao. plur</i>. βολίσαντες) jeter la sonde, NT. <i>Ap. 27, 28 ; au pass. (seul. prés</i>.) s’enfoncer, <i>en parl. d’une sonde <i>ou</i> d’objets analogues,</i> GEOP. <i>6, 17</i>.<br><span><b>Étym</b>. βολίς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βολιζω - βολίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G1002":"<h1>bolis</h1>\n<p>Strong n° 1002 <i>Prononciation [bol-ece']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un projectile, dard, javelot</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βολίς, ίδος (ἡ) :<br>   I</b> objet qu’on lance <i>ou</i> qu’on jette :<br><b>      1</b> trait, PLUT. <i>Demetr. 3 ;</i><br><b>      2</b> dé à jouer, ANTH. <i>9, 767, 768 ;</i><br><b>   II</b> jet : ἀστραπῶν βολίδες, SPT. <i>Sap. 5,</i> éclairs qui jaillissent.<br><span><b>Étym</b>. βάλλω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βολις - βολίς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>","G1003":"<h1>Booz</h1>\n<p>Strong n° 1003 <i>Prononciation [bo-oz']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Boaz = « en lui est la force ».\n<ol><li>un parent de Ruth, devenu ensuite son second mari.</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βοος</font> &lt; בעז - <font face=\"Georgia\">Βόες</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1004":"<h1>borboros</h1>\n<p>Strong n° 1004 <i>Prononciation [bor'-bor-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>fiente, fumier, boue, bourbier, fange</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βόρϐορος, ου (ὁ)</b> fange, bourbier (<i>différent de</i> πηλός, boue, terre détrempée ; <i>cf</i>. PLAT. <i>Phæd. 111</i> e), ESCHL. <i>Eum. 694 ;</i> AR. <i>Vesp. 259 ;</i> PLAT. <i>Phæd. 69</i> c ; <i>au plur. Phæd. 110</i> a.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βορβορος - βόρβορος</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1005":"<h1>borrhas</h1>\n<p>Strong n° 1005 <i>Prononciation [bor-hras']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le vent du nord-nord-est</li>\n<li>le nord</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Βορρᾶς</b>, <i>v</i>. Βορέας.<br>\n<b>Βορέας, ου</b> <i>et</i> <b>α (ὁ) :<br>      1</b> vent du nord-nord-ouest, <i>ou, en gén</i>. vent du nord, IL. <i>5, 524 ;</i> OD. <i>5, 296, etc. ;</i> ARSTT. <i>Meteor. 2, 3, 25, etc. ;</i> le Vent du nord <i>personnifié, càd</i>. Borée, IL. <i>9, 5 ;</i> HÉS. <i>Th. 379 ;</i> PD. HDT. <i>etc. ;</i><br><b>      2</b> <i>p. ext</i>. région du nord, le nord : πρὸς βορέαν τοῦ ὄρους, THC. <i>2, 96,</i> vers le nord de la montagne.<br><span><b><span class=\"arrow\"></span></b> <i>Voc</i>. Βορέα, ORPH. <i>H. 80, 2.<br>Gén</i>. Βορέου, ATT. (CIA. <i>1, 321, 29, avant 409 av. J.C.) ; épq. réc</i>. (ORPH. <i>Arg. 19) ; postér. gén. att</i>. βορείου, CIA. <i>2, 167, 120 (peu après 307 av. J.C.). — Épq. et ion. nomin</i>. Βορέης, IL. <i>20, 223, etc. ;</i> HDT. <i>1, 193 ;</i> A. RH. <i>1, 212 ; etc. (dissyll. au commenc. du vers</i> = Βορρῆς, IL. <i>9, 5 ; 23, 195).<br>Gén</i>. Βορέαο <span>[ᾱ]</span>, IL. <i>5, 524 ;</i> HÉS. <i>O. 504 ;</i> CALL. <i>H. 4, 26, etc. ; ou</i> Βορέω, IL. <i>14, 395 ; 23, 692 ;</i> OD. <i>14, 533 ;</i> THGN. <i>716 ;</i> A. RH. <i>2, 288, etc. ; gén. ion. en prose</i> Βορέω, HDT. <i>2, 101 ; 4, 37.<br>Dat</i>. Βορέῃ, A. RH. <i>1, 212 ;</i> Q. SM. <i>8, 243, etc.<br>Acc</i>. Βορέην, HÉS. <i>Th. 379 ;</i> NONN. <i>D. 1, 131, etc. ;</i> HDT. <i>7, 189 ;</i> PLAT. <i>Leg. 661</i> a. —<br><i>Dor. gén</i>. Βορέα <span>[ᾱ]</span> PD. <i>O. 3, 56 ;</i> SOPH. <i>Tr. 113. — Att. postér. (d’orig. dorienne) nomin</i>. Βορρᾶς, <i>gén</i>. Βορρᾶ, THC. <i>6, 2, etc. ou</i> Βορροῦ, ARISTONYM. (HSCH.) — <i>En outre, v</i>. *Βορεύς.<br><span><b>Étym</b>. <i>p.-ê. indo-europ</i>. *g<sup>w</sup>(o)rH-, montagne ; <i>cf. sscr</i>. girí-, <i>litt</i>. « le vent de la montagne ».</span></span><br><br>\n<u>Mot apparenté</u> : <b>βορρᾶθεν</b>, <i>adv</i>., en venant du Nord, CIA. <i>2, 777, 4, 11, 17 (commenc. du 4<sup>e</sup> siècle av. J.C.) ; 600, 9 (300 av. J.C</i>.) ; TH. <i>fr. 6, 1, 11</i>.<br><span><b>Étym</b>. Βορρᾶς, -θεν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βορρας - βορρᾶς</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1006":"<h1>bosko</h1>\n<p>Strong n° 1006 <i>Prononciation [bos'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>nourrir, paître, brouter\n<ol type=\"a\">\n<li>image des devoirs de l'enseignant Chrétien pour assurer en permanence le bien-être spirituel des membres de l'église</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βόσκω</b> <span>(<i>impf</i>. ἔϐοσκον, <i>f</i>. βοσκήσω, <i>ao</i>. ἐϐόσκησα, <i>pf. inus. ; pass. ao</i>. ἐϐοσκήθην)</span><br><b>   I</b> faire paître, <i>d’où :</i><br><b>      1</b> mener paître, <i>acc</i>. IL. <i>15, 548 ;</i><br><b>      2</b> donner la pâture à, nourrir, <i>en parl. d’animaux, acc</i>. OD. <i>12, 97 ; en parl. de pers</i>. βόσκειν τινά, OD. <i>14, 325,</i> nourrir qqn ; βόσκειν γαστέρα, OD. <i>17, 228, 559,</i> nourrir son estomac ; βόσκει γαῖα (ἀνθρώπους), OD. <i>11, 365,</i> la terre nourrit (les hommes) ; <i>cf</i>. SOPH. <i>O.R. 1425 ; en parl. de l’entretien de serviteurs, de soldats, etc</i>. HDT. <i>6, 39 ;</i> THC. <i>7, 48 ; fig</i>. β. νόσον, SOPH. <i>Ph. 313,</i> alimenter <i>ou</i> entretenir une maladie ; <i>d’où</i> faire vivre, soutenir : ἐλπίδες βόσκουσι φυγάδας, EUR. <i>Ph. 399,</i> l’espérance soutient les exilés ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. βοσκήσομαι)</span> paître, <i>en parl. d’animaux (chevaux, bœufs, etc</i>.) IL. <i>5, 162 ; 20, 223 ;</i> OD. <i>12, 128, 355, etc.,</i> β. λειμῶνι, IL. <i>16, 151 ;</i> OD. <i>21, 49,</i> se repaître de l’herbe de la prairie ; <i>avec l’acc</i>. β. ποίην, HH. <i>Merc. 27, 232,</i> paître l’herbe ; <i>cf</i>. ESCHL. <i>Ag. 118 ;</i> ARSTT. <i>H.A. 8, 2, 24 ; en parl. d’oiseaux,</i> se repaître de, IL. <i>15, 691 ; fig</i>. se repaître de, <i>dat. :</i> ἰυγμοῖσι, ESCHL. <i>Ch. 26,</i> de sanglots ; ἐλπίσιν, EUR. <i>Bacch. 617,</i> d’espérances ; περί τι <i>ou</i> ἐπί τινι, ANTH. <i>5, 272, 286,</i> de qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. inf. dor</i>. βόσκεν, THCR. <i>Idyl. 4, 2 (vulg.). Impf. poet. 3 sg</i>. βόσκε, IL. <i>15, 548. Ao. réc</i>. ἐϐόσκησα, GEOP. <i>18, 7. — Pass. moy. impf. 3 pl. poét</i>. βόσκοντο, OD. <i>12, 128. Impf. itér. 3 pl</i>. βοσκέσκοντο, OD. <i>12, 355. Fut. dor</i>. βοσκησοῦμαι, THCR. <i>Idyl. 5, 103. Ao. pass. au sens moy</i>. ἐϐοσκήθην, BABR. <i>89 ;</i> TRAG. <i>fr. 268 Wagn. ;</i> NIC. <i>Th. 34, etc</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *g<sup>w</sup>eh₃-, nourrir, faire paître ; <i>v</i>. βοτόν, βοτάνη <i>et probabl</i>. βοῦς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βοσκω - βόσκω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> est le terme au sens le plus large,  est d'un sens plus limité ; le premier comprend une surveillance, le second dénote l'action de nourrir ;  peut être rendu par « soigner »,  est bien spécifiquement « nourrir ».</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Luc (3)</li>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G1007":"<h1>Bosor</h1>\n<p>Strong n° 1007 <i>Prononciation [bos-or']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Bosor = « brûlant, flambeau »\n<ol><li>le père de Balaam</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βοσορ</font> &lt; בעור - <font face=\"Georgia\">Βοσόρ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1008":"<h1>botane</h1>\n<p>Strong n° 1008 <i>Prononciation [bot-an'-ay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une herbe convenant au fourrage, herbe verte, jeune plante</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βοτάνη, ης (ἡ)</b> <span>[ᾰ]</span><br><b>      1</b> herbe à paître, <i>d’où</i> pâturage, IL. <i>13, 493 ;</i> PLAT. <i>Rsp. 401</i> c, <i>etc. ;</i><br><b>      2</b> herbe, <i>en gén. p. opp. à</i> λάχανον, ARSTT. <i>Plant. 1, 4, 7</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. βοτάνα, PD. <i>N. 5, 43 ;</i> EUR. <i>fr. 775, 27 ;</i> THCR. <i>Idyl. 25, 87</i>.<br><span><b>Étym</b>. βόσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βοτανη - βοτάνη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1009":"<h1>botrus</h1>\n<p>Strong n° 1009 <i>Prononciation [bot'-rooce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>la grappe ou un ensemble de grappes (de raisin)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βότρυς, υος (ὁ) :<br>   I</b> grappe de raisin, IL. <i>18, 562 ;</i> ATT. (AR. <i>Eq. 1072 ;</i> PLAT. TH. <i>etc.) ; p. ext</i>. tout fruit <i>ou</i> plante en forme de grappe, TH. ; <i>part. autre nom de la plante</i> ἀρτεμισία, DIOSC. <i>3, 130 ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> boucle de cheveux, <i>c</i>. βότρυχος, ANTH. <i>5, 287 ;</i> NONN. <i>D. 1, 528, etc. ;</i><br><b>      2</b> pendant d’oreille, AR. <i>fr. 309, 10</i>.<br><span><b>Étym</b>. <i>p.-ê. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βοτρυς - βότρυς</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1010":"<h1>bouleutes</h1>\n<p>Strong n° 1010 <i>Prononciation [bool-yoo-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un conseiller, sénateur</li>\n<li>un membre du Sanhédrin</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βουλευτής, οῦ (ὁ) :<br>      1</b> qui conseille, <i>gén</i>. ANT. <i>127, 29 ;</i><br><b>      2</b> membre d’un conseil, IL. <i>6, 114 ;</i> HDT. <i>9, 5 ; part. à Athènes,</i> membre de la βουλή <i>ou</i> conseil des Cinq cents, ANT. <i>146, 35 ;</i> AND. <i>6, 41, etc. ; à Rome,</i> sénateur, DH. <i>2, 12, etc</i>.<br><span><b>Étym</b>. βουλεύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βουλευτης - βουλευτής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1011":"<h1>bouleuo</h1>\n<p>Strong n° 1011 <i>Prononciation [bool-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>délibérer avec soi-même, considérer</li>\n<li>prendre conseil, résoudre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βουλεύω</b> <span>(<i>f</i>. εύσω, <i>ao</i>. ἐϐούλευσα, <i>pf</i>. βεϐούλευκα)</span><br><b>   I</b> (βουλή, conseil, délibération) :<br><b>      1</b> tenir conseil, délibérer, IL. <i>1, 531 ; p. opp. à</i> μάχεσθαι, OD. <i>14, 491 ;</i> β. περί τινος, OD. <i>16, 234 ;</i> HDT. <i>1, 120 ;</i> THC. <i>3, 28, etc</i>. délibérer sur qqe ch. ; βουλεύειν ὅπως τι γένηται, OD. <i>9, 420,</i> délibérer pour qu’une chose se fasse <i>ou</i> pour voir comment une chose pourrait se faire ; β. βουλάς, IL. <i>10, 147, 415,</i> agiter des projets, délibérer ;<br><b>      2</b> projeter après délibération, projeter, décider : νόον, OD. <i>5, 23,</i> former un projet ; ὁδόν, OD. <i>1, 444 ;</i> φύξιν, IL. <i>10, 311,</i> former le projet d’un voyage, d’une fuite ; <i>avec double rég</i>. τινι β. ὄλεθρον, IL. <i>14, 464,</i> décider la perte de qqn (<i>cf</i>. OD. <i>5, 179, 187, etc</i>.) ; βουλεύειν θάνατόν τινι, PLAT. <i>Leg. 871</i> e, décider la mort de qqn ; <i>cf</i>. HDT. <i>9, 110 ; avec l’inf</i>. décider de, IL. <i>9, 458 ;</i> OD. <i>9, 299 ;</i> HDT. <i>1, 73 ; 6, 52, etc. ;</i> ἐς μίαν βουλεύειν (<i>s.-e</i>. βουλήν), IL. <i>2, 379,</i> décider à l’unanimité ; <i>au pass</i>. être décidé, être résolu, <i>en parl. d’un projet, d’un plan, etc</i>. ESCHL. <i>Sept. 198, etc. ;</i> HDT. <i>7, 10, 4 ;</i> πῶς σφῷν βεϐούλευται ; PLAT. <i>Euthyd. 274</i> a, quelle résolution avez-vous prise ? qu’avez-vous décidé ? <i>avec l’inf</i>. τοῖσι δὲ ἐϐεϐούλευτο, <i>inf</i>. HDT. <i>5, 92, 3,</i> ils avaient résolu de, <i>etc. ; abs</i>. τὸ βουλευόμενον, ARSTT. <i>Pol. 4, 16, 16, etc</i>. le soin de délibérer et de décider ; τὰ βουλευόμενα, XÉN. <i>Cyr. 6, 2, 2,</i> les projets <i>ou</i> questions en délibération ; τὰ βεϐουλευμένα, HDT. <i>4, 128,</i> les résolutions prises ;<br><b>      3</b> donner un conseil : τὰ λῷστα β. ESCHL. <i>Pr. 203,</i> donner le meilleur conseil ; <i>avec un dat</i>. β. τινί, ESCHL. <i>Eum. 700,</i> donner un conseil à qqn ;<br><b>   II</b> (βουλή, assemblée délibérante) être membre d’un conseil, siéger dans un conseil, HDT. <i>6, 57 ;</i> ARSTT. <i>Pol. 3, 11, 16 ; part. à Athènes, en parl. du conseil des Cinq cents ou Sénat,</i> XÉN. <i>Mem. 1, 1, 18 ;</i> PLAT. <i>Gorg. 473</i> e ; <i>etc. ;</i><br><b><i>Moy.</i></b> <span>(<i>f</i>. βουλεύσομαι, <i>ao</i>. ἐϐουλευσάμην <i>et</i> ἐϐουλεύθην, <i>pf</i>. βεϐούλευμαι)</span><br><b>   I</b> (βουλή, conseil, délibération) :<br><b>      1</b> se consulter, délibérer en soi-même <i>ou</i> avec d’autres, HDT. <i>7, 10, 4, etc. ;</i> περί τινος, THC. <i>3, 44 ;</i> PLAT. <i>Phædr. 231</i> a, <i>etc. ;</i> περί τι, PLAT. <i>Rsp. 604</i> c ; ὑπέρ τινος, PLAT. <i>Rsp. 428</i> d, au sujet de qqe ch. ; πρός τι, THC. <i>7, 47,</i> pour prendre des mesures au sujet de qqe ch. ; β. βουλὴν περί τινος, PLAT. <i>Pol. 298</i> b, délibérer sur qqn <i>etc. ;</i><br><b>      2</b> <i>p. suite,</i> projeter en soi-même, méditer : κακὴν ἀπάτην, IL. <i>2, 114,</i> une fraude ; <i>d’où</i> décider, se résoudre à, <i>acc</i>. THC. <i>2, 44 ; 6, 23 ; avec un inf</i>. HDT. <i>3, 134 ;</i> PLAT. <i>Charm. 176</i> c ; <i>avec un relat</i>. ὅ τι χρὴ ποιεῖν, XÉN. <i>An. 1, 3, 11,</i> décider ce qu’il faut faire ; <i>ou une conj</i>. β. πῶς, XÉN. <i>An. 3, 4, 40, ou</i> ὅπως, XÉN. <i>Cyr. 1, 4, 13,</i> décider comment ;<br><b>   II</b> (βουλή, assemblée délibérante) prendre des résolutions comme membre d’un conseil, ARSTT. <i>Pol. 4, 14, 15</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. Prés. sbj. 2 sg. épq</i>. βουλεύῃσθα, IL. <i>9, 99 ; inf. épq</i>. βουλευέμεν, OD. <i>14, 491. Impf. poét</i>. βούλευον, OD. <i>1, 444. Fut. inf. épq</i>. βουλευσέμεν, OD. <i>5, 179. Ao. poét</i>. βούλευσα, IL. <i>9, 458. — Pass. ao</i>. ἐϐουλεύθην, THC. <i>1, 120 ;</i> PLAT. <i>Rsp. 442</i> b (<i>mais v. ci-dessous Moy.). Pf</i>. βεϐούλευμαι, ESCHL. <i>Pr. 998 ;</i> HDT. <i>7, 10 ; 8, 100 ;</i> PLAT. <i>Euthyd. 274</i> a, <i>etc. (mais v. ci-dessous Moy.). — Moy. f</i>. βουλεύσομαι, ESCHL. <i>Ag. 846 ;</i> THC. <i>1, 43 ; etc. mais au sens pass</i>. ESCHL. <i>Sept. 198. Ao. poét. 3 sg</i>. βουλεύσατο. IL. <i>2, 114. Ao. pass. au sens moy</i>. ἐϐουλεύθην, DH. <i>Exc. 15, 7 Pf</i>. βεϐούλευμαι, SOPH. <i>El. 947 ;</i> EUR. <i>Med. 893 ;</i> HDT. <i>3, 134 ;</i> THC. <i>6, 8 ;</i> XÉN. <i>Cyr. 3, 1, 15, etc</i>.<br><span><b>Étym</b>. βουλή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βουλευω - βουλεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (3)</li>\n<li>2 Corinthiens (3)</li>\n</ul>\n</td></tr>\n</table>","G1012":"<h1>boule</h1>\n<p>Strong n° 1012 <i>Prononciation [boo-lay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>conseil, but, décision, dessein, volonté</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βουλή, ῆς (ἡ) :<br>   I</b> <i>litt</i>. ce qu’on veut ; ce qu’on peut vouloir <i>ou</i> ce qu’il faut vouloir, <i>d’où :</i><br><b>      1</b> volonté, détermination, <i>en parl. des dieux,</i> IL. <i>1, 5 ; 12, 236 ;</i> OD. <i>8, 82, etc. ; en parl. des hommes,</i> IL. <i>2, 340, 344 ;</i> OD. <i>3, 150, etc. ;</i><br><b>      2</b> conseil, avis, IL. <i>18, 313, etc. ; joint à</i> μῦθοι, IL. <i>4, 323 ;</i> OD. <i>13, 298 ; 16, 420 ; d’où</i> réflexion, délibération, <i>p. opp. à</i> action, IL. <i>1, 258, etc. ; p. opp. à</i> πόλεμος, IL. <i>12, 213 ; joint à</i> νόος, OD. <i>3, 128 ; 12, 211, etc. ;</i> ἐν βουλῇ ἔχειν τι, HDT. <i>3, 78,</i> délibérer sur qqe ch. ;<br><b>      3</b> <i>p. suite,</i> dessein, projet, plan, IL. <i>2, 55, 282 ; etc. ;</i><br><b>   II</b> conseil, assemblée délibérante :<br><b>      1</b> <i>dans Hom</i>. conseil des anciens, IL. <i>2, 53, 194 ;</i> OD. <i>3, 127 ; dans</i> ESCHL. <i>Ag. 844,</i> conseil du roi ;<br><b>      2</b> <i>à Athènes,</i> conseil des Cinq cents <i>ou</i> Sénat, <i>sorte de conseil d’État chargé de préparer les lois à discuter dans l’assemblée du peuple ou</i> ἐκκλησία, HDT. <i>9, 5 ;</i> AR. <i>Vesp. 590 ;</i> ORAT. <i>etc. ; joint à</i> πεντακόσιοι : ἡ βουλὴ οἱ πεντακόσιοι, ESCHN. <i>56, 35,</i> le conseil des Cinq cents ; ἡ κάτω β. (<i>v</i>. κάτω), <i>m. sign. ;</i> ἡ ἄνω β. <i>ou</i> ἡ ἐν Ἀρείῳ πάγῳ β. (<i>v</i>. ἄνω <i>et</i> Ἄρειος πάγος) l’Aréopage : <i>ironiqu. en parl. du Sénat :</i> ἡ β. ἀπὸ κυάμου, THC. <i>8, 66,</i> le sénat de la fève ; — <i>de même,</i> conseil <i>ou</i> sénat <i>dans les autres cités grecques,</i> HDT. <i>7, 140 ;</i> XÉN. <i>Hell. 5, 2, 20, etc. ;</i><br><b>      3</b> <i>à Rome,</i> le Sénat, DH. <i>6, 69, etc. ; d’où</i> lieu de réunion du Sénat, DH.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. plur. épq</i>. βουλέων, IL. <i>1, 273 ; 12, 236. Acc. plur</i>. βουλάς <span>[ᾰ]</span> HÉS. <i>Th. 534. — Dor</i>. βουλά, THCR. <i>Idyl. 17, 14 ; ou</i> βωλά, DÉM. <i>255, 21 (décr. Byz.) ; gén. pl</i>. βουλᾶν, PD. <i>P. 8, 3. Éol</i>. βόλλα, PLUT. <i>M. 288</i> b.<br><span><b>Étym</b>. βούλομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βουλη - βουλή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 5 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (7)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1013":"<h1>boulema</h1>\n<p>Strong n° 1013 <i>Prononciation [boo'-lay-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>volonté, conseil, but</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βούλημα, ατος (τὸ) :<br>      1</b> dessein, intention, PLAT. <i>Leg. 769</i> d, <i>802</i> c ; ARSTT. <i>Nic. 2, 1, etc. ;</i><br><b>      2</b> volonté exprimée, avis, vote, POL. <i>6, 15, 4</i>.<br><span><b>Étym</b>. βούλομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βουλημα - βούλημα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT).\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G1014":"<h1>boulomai</h1>\n<p>Strong n° 1014 <i>Prononciation [boo'-lom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>vouloir de propos délibéré, avoir un but</li>\n<li>vouloir avec affection, désirer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βούλομαι</b> <span>(<i>impf</i>. ἐϐουλόμην <i>ou</i> ἠϐουλόμην, <i>f</i>. βουλήσομαι, <i>ao</i>. ἐϐουλήθην <i>ou</i> ἠϐουλήθην, <i>pf</i>. βεϐούλημαι)</span><br><b>   I</b> vouloir, <i>en génér. et malgré de nombreuses except., plutôt au sens de</i> désirer, <i>p. opp. à</i> θέλω, <i>qui semble manquer plutôt l’idée de</i> vouloir <i>proprement dite :</i><br><b>      1</b> vouloir : τινί τι (Τρώεσσιν νίκην, IL. <i>7, 21 ; cf. 8, 204 ; 13, 347, etc</i>.) qqe chose pour qqn (la victoire pour les Troyens, <i>etc.) ; avec un inf</i>. HOM. ATT. : Τρώεσσιν κῦδος ὀρέξαι, IL. <i>11, 79,</i> vouloir procurer de la gloire aux Troyens ; <i>qqf. avec l’inf. fut</i>. THGN. <i>187 ; avec une prop. inf</i>. εἰ βόλεσθε (<i>épq</i>.) αὐτὸν ζώειν, OD. <i>16, 387,</i> si vous voulez qu’il vive ; <i>abs. avec une prép. marquant l’intention :</i> εἰς τὸ βαλανεῖον βούλομαι, AR. <i>Ran. 1279,</i> je veux aller au bain ; βούλεσθαι… μᾶλλον ἤ, vouloir… plutôt que, préférer, aimer mieux ; βουλήσει δειλὸς εἶναι μᾶλλον ἤ, SOPH. <i>Aj. 1314,</i> tu aimeras mieux être lâche que, <i>etc. ; sans</i> μᾶλλον, <i>mais avec un comparatif :</i> βούλομαι παρθενεύεσθαι πλέω χρόνον ἢ πατρὸς ἐστερῆσθαι, HDT. <i>3, 124,</i> je préfère rester fille longtemps encore, plutôt que d’être privée de mon père ; <i>sans comparatif, avec une prop. inf. :</i> βούλομ' ἐγὼ λαὸν σόον ἔμμεναι ἢ ἀπολέσθαι, IL. <i>1, 117,</i> je préfère voir mon peuple sauvé plutôt que perdu (<i>cf</i>. OD. <i>17, 81 ;</i> HDT. <i>3, 40, etc.) ; ou simpl. avec un inf</i>. OD. <i>9, 96 ; 15, 88, etc. ; qqf. avec</i> πολύ (<i>au lieu de</i> μᾶλλον) <i>et</i> ἤ, IL. <i>17, 331, etc. ; rar. avec</i> πολύ <i>sans</i> ἤ : πολὺ βούλομαι αὐτὴν οἴκοι ἔχειν, IL. <i>1, 112,</i> je préfère la garder chez moi ; <i>abs</i>. avoir une préférence pour, incliner vers, préférer : β. τὰ Συρακοσίων, THC. <i>6, 50,</i> se déclarer en faveur des Syracusains ;<br><b>      2</b> désirer, souhaiter : τι, IL. <i>3, 41,</i> qqe ch. (<i>cf</i>. OD. <i>11, 358 ; 20, 316) ; avec un inf</i>. IL. <i>1, 67 ; avec un sbj</i>. βούλει ἀναγνῶμεν ; PLAT. <i>Phædr. 228</i> e, veux-tu que nous lisions ? <i>avec un adv</i>. ἄλλῃ βούλεσθαι, IL. <i>15, 51,</i> souhaiter que qqe ch. arrive autrement ; <i>abs</i>. βουλοίμην ἄν, PLAT. <i>Euthyphr. 3</i> a, je voudrais, <i>càd</i>. je souhaiterais (qu’il en fût ainsi) ; <i>particul. dans les locut. ou construct</i>. εἰ δὲ βούλει, PLAT. <i>Conv. 201</i> a, si tu le désires, si cela te convient ; <i>formule de politesse pour marquer une concession ou une adhésion ;</i> εἰ σοὶ βουλομένῳ ἐστὶν ἀποκρίνεσθαι, PLAT. <i>Gorg. 448</i> d, s’il te convient de répondre (<i>cf. lat</i>. nobis volentibus) ; <i>subst</i>. τό τινος βουλόμενον, EUR. <i>I.A. 1270,</i> la faculté de vouloir, la volonté de qqn ; ὁ βουλόμενος, HDT. <i>1, 54 ;</i> ATT. (PLAT. <i>Gorg. 527</i> a, DÉM. <i>528, 26, etc</i>.) le premier venu, <i>litt</i>. celui qui le désire, à qui cela convient ; <i>cf</i>. ὃς βούλει, PLAT. <i>Gorg. 517</i> b ; ὅστις βούλει, PLAT. <i>Crat. 432</i> a, qui tu voudras, le premier venu ; τί βουλόμενος ; PLAT. <i>Phæd. 63</i> a ; DÉM. <i>285, 24 ;</i> τί βουληθείς, SOPH. <i>El. 1100,</i> dans quelle intention ? <i>litt</i>. voulant <i>ou</i> ayant voulu quoi ? ;<br><b>      3</b> <i>p. suite, avec des nuances de signif. diverses,</i> avoir l’intention de, montrer une tendance à, <i>etc. :</i> βούλεται εἶναι, PLAT. <i>Rsp. 595</i> c, CRAT. <i>412</i> c, <i>etc.,</i> il a la prétention d’être, il a une tendance à être, il n’est pas éloigné d’être, <i>à peu près au sens de</i> κινδυνεύει εἶναι ; <i>en parl. de choses :</i> ἡ τοῦ ὕδατος φύσις βούλεται εἶναι, <i>etc</i>. ARSTT. <i>Sens. 4, 4,</i> la nature de l’eau a pour caractère d’être, <i>etc. ; d’où</i> signifier, vouloir dire : τί ἡμῖν βούλεται τοῦτο ; PLAT. <i>Theæt. 156</i> c, que nous veut cela ? qu’est-ce que cela signifie ? (<i>cf. lat</i>. quid sibi vult hæc res ?) ;<br><b>   II</b> vouloir bien, consentir à : βούλει λάϐωμαι ; SOPH. <i>Ph. 762,</i> veux-tu que je prenne ? βούλει φράσω ; AR. <i>Eq. 36,</i> veux-tu que je dise ? εἰ βούλει, SOPH. <i>Ant. 1168 ;</i> XÉN. <i>An. 3, 4, 41,</i> si tu veux bien, s’il te plaît (<i>cf. lat</i>. sis = si vis).<br><span><b><span class=\"arrow\"></span></b> <i>Prés. 2 sg. att</i>. βούλει, THC. <i>6, 14 ;</i> SOPH. <i>Ant. 757 ; etc. ; ion</i>. βούλεαι, OD. <i>18, 364 ;</i> HDT. <i>1, 11 ; 3, 53, etc. ; impér. 2 sg. poét</i>. βούλεο, THGN. <i>145 ; sbj. 2 sg</i>. βουλῇ, AR. <i>Eq. 850, etc. ; épq</i>. βούλεαι, HÉS. <i>O. 647 (sel. d’autres,</i> βούληαι) ; <i>3 sg. épq</i>. βούλεται, IL. <i>1, 67 ; opt. 3 pl. ion</i>. βουλοίατο, HDT. <i>1, 4, etc. — Impf</i>. ἐϐουλόμην, IL. <i>11, 79 ;</i> HDT. <i>1, 165, etc. ;</i> ATT. (SOPH. <i>Ph. 1239 ;</i> THC. <i>3, 51 ;</i> XÉN. <i>An. 1, 1, 1, etc.) ou</i> ἠϐουλόμην, EUR. <i>Hel. 752 ;</i> XÉN. <i>Hell. 1, 1, 29 ;</i> ISOCR. DÉM. <i>etc. ; poét</i>. βουλόμην, IL. <i>23, 682 ; 3 pl. ion</i>. ἐϐουλέατο, HDT. <i>1, 4 ; 3, 143. Fut</i>. βουλήσομαι, HH. <i>2, 86 ;</i> ESCHL. <i>Pr. 867 ;</i> HDT. <i>1, 127 ;</i> THC. <i>1, 22 ; etc. Fut. réc</i>. βουληθήσομαι, ARSTD. <i>24, 292 (vulg</i>.) ; GAL. <i>13, 636. Ao</i>. ἐϐουλήθην, EUR. <i>Hipp. 476 ;</i> THC. <i>1, 34 ;</i> XÉN. <i>Hell. 2, 4, 8, etc. ; qqf</i>. ἠϐουλήθην, XÉN. <i>Hell. 4, 4, 8 (vulg.) ; Hipp. 3, 5 ;</i> ISOCR. DÉM. — <i>Poét. prés. 3 sg</i>. βόλεται, IL. <i>11, 319 ; 2 pl</i>. βόλεσθε, OD. <i>16, 387 ; impf. 3 pl</i>. ἐϐόλοντο, OD. <i>1, 234. — Éol</i>. βόλλομαι, <i>d’où part. prés</i>. βολλόμενος, DIUS (STOB. <i>Fl. 65, 16) ; impf</i>. ἐϐολλόμαν, THCR. <i>Idyl. 28, 15</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *g<sup>w</sup>el-, *g<sup>w</sup>ol-, vouloir, désirer.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βουλομαι - βούλομαι</font>\n<br><br>verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n34 fois dans 34 versets de 17 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n<li>Actes (12)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Timothée (3)</li>\n<li>Tite (1)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (3)</li>\n<li>2 Pierre (1)</li>\n<li>2 Jean (1)</li>\n<li>3 Jean (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G1015":"<h1>bounos</h1>\n<p>Strong n° 1015 <i>Prononciation [boo-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une colline, une éminence, un tertre, hauteur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βουνός, οῦ (ὁ)</b> colline, hauteur, <i>mot cyrénéen selon</i> HDT. <i>4, 158, 199 ;</i> ESCHL. PHILÉM. POL. STR. <i>etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βουνος - βουνός</font>\n<br><br>probablement origine étrangère</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G1016":"<h1>bous</h1>\n<p>Strong n° 1016 <i>Prononciation [booce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un bœuf, une vache</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βοῦς</b>, <i>gén</i>. <b>βοός (ὁ</b> <i>et</i> <b>ἡ) :<br>   I</b> bœuf, vache, HOM. <i>etc. ; sans indicat. de genre,</i> βοῦς <i>se prend en gén. au sens du fém. ; au sens du masc. Homère ajoute qqf. une épith</i>. βοῦς ἄρσην, IL. <i>7, 314 ;</i> OD. <i>19, 420, ou</i> ταῦρος βοῦς, IL. <i>17, 389,</i> bœuf mâle ; <i>au plur</i>. troupeau de bœufs, HOM. <i>etc. ; accompagné de certains déterminatifs, βοῦς désigne divers ruminants :</i> βοῦς ἄγριος, ARSTT. <i>H.A. 2, 1,</i> buffle (<i>bos bubalus</i>) ; βοῦς ἐν Συρίᾳ, ARSTT. <i>H.A. 9, 28,</i> zébu (<i>bos taurus zebu</i>) ;<br><b>   II</b> <i>p. ext</i>. ἡ βοῦς, peau de bœuf, <i>d’où :</i> bouclier recouvert de peau de bœuf, IL. <i>7, 238 ; 12, 105 ; 16, 636 ;</i> XÉN. <i>An. 5, 4, 12 ;</i><br><b>   III</b> <i>p. anal. ou fig. :</i><br><b>      1</b> ἡ βοῦς, génisse, <i>en parl. d’une femme,</i> PD. <i>P. 4, 142 ;</i> ESCHL. <i>Ag. 1125 ;</i><br><b>      2</b> ὁ βοῦς, bœuf, <i>en parl. d’un homme lourd et stupide,</i> MACH. (ATH. <i>349</i> c) ;<br><b>      3</b> sorte de poisson, <i>de l’espèce de la raie,</i> ARSTT. <i>H.A. 5, 5, 3 ;</i><br><b>      4</b> sorte de gâteau à cornes, CLITOD. (HSCH.) ;<br><b>      5</b> <i>prov</i>. <span>βοῦς ἐπὶ γλώσσῃ βέϐηκε</span>, THGN. <i>793 ;</i> ESCHL. <i>Ag. 36,</i> avoir reçu de l’argent pour se taire, <i>p.-ê. par allus. à une ancienne monnaie d’Athènes avec un bœuf pour empreinte ; cf</i>. PLUT. <i>Thes. 25</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Du radical βοϝ- dont le ϝ tantôt se vocalise</i> (βου-), <i>tantôt tombe</i> (βο-) <i>viennent les formes de déclin. régulières :</i> βοῦ-ς, βο-ός, βο-ΐ, βοῦ-ν, <i>etc. ; plur</i>. βό-ες, <i>d’où</i> βοῦς, βο-ῶν, βου-σί, βοῦς ; <i>duel (v. ci-dessous), et les formes suiv. : sg. nom. dor</i>. βῶς, THCR. <i>Idyl. 9, 7, gén. poét</i>. βοῦ, ESCHL. <i>fr. 430 ;</i> SOPH. <i>fr. 277. Acc. épq</i>. βῶν, IL. <i>7, 238 ; poét</i>. βόα, ANTH. <i>9, 255. Plur. dat. épq</i>. βόεσσι, IL. <i>12, 105 ; poét</i>. βοσί, ANTH. <i>7, 622. Acc</i>. βόας, IL. <i>12, 137, ou</i> βοῦς, SOPH. <i>Aj. 175 ; dor</i>. βῶς, THCR. <i>Idyl. 8, 48. Duel nomin.-acc</i>. βόε, IL. <i>13, 703 ;</i> OD. <i>13, 32 ;</i> HÉS. <i>O. 436</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *g<sup>w</sup>eh₃-u-, bœuf ; <i>cf. lat</i>. bōs, bŏvis ; <i>sscr</i>. gáuḥ.</span></span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βους - βοῦς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>Jean (2)</li>\n<li>1 Corinthiens (2)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G1017":"<h1>brabeion</h1>\n<p>Strong n° 1017 <i>Prononciation [brab-i'-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la récompense du vainqueur dans les jeux, prix du combat, un prix, prix décerné par le jury, récompense</li>\n<li>métaph : la récompense dans les cieux du caractère chrétien</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βραϐεῖον, ου (τὸ)</b> <span>[ᾰ]</span> prix du combat, NT. <i>1Cor. 9, 24</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. βραϐήϊον, OPP. <i>C. 4, 197</i>.<br><span><b>Étym</b>. βραϐεύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βραβειον - βραβεῖον</font>\n<br><br>vient de brabeus (un arbitre)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1018":"<h1>brabeuo</h1>\n<p>Strong n° 1018 <i>Prononciation [brab-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être un arbitre d'où administrer, décider de, juger de</li>\n<li>décider, déterminer</li>\n<li>diriger, contrôler, gouverner, régner, présider à, décider</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βραϐεύω</b> <span>(<i>f</i>. εύσω)</span> <span>[ᾰ]</span><br><b>      1</b> décerner le prix du combat, PLUT. <i>M. 960</i> a ;<br><b>      2</b> <i>p. suite,</i> juger comme arbitre, décider de, juger de, <i>acc</i>. DÉM. <i>36, 7 ;</i> PLUT. <i>Cic. 42, etc. ; abs</i>. ISOCR. <i>144</i> b ; <i>au pass</i>. ISOCR. <i>96</i> b ;<br><b>      3</b> <i>p. ext</i>. diriger, présider à, ANTH. <i>12, 56 ; part. en parl. des tribuns, à Rome,</i> présider à une élection, PLUT. <i>Cato mi. 44</i>.<br><span><b>Étym</b>. βραϐεύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βραβευω - βραβεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1019":"<h1>braduno</h1>\n<p>Strong n° 1019 <i>Prononciation [brad-oo'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tarder, être lent\n<ol type=\"a\">\n<li>ralentir, retarder</li>\n<li>traîner, flâner</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βραδύνω</b> <span>(<i>impf</i>. ἐϐράδυνον, <i>f</i>. βραδυνῶ, <i>ao</i>. ἐϐράδυνα, <i>pf. inus., pl.q.pf</i>. ἐϐεϐραδύκειν)</span> <span>[ᾰ, ῡ <i>excepté fut. et pl.q.pf</i>.]</span><br><b>   I <i>intr</i>.<br>      1</b> tarder, ESCHL. <i>Suppl. 730 ;</i> SOPH. <i>Ph. 1400 ; avec l’inf</i>. tarder à, PLAT. <i>Rsp. 528</i> d ;<br><b>      2</b> traîner en longueur, <i>en parl. d’une guerre,</i> APP. <i>Civ. 2, 47 ;</i><br><b>   II <i>tr.</i></b> retarder, SPT. <i>Esaï. 46, 13 ; au pass</i>. être retardé, être fait lentement <i>ou</i> être différé, SOPH. <i>O.C. 1628 ;</i> EL. <i>1501 ;</i><br><b><i>Moy.</i></b> tarder, ESCHL. <i>Sept. 623</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pl.q.pf. 3 sg</i>. ἐϐεϐραδύκει, LUC. <i>Laps. 20</i>.<br><span><b>Étym</b>. βραδύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βραδυνω - βραδύνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Timothée (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1020":"<h1>braduploeo</h1>\n<p>Strong n° 1020 <i>Prononciation [brad-oo-plo-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>naviguer lentement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βραδυ·πλοέω-οῶ</b>, <i>f</i>. οήσω <span>[ᾰῠ]</span> naviguer lentement, NT. <i>Ap. 27, 7 ;</i> ARTÉM. <i>344 Reiff</i>.<br><span><b>Étym</b>. βρ. πλόος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βραδυπλοεω - βραδυπλοέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1021":"<h1>bradus</h1>\n<p>Strong n° 1021 <i>Prononciation [brad-ooce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>lent</li>\n<li>métaph : ennuyeux, inactif, absorbé dans ses pensées\n<ol type=\"a\">\n<li>stupide, lent à saisir ou croire</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βραδύς, εῖα, ύ</b> <span>[ᾰ]</span><br><b>      1</b> lent, IL. <i>8, 104 ; p. opp. à</i> ὠκύς, OD. <i>8, 330 ; à</i> ταχύς, PLAT. <i>Tim. 80</i> a ; à ποδώκης, XÉN. <i>Cyn. 5, 17 ; avec un inf</i>. βρ. θείειν, IL. <i>23, 310 ;</i> λέγειν, EUR. <i>H.f. 237, etc</i>. lent à courir, à parler ; <i>en parl. du caractère,</i> lent, tranquille, indolent, <i>p. opp. à</i> ὀξύς, THC. <i>8, 96 ;</i> τὸ βραδὺ καὶ τὸ μέλλον, THC. <i>1, 84,</i> habitudes de lenteur et de temporisation ; <i>en parl. de l’intelligence, joint à</i> ἐπιλήσμων, AR. <i>Nub. 129 ; p. opp. à</i> ἀγχίνους, PLAT. <i>Phædr. 239</i> a ; <i>avec un inf</i>. προνοῆσαι βρ. THC. <i>3, 38,</i> lent à prévoir ;<br><b>      2</b> <i>p. suite,</i> tardif, HPC. <i>Progn. 44 ;</i> THC. <i>7, 43 ;</i> SOPH. <i>Tr. 395, etc</i>.<br><span>•<i> Cp</i>. βραδύτερος, HPC. <i>l. c. ;</i> THC. <i>4, 8 et 34 ; poét</i>. βαρδύτερος, THCR. <i>Idyl. 29, 30 ;</i> βραδίων, HÉS. <i>O. 526 ;</i> PLUT. <i>Fab. 12</i>. <i>• Sup</i>. βραδύτατος, XÉN. <i>l. c. ;</i> βράδιστος, AR. <i>fr. 324, ou</i> βάρδιστος ; IL. <i>23, 310, 530</i>.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *g<sup>w</sup>rd-u-, lent ; <i>cf. lat</i>. gurdus.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βραδυς - βραδύς</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – désœuvré, impliquant une action blâmable, répréhensible\n<br><br> – lent, paresseux, faisant référence à un moment, et non nécessairement dans un mauvais sens\n<br><br> – paresseux, descriptif de qualités constitutionnelles, et suggérant une critique</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jacques (2)</li>\n</ul>\n</td></tr>\n</table>","G1022":"<h1>bradutes</h1>\n<p>Strong n° 1022 <i>Prononciation [brad-oo'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lenteur, retard, relâchement, tarder, hésitation</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βραδυτής, ῆτος</b>, <i>mieux que</i> <b>βραδύτης, ητος (ἡ)</b> <span>[ᾰῠ]</span> lenteur, nonchalance, IL. <i>19, 411 ;</i> SOPH. <i>Ant. 932 ;</i> THC. <i>1, 71, etc. ; au plur</i>. ISOCR. <i>70</i> a ; DÉM. <i>308, 29 ; part</i>. lenteur d’esprit, PLAT. <i>Phæd. 109</i> c ; TH. <i>Char. 14 ;</i> DC.<br><span><b>Étym</b>. βραδύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βραδυτης - βραδύτης</font>\n<br><br>Voir définition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1023":"<h1>brachion</h1>\n<p>Strong n° 1023 <i>Prononciation [brakh-ee'-own]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le bras\n<ol type=\"a\">\n<li>le bras de Dieu, idiome Hébreu pour la puissance et le pouvoir de Dieu</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n① <b>βραχίων, ονος (ὁ)</b> <span>[ᾰῑ]</span><br><b>      1</b> bras, IL. <i>13, 529 ;</i> EUR. <i>Hec. 15 ;</i> PLAT. <i>Tim. 75</i> a, <i>p. opp. à</i> πῆχυς ; <i>synon. de</i> force, EUR. <i>Suppl. 478 ;</i> πρυμνὸς βρ. IL. <i>13, 532 ; 16, 323,</i> le haut du bras, l’épaule ;<br><b>      2</b> <i>p. ext</i>. épaule des animaux, ARSTT. <i>H.A. 8, 5, 4</i>.<br><span><b>Étym</b>. <i>p.-ê. apparenté à</i> βραχύς.</span><br><br>\n② <b>βραχίων</b>, <i>compar. de</i> .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βραχιων - βραχίων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1024":"<h1>brachus</h1>\n<p>Strong n° 1024 <i>Prononciation [brakh-ooce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>court, petit, peu de\n<ol type=\"a\">\n<li>endroit : courte distance</li>\n<li>temps : peu de temps, un instant</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βραχύς, εῖα, ύ</b> <span>[ᾰ]</span> court :<br><b>      1</b> <i>en parl. de l’espace, part. de la longueur :</i> βρ. οἶμος, PD. <i>P. 4, 248 ;</i> βρ. ὁδός, PD. <i>P. 9, 68 ;</i> PLAT. <i>Phædr. 272</i> a, court chemin, court trajet ; βρ. αἰχμή, HDT. <i>5, 49,</i> lance courte ; βρ. φάλαγξ, XÉN. <i>Cyr. 7, 5, 5, ou</i> τάξις, POL. <i>1, 38,</i> ligne de bataille peu profonde ; <i>adv</i>., βραχύ, XÉN. <i>An. 3, 3, 7, ou</i> ἐπὶ βραχύ, <i>An. 17,</i> à courte distance ; <i>en parl. de la hauteur :</i> βρ. μορφάν, PD. <i>I. 3, 71,</i> homme de petite taille, de courte stature ; βρ. τεῖχος, THC. <i>7, 29,</i> mur peu élevé ;<br><b>      2</b> <i>en parl. de la durée :</i> βρ. βίος, HDT. <i>7, 46,</i> vie courte ; βρ. χρόνος, ESCHL. <i>Pr. 939,</i> temps court ; ἔν τινι βραχεῖ χρόνῳ, PLAT. <i>Leg. 698</i> d, <i>ou simpl</i>. ἐν βραχέϊ (<i>ion</i>.) HDT. <i>5, 27 ;</i> ἐν βραχεῖ, PLAT. <i>Conv. 217</i> a ; <i>ou</i> διὰ βραχέος, THC. <i>2, 83,</i> en peu de temps ; κατὰ βραχύ, THC. <i>1, 64 ;</i> PLAT. <i>Soph. 241</i> c ; POL. <i>3, 88, 1 ; 4, 82, 2,</i> peu à peu ; <i>en parl. de la parole :</i> βρ. λόγος, ESCHL. <i>Pers. 713, etc</i>. discours bref ; ἐν βραχεῖ, PD. <i>P. 1, 82, etc. ;</i> κατὰ βραχύ, PLAT. <i>Prot. 329</i> b, en peu de mots, brièvement ; ἐν βραχυτάτῳ, XÉN. <i>Cyr. 1, 2, 15,</i> en très peu de mots, très brièvement ; <i>t. de pros</i>. bref, ARSTT. <i>Rhet. 3, 8, 6 ; Categ. 6, 3 ; Poet. 21, 25 ;</i> PLUT. <i>M. 737</i> e ; <i>etc. ;</i><br><b>      3</b> <i>en parl. du nombre, de la quantité :</i> βραχεῖς τινες ἱππεῖς, POL. <i>4, 19,</i> quelques rares cavaliers ; βραχέα φρᾶσαι, SOPH. <i>O.C. 570,</i> ne dire que peu de mots ; διὰ βραχέων, PLAT. <i>Gorg. 449</i> a ; <i>Prot. 336</i> a, en peu de mots, brièvement ; διὰ βραχυτάτων, PLAT. <i>Gorg. 449</i> e ; DÉM. <i>814, 4, etc. ;</i> ἐν βραχυτάτοις, ANT. <i>113, 21,</i> en très peu de mots, très brièvement ;<br><b>      4</b> <i>en parl. de la qualité :</i> petit, médiocre, humble, <i>en parl. de pers</i>. SOPH. <i>O.C. 880 ; p. opp. à</i> ὑψηλός, EUR. <i>Her. 613 ; en parl. de choses :</i> βρ. οὐσία, IS. <i>82, 23,</i> fortune médiocre ; βρ. κέρδος, LYS. <i>109, 41,</i> gain chétif ; ἔργον βρ. XÉN. <i>Cyr. 8, 2, 5,</i> œuvre sans importance ; λόγοι βραχεῖς, SOPH. <i>O.C. 294,</i> paroles insignifiantes ; βρ. πρόφασις, EUR. <i>I.A. 1180,</i> prétexte vain ; βραχὺ καὶ οὐδενὸς ἄξιον, THC. <i>8, 76,</i> chose vaine et sans valeur ; βραχὺ φροντίζειν τινός, DÉM. <i>212, 25,</i> s’inquiéter peu de qqe ch.<br><span>•<i> Cp</i>. βραχύτερος, XÉN. <i>Cyr. 7, 5, 5 ;</i> PLAT. <i>Prot. 334</i> e, <i>etc. ; ou</i> βραχίων, HSCH. CHOER. <i>etc. ; d’où</i> βράσσων (= *βράχϳων), IL. <i>10, 226</i>. <i>• Sup</i>. βραχύτατος, XÉN. PLAT. ANT. <i>ll. cc. etc. ; ou</i> βράχιστος, PD. <i>I. 5, 56 ;</i> SOPH. <i>O.C. 1115 ; Ant. 1327, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém. ion</i>. βραχέα, HDT. <i>5, 49</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *mr̥ǵ<sup>h</sup>ú-, court ; <i>cf. lat</i>. brevis, <i>sscr</i>. múhuḥ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βραχυς - βραχύς</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (2)</li>\n<li>Hébreux (3)</li>\n</ul>\n</td></tr>\n</table>","G1025":"<h1>brephos</h1>\n<p>Strong n° 1025 <i>Prononciation [bref'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un enfant à naître, un embryon, un fœtus</li>\n<li>un enfant nouveau-né, un nourrisson, un bébé</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βρέφος, εος-ους (τὸ) :<br>      1</b> enfant <i>ou</i> petit d’animal encore dans le sein de sa mère, IL. <i>23, 266 ;</i> PLUT. <i>M. 1052</i> e ; DIOSC. <i>5, 74, etc. ;</i><br><b>      2</b> enfant nouveau-né, PD. <i>O. 6, 33 ; P. 9, 24 ;</i> ESCHL. <i>Ag. 1096 ;</i> EUR. <i>Bacch. 289 ;</i> ἐκ βρέφεος, ANTH. <i>9, 567 ;</i> ἀπὸ βρέφους, NT. <i>2Tim. 3, 15,</i> dès la plus tendre enfance ; <i>en parl. des petits des animaux,</i> HDT. <i>3, 153 ;</i> EL. <i>N.A. 3, 8 ;</i> OPP. <i>H. 5, 464 ;</i> ATH. <i>607</i> a ;<br><b>      3</b> enfant déjà un peu grand, THCR. <i>Idyl. 15, 14</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ε̄φ]</span> THCR. <i>Idyl. 24, 7</i>.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *g<sup>w</sup>erb<sup>h</sup>- / *g<sup>w</sup>reb<sup>h</sup>-, enfant, petit.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βρεφος - βρέφος</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (5)</li>\n<li>Actes (1)</li>\n<li>2 Timothée (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1026":"<h1>brecho</h1>\n<p>Strong n° 1026 <i>Prononciation [brekh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>humecter, mouiller, arroser, tremper</li>\n<li>arroser de pluie, faire pleuvoir, tomber comme la pluie</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βρέχω</b> <span>(<i>impf</i>. ἔϐρεχον, <i>f. réc</i>. βρέξω, <i>ao</i>. ἔϐρεξα, <i>pf. inus. ; pass. f. réc</i>. βραχήσομαι, <i>ao</i>. ἐϐρέχθην, <i>ao.2</i> ἐϐράχην <span>[ᾰ]</span>, <i>pf</i>. βέϐρεγμαι)</span> mouiller :<br><b>   I</b> en plongeant dans un liquide (eau, vin, <i>etc</i>.) HDT. <i>3, 104 ;</i> XÉN. <i>An. 1, 4, 17 ;</i> PLAT. <i>Phædr. 229</i> a ; βρεχόμενοι πρὸς τὸν ὀμφαλόν, XÉN. <i>An. 4, 5, 2,</i> mouillés jusqu’au nombril, <i>en parl. de soldats qui traversent un fleuve ;</i><br><b>   II</b> en arrosant <i>ou</i> inondant, <i>part. :</i><br><b>      1</b> faire pleuvoir, SPT. <i>Gen. 2, 5 ; Ex. 16, 4 ;</i> θεῖον, SPT. <i>Gen. 19, 24,</i> du soufre ; <i>p. anal</i>. ἄρτους, SPT. <i>Ex. 9, 23,</i> des pains, <i>etc. ; abs</i>. NT. <i>Matth. 5, 45 ; au pass</i>. être mouillé par la pluie, POL. <i>16, 12, 3 ; impers</i>. βρέχει, il pleut, TÉLÉCL. (<i>Bkk. 291</i>) ; ARR. <i>Epict. 1, 6, 26 ;</i> SPT. NT. <i>etc. ; fig</i>. βρέχειν χρυσέαις νιφάδεσσι πόλιν, PD. <i>O. 7, 34,</i> inonder une ville de neige aux flocons d’or, d’une pluie d’or ; ἀκτῖσι βεϐρεγμένος, PD. <i>O. 6, 55,</i> inondé de lumière (<i>litt</i>. de rayons) ;<br><b>      2</b> mouiller de sueur ; PLAT. <i>Phædr. 254</i> c ;<br><b>      3</b> mouiller <i>ou</i> humecter (le gosier), <i>en parl. de buveurs,</i> ANTIPH. (ATH. <i>23</i> a) ; ANACR. <i>31, 12, etc. ;</i> μέθῃ βρεχθείς, EUR. <i>El. 326 ;</i> βεϐρεγμένος, EUB. (ATH. <i>23</i> a) gorgé de vin.<br><span><b><span class=\"arrow\"></span></b> <i>Act. impf. poét. 3 sg</i>. βρέχε, PD. <i>O. 7, 34. Fut. réc</i>. βρέξω, SIB. <i>5, 377, 508 ; 10, 200. Pass. fut.2 réc. 3 sg</i>. βραχήσεται, SPT. <i>Esaï. 34, 3. Ao.2</i> ἐϐράχην, ANACR. <i>31, 26 ;</i> ARSTT. <i>Probl. 12, 3, 6</i>.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *merg<sup>h</sup>-, mouiller, humidifier.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βρεχω - βρέχω</font>\n<br><br>mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (4)</li>\n<li>Jacques (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1027":"<h1>bronte</h1>\n<p>Strong n° 1027 <i>Prononciation [bron-tay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tonnerre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βροντή, ῆς (ἡ) :<br>      1</b> tonnerre, IL. <i>21, 199, etc. ; distinct de</i> κεραυνός, IL. <i>21, 198 ; joint à</i> ἀστραπή, SOPH. <i>fr. 507 ;</i> HDT. <i>3, 86 ; ou à</i> στεροπή, ESCHL. <i>Suppl. 35 ; à</i> φλὸξ κεραυνία, ESCHL. <i>Pr. 1017 ; au plur</i>. SOPH. <i>O.C. 1514 ;</i> AR. <i>Av. 1745 ;</i> PLAT. <i>Rsp. 397</i> a ;<br><b>      2</b> état d’un homme frappé de la foudre, stupeur, HDT. <i>7, 10, 15</i>.<br><span><b>Étym</b>. βρέμω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βροντη - βροντή</font>\n<br><br>parent à bremo (gronder)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 11 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Jean (1)</li>\n<li>Apocalypse (10)</li>\n</ul>\n</td></tr>\n</table>","G1028":"<h1>broche</h1>\n<p>Strong n° 1028 <i>Prononciation [brokh-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>aspersion, arrosage, pluie\n<ol type=\"a\">\n<li>utilisé pour une forte averse ou une violente tempête de pluie</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βροχή, ῆς (ἡ) :<br>      1</b> action de mouiller, DIOSC. <i>1, 59 ;</i> ORIB. <i>1, 429 ; 2, 254 ;</i><br><b>      2</b> pluie, NT. <i>Matth. 7, 25 ;</i> ORACL. (CLÉM. <i>66</i>) ; GEOP. <i>2, 19</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βροχη - βροχή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G1029":"<h1>brochos</h1>\n<p>Strong n° 1029 <i>Prononciation [brokh'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>nœud coulant, collet par lequel une personne ou une chose est saisie, ou suspendue</li>\n<li>jeter un nœud coulant sur quelqu'un : terme de chasse ou de guerre qui permet de forcer celui qui est saisi d'obéir à celui qui l'a pris au piège</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βρόχος, ου (ὁ) :<br>      1</b> lacet <i>ou</i> corde pour pendre <i>ou</i> étrangler, OD. <i>11, 278 ; 22, 472 ;</i> HDT. <i>4, 60 ;</i> ESCHL. <i>Suppl. 787 ;</i> SOPH. <i>Ant. 1222 ;</i> DÉM. <i>744, 6 ; p. ext</i>. corde à nœud coulant, <i>en gén</i>. PHIL. BYZ. ;<br><b>      2</b> <i>p. suite,</i> maille de filet, XÉN. <i>Cyn. 2, 5, etc. ;</i> EUR. <i>H.f. 729 ; d’où</i> lacet <i>ou</i> filet pour prendre les oiseaux, AR. <i>Av. 527 ;</i> PLAT. <i>Soph. 220</i> c ; <i>ou, en gén.,</i> pour les bêtes sauvages, EUR. <i>Hel. 1169</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[βρο̄]</span> <i>à l’arsis,</i> THGN. <i>1099</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βροχος - βρόχος</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1030":"<h1>brugmos</h1>\n<p>Strong n° 1030 <i>Prononciation [broog-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un grincement de dents\n<ol type=\"a\">\n<li>pour dénoter l'extrême angoisse et l'absolu désespoir des hommes condamnés à l'enfer éternel</li>\n</ol>\n</li>\n<li>grognement : sens de mordant</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βρυγμός, οῦ (ὁ) :<br>      1</b> morsure, EUP. <i>347 Kock ;</i> NIC. <i>Th. 716 ;</i><br><b>      2</b> grincement de dents, GAL. <i>Lex. Hipp. 19, 90 ;</i> SPT. <i>Prov. 19, 12 ;</i><br><b>      3</b> sorte de mets, EPHIPP. <i>fr. 13</i>.<br><span><b>Étym</b>. βρύκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βρυγμος - βρυγμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1031":"<h1>brucho</h1>\n<p>Strong n° 1031 <i>Prononciation [broo'-kho]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>moudre, aiguiser, grincer des dents</li>\n<li>mordre, mâcher</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βρύχω</b> (<i>seul. prés</i>.) <span>[ῡ]</span><br><b>      1 <i>tr.</i></b> faire grincer : τοὺς ὀδόντας, HPC. <i>593, 29, etc</i>. les dents ;<br><b>      2 <i>intr.</i></b> grincer des dents, HPC. <i>643, 42 ; en parl. des dents elles-mêmes,</i> grincer, HPC. <i>604, 20 ;</i><br><b><i>Moy.</i></b> (<i>seul. part. prés</i>. βρυχόμενος), rugir, mugir, LUC. <i>D. mar. 1, 4 ;</i> Q. SM. <i>14, 484</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *g<sup>w</sup>ruHǵ<sup>h</sup>-.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βρυχω - βρύχω</font>\n<br><br>mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1032":"<h1>bruo</h1>\n<p>Strong n° 1032 <i>Prononciation [broo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>abonder, jaillir, regorger de jus, faire sourdre</li>\n<li>produire abondamment, enfanter</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βρύω</b> <span>[ῠ]</span> (<i>seul. prés., impf</i>. ἔϐρυον <span>[ῠ]</span> <i>et fut</i>. βρύσω <span>[ῡ]</span>) ;<br><b>   I <i>intr</i>.<br>      1</b> sourdre avec force, pousser en abondance, <i>d’ord. en parl. de la végétation :</i> βρύων θαλλός, SOPH. <i>El. 422,</i> branche qui se couvre de bourgeons ; ἡ γῆ βρύει, XÉN. <i>Cyn. 5, 12,</i> la terre se couvre de végétation ; <i>avec un dat</i>. βρ. ἄνθεϊ, IL. <i>17, 56,</i> se couvrir de fleurs, <i>en parl. d’une branche ;</i> γῆ βρύουσα φυτοῖς, ARSTT. <i>Mund. 3, 1,</i> la terre qui se couvre de plantes ; <i>avec le gén</i>. χῶρος βρύων δάφνης, ἐλάας, ἀμπέλου, SOPH. <i>O.C. 16,</i> pays couvert de lauriers, d’oliviers, de vigne ; <i>fig</i>. βρ. μελίτταις καὶ προϐάτοις, AR. <i>Nub. 46,</i> regorger d’abeilles et de brebis ; ἀγαθοῖσι βρ. ESCHL. <i>Suppl. 966,</i> regorger de biens ; θράσει βρ. ESCHL. <i>Ag. 167,</i> déborder d’audace ;<br><b>      2</b> <i>p. ext</i>. être en ébullition, en fermentation, <i>d’où</i> s’enivrer, être ivre, MÉN. (PRISC. <i>Gr. lat. Keil, 2, p. 193, 2</i>) ;<br><b>   II <i>tr</i>.</b> faire pousser en abondance : ῥόδα, ANACR. <i>44, 2,</i> des roses.<br><span><b>⇒</b> <i>Fut</i>. SIB. <i>6, 8</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βρυω - βρύω</font>\n<br><br>un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G1033":"<h1>broma</h1>\n<p>Strong n° 1033 <i>Prononciation [bro'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ce qui est mangé, les aliments, nourriture, pâture</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βρῶμα, ατος (τὸ) :<br>   I</b> ce qu’on mange, <i>d’où :</i><br><b>      1</b> nourriture, aliment, HPC. <i>V. med. 9 ;</i> THC. <i>4, 26 ; p. opp. à</i> πῶμα, XÉN. <i>Mem. 4, 7, 9 ;</i> PLAT. <i>Criti. 115</i> b ;<br><b>      2</b> repas, PLAT. <i>Leg. 953</i> e ;<br><b>      3</b> <i>p. suite,</i> jouissance que procure un repas, <i>d’où fig</i>. jouissance exquise, AR. <i>fr. 313 Dind. ;</i><br><b>   II</b> ce qui est mangé <i>ou</i> rongé, <i>d’où :</i><br><b>      1</b> plaie produite par un ulcère, <i>d’où</i> ulcère, HPC. <i>1131</i> f ; <i>joint à</i> ἰός, SPT. <i>Bar. 6, 11 ;</i><br><b>      2</b> carie des dents, SPT. <i>Jer. 11 ;</i> DIOSC. <i>1, 141, etc. ;</i><br><b>   III</b> action de dévorer, SPT. <i>Sir. 51, 3</i>.<br><span><b>Étym</b>. βιϐρώσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βρωμα - βρῶμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n17 fois dans 15 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (6)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G1034":"<h1>brosimos</h1>\n<p>Strong n° 1034 <i>Prononciation [bro'-sim-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>mangeable, consommable</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βρώσιμος, ος, ον</b>, qu’on peut manger, mangeable, ESCHL. <i>Pr. 479 ;</i> DIPH. (<i>Bkk. 84, 25</i>) ; SPT. <i>Lev. 19, 23, etc. ;</i> NT. <i>Luc. 24, 41</i>.<br><span><b>Étym</b>. βιϐρώσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βρωσιμος - βρώσιμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1035":"<h1>brosis</h1>\n<p>Strong n° 1035 <i>Prononciation [bro'-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>action de manger\n<ol type=\"a\">\n<li>dans un sens élargi : corrosion</li>\n</ol>\n</li>\n<li>ce qui est mangé, aliment, nourriture\n<ol type=\"a\">\n<li>nourriture de l'âme, à la fois ce qui la rafraîchit et ce qui la nourrit</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βρῶσις, εως (ἡ) :<br>      1</b> nourriture solide, nourriture, HÉS. <i>Th. 797 ;</i> THC. <i>2, 70 ;</i> PLAT. <i>Leg. 783</i> c ; <i>p. opp. à</i> πόσις, OD. <i>15, 490 ;</i><br><b>      2</b> action de manger, HPC. <i>Acut. 388 ;</i> PLAT. <i>Rsp. 619</i> c, <i>etc. ; p. opp. à</i> πόσις, XÉN. <i>Mem. 1, 3, 15 ; fig</i>. action de ronger, érosion, <i>d’où</i> ce qui ronge, <i>particul</i>. rouille, <i>joint à</i> σής, NT. <i>Matth. 6, 19</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. ion</i>. -ιος, HÉS. <i>Th. 797</i>.<br><span><b>Étym</b>. βιϐρώσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βρωσις - βρῶσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 10 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Jean (4)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1036":"<h1>buthizo</h1>\n<p>Strong n° 1036 <i>Prononciation [boo-thid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>plonger dans les profondeurs, enfoncer, couler au fond</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βυθίζω</b> <span>[ῠ]</span> <span>(<i>ao</i>. ἐϐύθισα, <i>part. pf. pass</i>. βεϐυθισμένος)</span> enfoncer, plonger jusqu’au fond, DL. <i>5, 77 ;</i> GEOP. <i>20, 46, 5 ;</i> τριήρη, POL. <i>2, 10, 5,</i> submerger un navire ; <i>au pass</i>. s’enfoncer, être submergé, <i>en parl. de navires,</i> ARSTT. <i>Plant. 2, 2, 6 ;</i> D. CHR. <i>2, 325, etc. ; fig</i>. β. τινὰ εἰς ὄλεθρον, NT. <i>1Tim. 6, 9,</i> plonger qqn dans la ruine.<br><span><b>Étym</b>. βυθός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βυθιζω - βυθίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G1037":"<h1>buthos</h1>\n<p>Strong n° 1037 <i>Prononciation [boo-thos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le fond ou la profondeur de la mer</li>\n<li>la mer elle-même, la mer profonde, abîme</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βυθός, οῦ (ὁ)</b> <span>[ῠ]</span><br><b>      1</b> fond : καταφέρεσθαι εἰς βυθόν, ARSTT. <i>H.A. 9, 32, 5,</i> descendre au fond ; ἐκ βυθοῦ κηκῖον αἷμα, SOPH. <i>Ph. 783,</i> sang qui sort du fond d’une plaie : ἐν τῷ βυθῷ τῆς θαλάττης, ARSTT. <i>H.A. 4, 10, 5,</i> au fond de la mer ;<br><b>      2</b> <i>abs</i>. fond de la mer, fond de l’eau, ESCHL. <i>Pr. 432 ;</i> SOPH. <i>Aj. 1083 ;</i> AR. <i>Ran. 247, etc. ; d’où</i> abîmes de la mer, mer, ANTH. <i>11, 248 ;</i> LUC. <i>D. mar. 10, 2 ;</i><br><b>      3</b> <i>p. ext</i>. abîme, <i>en gén. ; fig</i>. βυθὸς ἀτεχνίης, HPC. <i>27, 10 ;</i> ἀθεότητος, PLUT. <i>M. 757</i> b, abîme de maladresse, d’impiété, <i>càd</i>. maladresse <i>ou</i> impiété profonde.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βυθος - βυθός</font>\n<br><br>une variante de </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1038":"<h1>burseus</h1>\n<p>Strong n° 1038 <i>Prononciation [boorce-yooce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un tanneur, un corroyeur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βυρσεύς, έως (ὁ)</b> corroyeur, tanneur, <i>mot réc. p</i>. βυρσοδέψης, ARTÉM. <i>4, 56 ;</i> NT. <i>Ap. 9, 43 ; 10, 6, 42</i>.<br><span><b>Étym</b>. βύρσα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βυρσευς - βυρσεύς</font>\n<br><br>vient de bursa (peau)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G1039":"<h1>bussinos</h1>\n<p>Strong n° 1039 <i>Prononciation [boos'-see-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>du fin lin (tissus)</li>\n<li>fait de fin lin (vêtement)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βύσσινος, η, ον</b>, fait du lin le plus fin (bandage, HDT. <i>2, 86, etc. ;</i> vêtement, ESCHL. <i>Pers. 125 ;</i> SOPH. <i>fr. 342 ;</i> ATH. <i>255</i> c).<br><span><b>Étym</b>. βύσσος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βυσσινος - βύσσινος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G1040":"<h1>bussos</h1>\n<p>Strong n° 1040 <i>Prononciation [boos'-sos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>byssus, une espèce de lin Egyptien</li>\n<li>lin fait de byssus, très coûteux, délicat, doux, blanc, mais aussi quelquefois de couleur jaune</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βύσσος, ου (ἡ) :<br>      1</b> byssus <i>ou</i> lin très fin de l’Inde, THCR. <i>Idyl. 2, 73 ; distinct de</i> λίνον <i>et de</i> κανναϐίς, PAUS. <i>5, 5, 2 ; 6, 26, 6 ;</i><br><b>      2</b> coton, STR. <i>693 ;</i> PHILSTR. <i>71</i>.<br><span><b>Étym</b>. <i>Orig. orientale</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βυσσος - βύσσος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1041":"<h1>bomos</h1>\n<p>Strong n° 1041 <i>Prononciation [bo'-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un lieu élevé\n<ol type=\"a\">\n<li>souvent un lieu pour offrir un sacrifice, un autel</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βωμός, οῦ (ὁ)</b> toute plate-forme élevée et servant de base <i>ou</i> de support, <i>d’où :</i><br><b>      1</b> estrade, IL. <i>8, 441 ;</i><br><b>      2</b> piédestal, socle (de statue) OD. <i>7, 100 ;</i> ANTH. <i>2, 1 ;</i><br><b>      3</b> <i>d’ord</i>. autel (<i>différent de l’</i>ἐσχάρα, <i>qui n’était pas élevé), dans Hom. d’ord. avec l’épith</i>. ἱερός <i>ou le gén</i>. θεῶν, Διός, <i>etc. ;</i> IL. <i>2, 305 ; 11, 808 ;</i> OD. <i>6, 162 ; 22, 334 ; abs</i>. ESCHL. <i>Eum. 305, etc. ;</i> SOPH. <i>O.R. 16, etc. ;</i> EUR. <i>Ion 1314 ;</i> PLAT. <i>Lys. etc. ;</i><br><b>      4</b> tumulus, <i>d’où</i> tombeau, ANTH. <i>App. 262</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *g<sup>w</sup>oh₂-mo-, être installé ; <i>cf</i>. βῆμα, βαίνω, βάσις, <i>etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βωμος - βωμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1042":"<h1>gabbatha</h1>\n<p>Strong n° 1042 <i>Prononciation [gab-bath-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Gabbatha = « tertre, crête, colline » = « dallage en mosaïque », « pavé »\n<ol><li>lieu élevé, élévation, tertre, (Lithostroton en grec)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γαββαθα</font> &lt; גבתא - <font face=\"Georgia\">Γαββαθᾶ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G1043":"<h1>Gabriel</h1>\n<p>Strong n° 1043 <i>Prononciation [gab-ree-ale']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Gabriel = « homme de Dieu »\n<ol><li>un des anges, prince ou chef (archange) des autres anges</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Γαϐριήλ (ὁ)</b> <i>indécl</i>. (l’archange) Gabriel, NT. <i>Luc. 1, 19, etc</i>.<br><span><b>Étym</b>. <i>n. hébreu</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Γαβριηλ</font> &lt; גבריאל - <font face=\"Georgia\">Γαβριήλ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G1044":"<h1>gaggraina</h1>\n<p>Strong n° 1044 <i>Prononciation [gang'-grahee-nah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une gangrène, un chancre, inflammation violente d'un membre du corps, en principe sans remède, le mal continuant jusqu'aux os</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γάγγραινα, ης (ἡ)</b> gangrène, NT. <i>2Tim. 2, 17 ;</i> DIOSC. <i>1, 74, 147 ;</i> GAL. <i>2, 97</i> f, <i>276</i> b.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γαγγραινα - γάγγραινα</font>\n<br><br>vient de graino (to gnaw)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G1045":"<h1>Gad</h1>\n<p>Strong n° 1045 <i>Prononciation [gad]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Gad = « troupe », « heureux »\n<ol><li>le septième fils du patriarche Jacob, par Zilpa, servante de Léa</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Γαδ</font> &lt; גד - <font face=\"Georgia\">Γάδ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1046":"<h1>Gadarenos</h1>\n<p>Strong n° 1046 <i>Prononciation [gad-ar-ay-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Géraséniens ou Gadaréniens (Angl. Gadarenes) = « récompensé à la fin »\n<ol><li>gens de Gadara ou Gérasa, vers le lac de Génésareth, à quelque distance du lac, sur les berges du fleuve Hieromax</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Γαδαρηνος - Γαδαρηνός</font>\n<br><br>vient de Gadara (ville à l'est du Jourdain)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G1047":"<h1>gaza</h1>\n<p>Strong n° 1047 <i>Prononciation [gad'-zah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>le trésor royal, trésor, richesse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γάζα, ης (ἡ) :<br>      1</b> le trésor du roi de Perse, <i>d’où</i> trésor royal (<i>aussi bien</i> le lieu du dépôt <i>que</i> le dépôt <i>même</i>), TH. <i>H.P. 8, 11, 5 ;</i> DS. <i>17, 35 ;</i> SPT. <i>2Esdr. 5, 17 ; 2, 7, 20 ;</i><br><b>      2</b> <i>p. ext</i>. grosse somme d’argent, POL. <i>11, 34, 12 ; 22, 26, 21, etc</i>.<br><span><b>Étym</b>. <i>Orig. persane</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γαζα - γάζα</font>\n<br><br>origine étrangère</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1048":"<h1>Gaza</h1>\n<p>Strong n° 1048 <i>Prononciation [gad'-zah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Gaza = « lieu fortifié ; le fort »\n<ol><li>une des cinq villes principales des Philistins en Palestine</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Γάζα, ης (ἡ)</b> Gaza :<br><b>      1</b> <i>v. de Palestine (auj</i>. Gaza), POL. <i>5, 68 ;</i> DS. <i>etc. ;</i><br><b>      2</b> <i>v. de Sogdiane,</i> ARR. <i>An. 4, 2, 1</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Γαζα</font> &lt; עזתה - <font face=\"Georgia\">Γάζα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1049":"<h1>gazophulakion</h1>\n<p>Strong n° 1049 <i>Prononciation [gad-zof-oo-lak'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>dépôt du trésor, spécialement du trésor public, le trésor</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γαζοφυλάκιον, ου (τὸ)</b> <span>[ῠᾰ]</span><br><b>      1</b> palais du Trésor, STR. <i>319 ;</i><br><b>      2</b> le Trésor, SPT. <i>4Reg. 23, 11, etc. ;</i> NT. <i>Luc. 21, 1</i>.<br><span><b>Étym</b>. γαζοφύλαξ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γαζοφυλακιον - γαζοφυλάκιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (3)</li>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G1050":"<h1>Gaios</h1>\n<p>Strong n° 1050 <i>Prononciation [gah'-ee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Gaïus = « seigneur »\n<ol>\n<li>un Macédonien qui accompagna Paul dans ses voyages</li>\n<li>un homme de Derbe qui vint avec Paul depuis Corinthe lors de son dernier voyage à Jérusalem</li>\n<li>un homme de Corinthe qui reçut Paul lors de son second séjour dans cette ville</li>\n<li>un Chrétien inconnu à qui la troisième épître de Jean est adressée</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Γάϊος, ου (ὁ)</b> = <i>lat</i>. Gaius <i>ou</i> Caius, <i>prénom rom</i>. POL. <i>2, 27, 28 ;</i> PLUT. <i>C. Gracch. 1, etc</i>.<br><span><b><span class=\"arrow\"></span></b> Γάϊος <span>[‒ ⏑ ⏑]</span> ANTH. <i>10, 19 ; 11, 92 et 100 ;</i> Γαῖος <span>[‒ ⏑]</span> ANTH. <i>9, 59</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Γαιος - Γάϊος</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>3 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G1051":"<h1>gala</h1>\n<p>Strong n° 1051 <i>Prononciation [gal'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>lait</li>\n<li>métaph : pour la difficulté du Chrétien à croire fermement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γάλα</b>, <i>gén</i>. <b>γάλακτος (τὸ)</b> <span>[γᾰ]</span><br><b>   I</b> lait, HOM. (IL. <i>4, 434 ;</i> OD. <i>4, 88, etc.) etc. ;</i> ἐν γάλακτι εἶναι, EUR. <i>H.f. 1269 ;</i> ἐν γάλακτι τρέφεσθαι, PLAT. <i>Tim. 81</i> c, <i>ou</i> ἐν γάλαξι τρέφεσθαι, PLAT. <i>Leg. 887</i> d, être au lait, être nourri au lait, <i>càd</i>. à la mamelle ; γάλα δοῦναι, XÉN. <i>Cyn. 7, 4,</i> donner le lait, allaiter ; <i>prov</i>. <span>γάλα ὀρνίθων</span>, AR. <i>Vesp. 508 ; Av. 733,</i> du lait d’oiseau, <i>càd</i>. chose merveilleuse (<i>v. ci-dessous) ; fig</i>. γάλα Ἀφροδίτης, AR. <i>fr. 490,</i> lait d’Aphrodite, <i>càd</i>. vin ; <i>p. ext</i>. lait de nourrice, <i>d’où</i> nourrice, ANTH. <i>7, 458 ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> suc laiteux de certaines plantes, ARSTT. <i>Plant. 2, 9, 11 ;</i> TH. <i>H.P. 6, 3, 4 ; etc. ;</i><br><b>      2</b> τὸ γάλα, la voie lactée, PARMÉN. <i>et</i> ANAXAG. (ARSTT. <i>Meteor. 1, 8, 4</i>) ;<br><b>      3</b> ὀρνίθων γάλα, NIC. (ATH. <i>371</i> c) <i>litt</i>. lait d’oiseau, <i>sorte de plante (cf. lat</i>. ornithogalum).<br><span><b><span class=\"arrow\"></span></b> <i>Gén</i>. γάλατος, EUST. <i>Od. 1761, 38 et 1818, 24 ; dat</i>. γάλατι, PHÉRÉCR. (ATH. <i>269</i> a), <i>sel. Mein. — Gén. invar</i>. τοῦ γάλα, PLAT. COM. (EUST. <i>Il. 961, 51</i>).<br><span><b>Étym</b>. <i>indo-europ</i>. *glkt, lait ; γάλα <i>pour proto-grec</i> *galakt, <i>d’où</i> *galak ; <i>cf. lat</i>. lac, <i>anc. lat</i>. lact ; <i>gén</i>. lactis = *glact, *glactis.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γαλα - γάλα</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (2)</li>\n<li>Hébreux (2)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1052":"<h1>Galates</h1>\n<p>Strong n° 1052 <i>Prononciation [gal-at'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un Galate : habitant de Galatie, province octroyée à des Gaulois</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Γαλάτης, ου</b> <span>[ᾰᾰ]</span><br><b>   I</b> <i>adj. m</i>. de Galatie, Galate, PLUT. <i>Mar. 39 ;</i> LUC. <i>28, etc. ;</i> APP. <i>Civ. 1, 50 ; etc. ;</i><br><b>   II</b> <i>subst</i>. οἱ Γαλάται :<br><b>      1</b> les Gaulois <i>en gén</i>. (de la Gaule transalpine <i>et</i> de la Gaule cisalpine), POL. <i>2, 21, 22, etc. ;</i> STR. <i>385 ;</i> PLUT. <i>Æmil. 9 ;</i> DC. <i>41, 36, etc. ; appelés collectiv</i>. Γ. ἑσπέριοι, LUC. <i>D. mort. 12, 2,</i> Gaulois de l’Occident ;<br><b>      2</b> <i>part</i>. les Galates <i>ou</i> Gaulois d’Asie Mineure : Γ. ἑῷοι, EL. <i>N.A. 17, 19,</i> Gaulois de l’Orient ; <i>ou</i> οἱ ἐκ τῆς Ἀσίας Γ., POL. <i>31, 2 ;</i> οἱ ἐν Ἀσίᾳ Γ., APP. <i>Syr. 50 ; etc</i>. Gaulois d’Asie ; <i>etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Γαλατης - Γαλάτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G1053":"<h1>Galatia</h1>\n<p>Strong n° 1053 <i>Prononciation [gal-at-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Galatie (Angl. Galatia) = « territoire des Gaulois, Gaule »\n<ol><li>province romaine de Galatie, habitée par les Galates, au centre de l'Asie Mineure, limitée par la Bithynie, le Pont, la Cappadoce, la Lycaonie, la Phrygie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Γαλατία, ας (ἡ)</b> <span>[ᾰᾰτ]</span><br><b>      1</b> Galatie, <i>contrée d’Asie Mineure,</i> STR. <i>566 ;</i> APP. <i>Civ. 2, 49, etc. ;</i><br><b>      2</b> Gaule (transalpine <i>et</i> cisalpine) PLUT. <i>Cæs. 18, 32 ; Pomp. 16 ;</i> APP. DC. <i>etc. ;</i> Γ. τογᾶτα, DC. <i>48, 12</i> = <i>lat</i>. Gallia tŏgāta ; Γ. κομᾶτα, DC. <i>46, 55</i> = <i>lat</i>. Gallia cŏmāta ; αἱ Γαλατίαι, DC. <i>53, 22,</i> les (deux) Gaules.<br><span><b>Étym</b>. Γαλάτης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Γαλατια - Γαλατία</font>\n<br><br>origine étrangère</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>2 Timothée (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1054":"<h1>Galatikos</h1>\n<p>Strong n° 1054 <i>Prononciation [gal-at-ee-kos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>pays habité par les Galates</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Γαλατικός, ή, όν</b> <span>[ᾰᾰ]</span> de Galatie <i>ou</i> de Gaule, ARSTT. <i>Mund. 3, 9 et 11 ;</i> POL. <i>2, 32, etc. ;</i> STR. <i>190, etc. ;</i> PLUT. <i>Cæs. 29, etc. ;</i> DC. <i>etc</i>.<br><span><b>Étym</b>. Γαλάτης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Γαλατικος - Γαλατικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G1055":"<h1>galene</h1>\n<p>Strong n° 1055 <i>Prononciation [gal-ay'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tranquillité, calme, tranquillité de la mer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γαλήνη, ης (ἡ)</b> <span>[ᾰ]</span><br><b>      1</b> calme de la mer, OD. <i>10, 94, etc. ;</i> γαλήνην ἐλαύνειν, OD. <i>7, 319,</i> sillonner une mer calme ; <i>particul</i>. absence de vent sur mer = νηνεμία, ARSTT. <i>Top. 1, 17, 1 ;</i> absence de vent <i>en génér., joint à</i> νηνεμία, PLAT. <i>Theæt. 153</i> c ; <i>à</i> ἐν εὐδίαις, ARSTT. <i>H.A. 4, 8, 15 ; fig</i>. calme, tranquillité, ATT., ESCHL. <i>Ag. 740 ;</i> SOPH. <i>El. 899 ; joint à</i> ἡσυχία, PLAT. <i>Leg. 791</i> a ; <i>cf</i>. PLUT. <i>Num. 20 ;</i> LUC. <i>Alex. 61 ;</i><br><b>      2</b> galène <i>ou</i> plomb sulfuré minéral, PLIN. <i>H.N. 33, 6 ;</i><br><b>      3</b> antidote contre la morsure des vipères, ANDROM. (GAL. <i>13, 875</i> b, <i>937</i> c).<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. γαλάνα <span>[ᾰᾱᾱ]</span> ESCHL. <i>l. c. ;</i> THCR. <i>Idyl. 6, 35 ; 22, 19</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *ǵlh₂-es-, rires, <i>litt</i>. « gaieté » ; <i>cf</i>. γελάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γαληνη - γαλήνη</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1056":"<h1>Galilaia</h1>\n<p>Strong n° 1056 <i>Prononciation [gal-il-ah'-yah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Galilée = « Circuit »\n<ol><li>nom d'une région du nord de la Palestine, limitée au nord par la Syrie, à l'ouest par Sidon, Tyr, Ptolémaïs et leurs territoires et le promontoire du Carmel, au sud par la Samarie et à l'est par le Jourdain. La région était divisée en Haute et en Basse Galilée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Γαλιλαία, ας (ἡ)</b> Galilée, <i>contrée du N. de la Palestine,</i> NT. <i>Matth. 4, 15 ;</i> STR. JOS. <i>etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Γαλιλαια</font> &lt; הגליל - <font face=\"Georgia\">Γαλιλαία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n63 fois dans 62 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (16)</li>\n<li>Marc (12)</li>\n<li>Luc (15)</li>\n<li>Jean (17)</li>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G1057":"<h1>Galilaios</h1>\n<p>Strong n° 1057 <i>Prononciation [gal-ee-lah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>originaire de Galilée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Γαλιλαῖος, α, ον</b>, de Galilée ; Γ. θάλασσα, NT. <i>Joh. 6, 1,</i> la mer de Galilée, <i>càd</i>. le lac de Tibériade ; οἱ Γαλιλαῖοι, NT. <i>Marc. 14, 70, etc</i>. les Galiléens ; <i>p. ext. synon. de</i> chrétien, LUC. <i>Philopatr. 12</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Γαλιλαιος - Γαλιλαῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 10 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (5)</li>\n<li>Jean (1)</li>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G1058":"<h1>Gallion</h1>\n<p>Strong n° 1058 <i>Prononciation [gal-lee'-own]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Gallion (Angl. Gallio) = « Celui qui vit du lait »\n<ol><li>Proconsul romain d'Achaïe à l'époque de la 1<sup>ère</sup> visite de Paul à Corinthe. Portait le nom de Junius Annaeus Gallio, était frère du philosophe Sénèque, et fut mis à mort, comme son frère, par Néron</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Γαλλίων, ωνος (ὁ)</b> = <i>lat</i>. Gallio, Gallion, <i>proconsul rom. d’Achaïe,</i> NT. <i>Ap. 18, 12</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Γαλλιων - Γαλλίων</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G1059":"<h1>Gamaliel</h1>\n<p>Strong n° 1059 <i>Prononciation [gam-al-ee-ale']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Gamaliel = « récompense de Dieu »\n<ol><li>Pharisien et célèbre docteur de la loi, qui donna un avis prudent au Sanhédrin concernant le traitement des disciples de Jésus de Nazareth (<a class=\"ref\" data-r=\"ACT5.34\">Actes 5.34</a>). Précepteur de Paul (<a class=\"ref\" data-r=\"ACT22.3\">Actes 22.3</a>).</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Γαμαλιήλ (ὁ)</b> <i>indécl</i>. Gamaliel, <i>n. hébreu,</i> NT. <i>Act. 22, 3</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Γαμαλιηλ</font> &lt; גמליאל - <font face=\"Georgia\">Γαμαλιήλ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G1060":"<h1>gameo</h1>\n<p>Strong n° 1060 <i>Prononciation [gam-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>contracter un mariage, prendre femme\n<ol type=\"a\">\n<li>se marier, épouser</li>\n<li>se donner en mariage</li>\n</ol>\n</li>\n<li>donner une fille en mariage</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γαμέω-ῶ</b> <span>(<i>impf</i>. ἐγάμουν ; <i>f</i>. γαμῶ, <i>postér</i>. γαμήσω ; <i>ao</i>. ἔγημα, <i>postér</i>. ἐγάμησα ; <i>pf</i>. γεγάμηκα ; <i>pass. fut. réc</i>. γαμηθήσομαι ; <i>ao</i>. ἐγαμέθην, <i>réc</i>. ἐγαμήθην ; <i>pf</i>. γεγάμημαι)</span> <span>[ᾰ]</span><br><b>   I <i>intr.</i></b> se marier, <i>en parl. de l’homme (mais voy</i>. I, 3) <i>d’où :</i><br><b>      1</b> épouser, prendre pour femme (<i>lat</i>. ducere uxorem), <i>abs</i>. OD. <i>4, 208 ;</i> οἱ γεγαμηκότες, XÉN. <i>Conv. 9, 7,</i> les hommes mariés ; <i>avec un acc. de pers</i>. γ. τινά, IL. <i>9, 388 ;</i> OD. <i>11, 179, etc</i>. prendre qqn pour femme ; γ. ἄλοχον, IL. <i>9, 399 ;</i> OD. <i>21, 72 ; ou</i> γυναῖκα, OD. <i>15, 241, m. sign. ; avec un acc. exprimant l’idée de mariage :</i> γάμον γαμεῖν, ESCHL. <i>Pr. 764, 909,</i> contracter mariage ; τόν τινος γάμον γ. EUR. <i>I.A. 467,</i> contracter mariage avec qqn ; γ. λέκτρα βασιλέως, EUR. <i>Med. 594,</i> épouser la fille du roi ; <i>avec un dat. exprimant l’idée de mariage :</i> γάμῳ γ. DÉM. <i>1002, 12,</i> s’unir par un mariage régulier ; <i>rar. avec doubl. acc. :</i> γάμους τοὺς πρώτους ἐγάμεε (<i>ion</i>.) Κύρου δύο θυγατέρας, HDT. <i>3, 88,</i> en premières noces il épousait deux filles de Cyrus ; <i>avec un rég. marquant l’origine :</i> γ. ἀπό τινος, EUR. <i>Andr. 976 ; ou</i> παρά τινος, PLAT. <i>Pol. 310</i> c ; <i>ou</i> ἔκ τινος, HDT. <i>6, 130,</i> prendre une femme dans la famille de qqn ; ἐκ μειόνων, XÉN. <i>Hier. 1, 28,</i> prendre femme dans une famille de condition inférieure, se mésallier ; <i>au même sens, direct. avec un gén</i>. Ἀδρήστοιο δ' ἔγημε θυγατρῶν, IL. <i>14, 121,</i> il épousa l’une des filles d’Adrèstos ; — <i>au pass</i>. être prise comme femme, être épousée, XÉN. <i>An. 4, 5, 24 ;</i> THCR. <i>Idyl. 8, 91 (v. ci-dessous</i>) ; PLUT. <i>Rom. 2, etc. ;</i><br><b>      2</b> prendre pour compagne, <i>en gén., sans idée de mariage,</i> OD. <i>1, 36 ;</i> LUC. <i>As. 32 ;</i> γ. βιαίως σκότιον λέχος, EUR. <i>Tr. 44,</i> contracter par la violence une union clandestine ;<br><b>      3</b> <i>ironiq. en parl. de la femme :</i> γαμοῦσα σε, EUR. <i>Med. 606,</i> en t’épousant (<i>Médée exprime ainsi son mépris pour Jason</i>) ;<br><b>   II</b> <i>trans. (seul. à l’ao</i>. ἐγάμησα) donner pour femme, MÉN. <i>4, 298 Meineke ;</i><br><b><i>Moy</i>. γαμέομαι-οῦμαι</b> (<i>fut</i>. γαμοῦμαι, <i>postér</i>. γαμήσομαι ; <i>ao</i>. ἐγημάμην) ;<br><b>   I <i>intr.</i></b> se marier, <i>en parl. de la femme et ironiq. de l’homme :</i><br><b>      1</b> <i>en parl. de la femme,</i> prendre pour époux, se donner en mariage (<i>lat</i>. nubere) : τινι, OD. <i>2, 113 ; 11, 273,</i> à qqn ; <i>p. opp. à</i> γαμεῖν (prendre pour femme) ESCHL. <i>fr. 11 ; ironiq. en parl. d’un mari docile :</i> οὐκ ἔγημεν ἀλλ' ἐγήματο, ANACR. <i>86,</i> il a pris non une femme, mais un mari (<i>cf. lat</i>. uxori nubere, MART. <i>8, 12) ; ou d’un mari pauvre épousant une femme riche,</i> ANTIPH. (<i>Bkk. 86</i>) ;<br><b>      2</b> <i>rar</i>. se donner à, <i>sans idée de mariage, en parl. de la femme,</i> CALL. <i>Del. 240 ;</i><br><b>   II</b> <i>tr. en parl. des parents,</i> marier sa fille, donner sa fille pour femme : τινι, IL. <i>9, 394 ;</i> EUR. <i>Med. 262,</i> à qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Act. Prés. ion. et épq. sans contract. : ind. 3 sg</i>. γαμέει, HDT. <i>6, 71 ; inf</i>. γαμέειν, OD. <i>15, 522 ; part</i>. γαμέων, OD. <i>4, 208. Impf. 3 sg. ion</i>. ἐγάμεε, HDT. <i>3, 88. Fut. épq. et ion</i>. γαμέω, IL. <i>9, 388, 391 ;</i> HDT. <i>5, 16 ; att</i>. γαμῶ, ESCHL. <i>Pr. 764 ;</i> SOPH. <i>O.R. 1500 ;</i> XÉN. <i>Cyr. 8, 4, 20 ; etc. ; fut. réc</i>. γαμήσω, PLUT. <i>M. 386</i> c ; ANTH. <i>11, 306 ;</i> LUC. <i>Rh. præc. 8, etc. Ao</i>. ἔγημα, IL. <i>14, 121, etc. ;</i> OD. <i>16, 34, etc. ;</i> HDT. <i>3, 88 ;</i> SOPH. <i>Tr. 460 ;</i> THC. <i>1, 128 ;</i> XÉN. <i>Cyr. 5, 2, 8 ; etc. ; dor. 3 sg. indic</i>. ἔγαμεν <span>[ᾱ]</span> PD. <i>N. 4, 65 ou</i> γᾶμεν), PD. <i>P. 3, 91 ;</i> THCR. <i>Idyl. 8, 93 ; inf. dor</i>. γᾶμαι, THCR. <i>Idyl. 3, 40 ; ao. réc</i>. ἐγάμησα, <i>au sens de</i> « prendre pour femme », DS. <i>2, 39 ;</i> LUC. <i>Luct. 13 ; D. deor. 5, 4 ; au sens de</i> « donner pour femme », MÉN. <i>l. c. Pf</i>. γεγάμηκα, HDT. <i>6, 43 ;</i> ATT. (AR. <i>Lys. 595 ;</i> PLAT. DÉM.). <i>Pl.q.pf. 3 sg</i>. ἐγεγαμήκει, THC. <i>1, 126. — Pass. fut. réc</i>. γαμηθήσομαι, APD. <i>2, 4, 7 ;</i> HLD. <i>5, 81 ;</i> DC. <i>58, 3, etc. Ao</i>. ἐγαμέθην, <i>d’où part. fém</i>. γαμεθεῖσα, THCR. <i>Idyl. 8, 91 (vulg.) ; ao. réc</i>. ἐγαμήθην, APD. <i>2, 1, 3 ;</i> DH. <i>11, 34 ;</i> PLUT. <i>Rom. 2 ; etc. Pf</i>. γεγάμημαι, XÉN. <i>An. 4, 5, 24 ;</i> DÉM. <i>954, 22. Pl.q.pf. 3 sg</i>. ἐγεγάμητο, APP. <i>Civ. 4, 23. — Moy. prés</i>. <b>γαμέομαι-οῦμαι</b>, HDT. <i>4, 117 ;</i> SOPH. <i>El. 594 ;</i> EUR. <i>Ion 58 ; inf. épq</i>. γαμέεσθαι, OD. <i>1, 275 ; 2, 113. Fut</i>. γαμοῦμαι, EUR. <i>Ph. 1673 ; Hel. 833 ;</i> AR. <i>Th. 900 ; épq. 3 sg</i>. γαμέσσεται, IL. <i>9, 394 (sel. Aristarque</i> γε μάσσεται) ; <i>fut. réc</i>. γαμήσομαι, PLUT. <i>Eum. 3 ; Artax. 26. Ao</i>. ἐγημάμην, HDT. <i>4, 117 ;</i> ATT. (IS. PLAT. DÉM. <i>etc.) ; d’où opt. 3 sg</i>. γήμαιτο, OD. <i>16, 392 ; 21, 162 ; inf</i>. γήμασθαι (<i>par élis</i>. γήμασθ'), OD. <i>2, 128, etc. ; part. fém</i>. γημαμένη, OD. <i>11, 273</i>.<br><span><b>Étym</b>. γάμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γαμεω - γαμέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n31 fois dans 25 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (5)</li>\n<li>Luc (7)</li>\n<li>1 Corinthiens (9)</li>\n<li>1 Timothée (3)</li>\n</ul>\n</td></tr>\n</table>","G1061":"<h1>gamisko</h1>\n<p>Strong n° 1061 <i>Prononciation [gam-is'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>donner ou prendre en mariage</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γαμίζω</b> <span>[ᾰ]</span> (<i>seul. prés</i>.) donner en mariage, DYSC. <i>Synt. 277 ;</i> NT. <i>Luc. 17, 27</i>.<br><span><b>Étym</b>. γάμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γαμισκω - γαμίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G1062":"<h1>gamos</h1>\n<p>Strong n° 1062 <i>Prononciation [gam'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fête du mariage, banquet de noces, cérémonies d'épousailles</li>\n<li>mariage, noces</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γάμος, ου (ὁ)</b> <span>[ᾰ]</span><br><b>   I</b> union, <i>d’où :</i><br><b>      1</b> union légitime, mariage, IL. <i>13, 382, etc. ;</i> OD. <i>18, 272 ; etc. ;</i> εἰς γάμον τινὸς ἐλθεῖν, EUR. <i>I.A. 1044,</i> épouser qqn ; ἄγειν τινὰ ἐπὶ γάμῳ, XÉN. <i>An. 2, 4, 8 ; ou</i> πρὸς γάμον, PLUT. <i>Cato ma. 24, m. sign., litt</i>. emmener une femme pour l’épouser ; γάμον γαμεῖν (<i>v</i>. γαμέω) ; γ. ἄγαμος (<i>v</i>. ἄγαμος) ; <i>souv. au plur. (cf. lat</i>. nuptiæ), ESCHL. <i>Pr. 559, 739, etc. ;</i><br><b>      2</b> union, relations intimes, <i>sans violence, mais sans idée de mariage,</i> DÉM. <i>270, 10 ; avec violence,</i> EUR. <i>Hel. 190 ;</i> union contre nature, LUC. <i>V.H. 1, 22 ;</i><br><b>   II</b> fêtes d’un mariage, noces : γάμον τεύχειν, OD. <i>1, 277, ou</i> ἀρτύειν, OD. <i>4, 770,</i> préparer la célébration d’un mariage ; γάμους ποιεῖν, DÉM. <i>869, 2 ; ou</i> ἐπιτελεῖν, DS. <i>13, 84,</i> célébrer un mariage ; ἱερὸς γάμος, ANAXANDR. (ATH. <i>242</i> d) le mariage sacré, <i>fête athénienne en l’honneur de Zeus et d’Hèra ; part</i>. festin pour un mariage, repas de noces ; γάμον δαινύναι, OD. <i>4, 3,</i> faire un repas de noces ; <i>au plur</i>. γάμους ἑστιᾶν, IS. <i>69, 35,</i> donner un repas de noces ; <i>joint à</i> εἰλαπίναι, IL. <i>18, 491 ;</i><br><b>   III</b> <i>p. ext. synon. de</i> épouse, SOPH. <i>Tr. 1139 au plur. ;</i> EUR. <i>Andr. 103 ;</i> DH. PLUT. ;<br><b>   IV</b> mariage, <i>nom que les Pythagoriciens donnaient aux nombres 5 et 6 (cf</i>. ἄγονος), PLUT. <i>M. 388</i> a, c ; THEOL. <i>24, 33, éd. Ast</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *ǵ(e)m-, se marier ; <i>cf</i>. γαμϐρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γαμος - γάμος</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 16 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Luc (2)</li>\n<li>Jean (2)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G1063":"<h1>gar</h1>\n<p>Strong n° 1063 <i>Prononciation [gar]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>car, parce que, en effet ...c'est que</li>\n<li>en effet, oui</li>\n<li>accompagnant une question : en effet, donc</li>\n<li>dans les injonctions : ainsi donc</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γάρ</b> <span>[ᾰ ; <i>v. ci-dessous</i>]</span> <i>conj. touj. placée après un mot,</i> car, en effet ;<br><b>A</b> <i>elle s’emploie :</i><br><b>   I. 1</b> <i>pour démontrer que ce qui vient d’être dit est naturel ou possible :</i> Ζεὺς πολλῶν πολίων κατέλυσε κάρηνα· τοῦ γὰρ κράτος ἐστὶ μέγιστον, IL. <i>2, 118,</i> Zeus a renversé les faîtes de beaucoup de villes ; car sa puissance est très grande ; ὧδε δὲ γνώσῃ ὅτι τἀληθῆ λέγω· εὑρήσεις γάρ, <i>etc</i>. PLAT. <i>Prot. 349</i> d, tu reconnaîtras ainsi que je dis vrai ; car tu trouveras, <i>etc. Elle se place qqf., comme par parenthèse, avant la propos. qu’elle explique :</i> Ἀτρείδη, πολλοὶ γὰρ τεθνᾶσιν Ἀχαιοί, τῷ σε χρὴ πόλεμον παῦσαι, IL. <i>7, 328,</i> fils d’Atrée, tant de Grecs sont morts déjà qu’il te faut cesser la guerre (<i>litt</i>. il te faut… car beaucoup de Grecs) ; εἶεν, σὺ γὰρ τούτων ἐπιστήμων, τί χρὴ ποιεῖν ; PLAT. <i>Phæd. 117</i> b, eh bien donc, car tu sais cela, que faut-il faire ? <i>Dans ce cas, le sujet de la propos. principale devient qqf. par attract. le rég. de la propos. où se trouve</i> γάρ : τῶν δὲ πᾶν γὰρ ἦν τὸ πλῆθος αὐτῶν μεταίτιον οὐκ ἐδέκοντο (<i>pour</i> οἱ δέ, πᾶν γὰρ ἦν…, οὐκ ἐδέκοντο), HDT. <i>4, 200,</i> ceux-ci, car toute la foule était leur complice, n’accueillaient pas, <i>etc. ;</i> τῇ δὲ κακῶς γὰρ ἔδεε γενέσθαι εἶπε (<i>pour</i> ἡ δέ, κακῶς γὰρ…, εἶπε), HDT. <i>9, 108,</i> celle-ci, car il fallait qu’il lui arrivât malheur, dit, <i>etc. ;</i> τῶν δὲ Ἀθηναίων ἔτυχε γὰρ πρεσϐεία ἐν τῇ Λακεδαίμονι παροῦσα, καὶ ὡς ᾔσθοντο (<i>pour</i> οἱ δὲ Ἀθηναῖοι, ἔτυχε γὰρ πρεσϐεία…, ὡς ᾔσθοντο), THC. <i>1, 72,</i> les Athéniens, car leur ambassade se trouvait justement à Lacédémone, apprenant que, <i>etc. ;</i><br><b>      2</b> <i>pour justifier une affirmation implicitement contenue dans ce qui vient d’être dit :</i> ἐπιστευόμην ὑπὸ τῶν Λακεδαιμονίων· οὐ γὰρ ἄν με ἔπεμπον πάλιν πρὸς ὑμᾶς (<i>s.-e</i>. εἰ μὴ ἐπίστευον), XÉN. <i>An. 7, 6, 33,</i> j’avais la confiance des Lacédémoniens, car autrement ils ne m’auraient pas renvoyé auprès de vous ; <i>particul. dans une réponse, pour confirmer une formule d’affirmation ou de négation exprimée ou sous-entendue :</i> οὔκουν ἀνάγκη ἐστί ; — ἀνάγκη γάρ, ἔφη, XÉN. <i>Cyr. 2, 1, 7,</i> n’est-ce pas chose nécessaire ? Oui, en effet, dit-il, cela est nécessaire ; καὶ δῆτ' ἐτόλμας τούσδ' ὑπερϐαίνειν νόμους ; — οὐ γάρ τί μοι, Ζεὺς ἦν ὁ κηρύξας τάδε, SOPH. <i>Ant. 449,</i> eh quoi ! tu as osé enfreindre ces lois ? — Certes, car pour moi ce n’est pas Zeus qui les a édictées ;<br><b>   II</b> <i>pour expliquer ce qu’on vient de faire entendre</i> (γάρ <i>correspond alors au français :</i> c’est que) : λεκτέα ἃ γιγνώσκω· ἔχει γὰρ ἡ χώρα πεδία κάλλιστα, XÉN. <i>An. 5, 7, 6,</i> je dois dire ce que je sais, c’est que le pays a des plaines magnifiques. <i>En ce sens γάρ est souvent annoncé par les locut</i>. τὸ δὲ μέγιστον, ὃ δὲ μέγιστον <i>ou</i> δεινότατον, <i>etc. :</i> τὸ δὲ πάντων σχετλιώτατον· οὓς γάρ, <i>etc</i>. ISOCR. le plus fâcheux de tout, c’est que ceux que, <i>etc. ;</i> ὃ δὲ πάντων ἀδικώτατον ἔδοξε· τῶν γὰρ προγεγραμμένων ἠτίμωσεν υἱούς, PLUT. ce qui parut le plus injuste de tout, c’est qu’il déclara infâmes les enfants des proscrits ; τούτου δὲ τεκμήριον· τόδε γάρ, HDT. <i>2, 58,</i> en voici la preuve, c’est que, <i>etc. ; de même, après les formules qui annoncent un avis, une explication, etc</i>. (σκέψασθε δέ, δῆλον δέ, μαρτύριον δέ, <i>etc</i>. examinez donc, cela est évident, et la preuve, <i>etc</i>.) ATT. ;<br><b>   III</b> <i>pour tirer une sorte de conclusion de ce qui vient d’être dit ou indiqué, au sens du français</i> donc, ainsi donc :<br><b>      1</b> <i>dans une propos. interrog. :</i> ποιμὴν γὰρ ἦσθα ; SOPH. <i>O.R. 1029,</i> tu étais donc pâtre ? ὄλωλε γὰρ δύστηνος ; SOPH. <i>O.C. 1583,</i> l’infortuné est-il donc mort ? δοκῶ γάρ σοι παίζειν ; PLAT. <i>Phædr. 234</i> d, te semble-t-il donc que je plaisante ? <i>part. dans les loc</i>. τίς γάρ ; τί γάρ ; ἦ γάρ ; <i>etc</i>. τίς γάρ σε θεῶν ἐμοὶ ἄγγελον ἦκεν ; IL. <i>18, 82,</i> quel dieu t’a donc envoyée vers moi en messagère ? τί γάρ ; SOPH. <i>O.C. 539, 542, etc</i>. quoi donc en effet ? <i>càd</i>. comment n’en serait-il pas ainsi ? cela doit être ; <i>au contraire,</i> πῶς γάρ ; πόθεν γάρ ; ATT. comment donc en effet, pourquoi donc en effet (cela serait-il) ? <i>càd</i>. cela ne peut pas être, cela est impossible ;<br><b>      2</b> <i>dans les propos. qui marquent un souhait :</i> κακῶς γὰρ ἐξόλοιο, EUR. <i>Cycl. 261,</i> puisses-tu donc périr misérablement ! <i>souv. en ce sens dans les loc. épq</i>. αἲ γάρ (<i>v</i>. αἴ), <i>att</i>. εἰ γάρ, εἴθε γάρ (<i>v</i>. εἰ, εἴθε), puissent donc les dieux, <i>etc</i>. ! (<i>cf. lat</i>. utinam) ;<br><b>B</b> <i>Rem. γάρ se joint, au même sens que dans l’une ou l’autre des constructions précédentes, à diverses particules :</i><br><b>      1</b> ἀλλὰ γάρ, mais en effet ; γάρ <i>explique une propos. à suppléer entre</i> ἀλλά <i>et</i> γάρ, <i>càd</i>. « mais (il n’en est pas ainsi), car », <i>etc. (cf. lat</i>. sed enim) : ἀλλ' οὐ γάρ σ' ἐθέλω βαλέειν λάθρῃ ὀπιπτεύσας, IL. <i>7, 243,</i> mais (ne crains pas), car je ne veux pas te frapper après t’avoir guetté en cachette ; <i>cf</i>. IL. <i>15, 739 ;</i><br><b>      2</b> γὰρ ἄρα, PLAT. <i>Prot. 309</i> c, <i>315</i> c ; γάρ ῥα, IL. <i>1, 113, 238 ;</i> OD. <i>3, 143, etc. ;</i> γὰρ δή, IL. <i>2, 301 ; 5, 383 ;</i> OD. <i>5, 23, etc. ;</i> HDT. <i>1, 34, etc. ;</i> γάρ νυ, OD. <i>14, 359,</i> oui certes, car (cela est) ; φάμεν γὰρ δή, PLAT. <i>Theæt. 187</i> e, oui certes, nous le disons, <i>litt</i>. nous (le) disons, car (cela est) certes ;<br><b>      3</b> γάρ που, PLAT. <i>Rsp. 381</i> c, <i>etc</i>. je le suppose, <i>litt</i>. « de qqe manière en effet » ;<br><b>      4</b> γάρ τε, IL. <i>1, 81 ;</i> OD. <i>1, 152, etc</i>. et en effet (<i>cf. lat</i>. etenim, namque) ;<br><b>      5</b> γάρ τοι, EUR. <i>Hel. 93 ; Suppl. 564,</i> car assurément ;<br><b>      6</b> γὰρ οὖν, IL. <i>15, 232 ;</i> HDT. <i>5, 34 ;</i> PLAT. <i>Theæt. 170</i> a ; γὰρ οὖν δή, PLAT. <i>Parm. 148</i> c, car en vérité, <i>pour confirmer ou expliquer ce qu’on vient de dire ;</i><br><b>      7</b> καὶ γάρ (<i>v</i>. καί).<br><span><b><span class=\"arrow\"></span></b> <span>[ᾱ]</span> <i>à l’arsis dans Hom. devant deux syllabes brèves,</i> IL. <i>2, 39, etc. ;</i> HH. <i>Cer. 57 ; rar. devant une longue</i> (Λητὼ γὰρ ἥλκησε), OD. <i>11, 580. — En poésie γάρ peut être le 3<sup>e</sup> ou le 4<sup>e</sup> mot de la prop. soit parce que les mots précédents sont étroitement liés par le sens</i> (ὁ μὲν γάρ, SOPH. <i>Aj. 764 ;</i> τὸ μὴ θέμις γάρ, ESCHL. <i>Ch. 641), soit par nécessité prosodique (3<sup>e</sup> mot,</i> ESCHL. <i>Ag. 222 ;</i> SOPH. <i>Ph. 219 ; 4<sup>e</sup> mot,</i> AR. <i>Av. 1545) ; qqf. même on le trouve 5<sup>e</sup></i> (MÉN. <i>dans</i> ATH. <i>132</i> d), <i>6<sup>e</sup></i> (SOPH. <i>Ph. 1451 ;</i> ANTIPH. <i>dans</i> ATH. <i>339</i> b), <i>7<sup>e</sup></i> (ALEX. <i>dans</i> ATH. <i>21</i> d). — <i>Il s’insère avant l’ι attique final : νυνγαρί pour</i> νυνὶ γάρ (<i>v</i>. νῦν).<br><span><b>Étym</b>. γέ, ἄρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γαρ - γάρ</font>\n<br><br>particule primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Conjonction</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1063 fois dans 1012 versets de 27 livres bibliques (NT)\n<ul>\n<li>Matthieu (127)</li>\n<li>Marc (73)</li>\n<li>Luc (96)</li>\n<li>Jean (65)</li>\n<li>Actes (85)</li>\n<li>Romains (145)</li>\n<li>1 Corinthiens (105)</li>\n<li>2 Corinthiens (78)</li>\n<li>Galates (36)</li>\n<li>Ephésiens (11)</li>\n<li>Philippiens (14)</li>\n<li>Colossiens (6)</li>\n<li>1 Thessaloniciens (24)</li>\n<li>2 Thessaloniciens (5)</li>\n<li>1 Timothée (14)</li>\n<li>2 Timothée (13)</li>\n<li>Tite (6)</li>\n<li>Philémon (3)</li>\n<li>Hébreux (91)</li>\n<li>Jacques (16)</li>\n<li>1 Pierre (10)</li>\n<li>2 Pierre (15)</li>\n<li>1 Jean (3)</li>\n<li>2 Jean (1)</li>\n<li>3 Jean (2)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (18)</li>\n</ul>\n</td></tr>\n</table>","G1064":"<h1>gaster</h1>\n<p>Strong n° 1064 <i>Prononciation [gas-tare']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le ventre</li>\n<li>la matrice</li>\n<li>l'estomac\n<ol type=\"a\">\n<li>gourmand, homme qui est comme s'il n'était qu'un estomac</li>\n</ol>\n</li>\n<li>femme enceinte (qui a le ventre)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γαστήρ</b>, <i>gén</i>. <b>γαστρός (ἡ) :<br>A</b> ventre :<br><b>   I</b> ventre <i>au sens génér</i>. IL. <i>13, 372 ; 17, 313, etc. ;</i><br><b>   II</b> ventre <i>pour</i> estomac, <i>comme organe de la digestion (lat</i>. venter) : βόσκειν γαστέρα, OD. <i>17, 228,</i> nourrir (<i>litt</i>. repaître) son ventre, se nourrir ; γαστέρι νέκυν πενθῆσαι, IL. <i>19, 225,</i> célébrer par un jeûne (<i>litt</i>. par le ventre) le deuil d’un mort ; — <i>p. ext. :</i><br><b>      1</b> <i>synon. de</i> envie de manger, appétit, faim, OD. <i>6, 133 ; 7, 216 ;</i> ἐν γαστρὸς ἀνάγκαις, ESCHL. <i>Ag. 726,</i> dans les nécessités de la faim ; γαστρὸς ἐγκρατής, XÉN. <i>Mem. 1, 2, 1,</i> qui maîtrise son appétit ; γαστρὸς ἥττων, <i>ibid. 1, 5, 1,</i> esclave de sa gourmandise ; γαστρὶ δουλεύειν, <i>ibid. 1, 6, 8 ; ou</i> χαρίσασθαι, <i>ibid. 2, 1, 2,</i> être l’esclave de son ventre, complaire à son ventre ;<br><b>      2</b> <i>synon. de</i> nourriture, manger, <i>p. opp. à</i> ποτός, XÉN. <i>Cyr. 1, 2, 8 ; à</i> οἶνος, XÉN. <i>Œc. 9, 11 ; Mem. 1, 5, 1 ;</i><br><b>   III</b> ventre <i>pour</i> sein, entrailles (<i>lat</i>. uterus) : ἐν γαστρὶ λαϐεῖν, ARSTT. <i>H.A. 9, 50, 8 ;</i> SPT. <i>Gen. 25, 21, ou</i> συλλαϐεῖν, SPT. <i>Ex. 2, 2,</i> concevoir : τινὰ γαστέρι φέρειν, IL. <i>6, 58 ;</i> ἐν γαστρὶ φέρειν, PLAT. <i>Leg. 792</i> e ; ἐν γαστρὶ ἔχειν, HDT. <i>3, 32 ;</i> SPT. <i>Gen. 16, 5, etc</i>. porter un enfant dans son sein ; ἐκ γαστρός, THGN. <i>305,</i> dès le sein de la mère, <i>càd</i>. dès la plus tendre enfance ; <i>au plur</i>. γυνὴ ἑπτὰ ἤδη γαστέρας δυστοκοῦσα, PHILSTR. <i>129,</i> femme ayant eu déjà sept couches malheureuses ;<br><b>B</b> <i>p. anal. :</i><br><b>      1</b> partie bombée d’un bouclier, TYRT. <i>11, 24 ;</i><br><b>      2</b> poche gonflée de chair préparée, boudin, saucisse, OD. <i>18, 44, 118 ; 20, 25 ;</i> AR. <i>Nub. 409 ;</i><br><b>      3</b> sorte de chou-rave, <i>c</i>. γογγυλίς, ATH. <i>369</i> a.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. et dat. sg. poét</i>. γαστέρος, OD. <i>17, 473 (mais</i> γαστρός, OD. <i>15, 344) ; dat</i>. γαστέρι, IL. <i>19, 225, etc. (mais</i> γαστρί, IL. <i>5, 539, 616 ; 17, 519</i>) ; EUR. <i>Cycl. 219. Dat. pl</i>. γαστράσι, DC. <i>54, 22 ; ion</i>. γαστῆρσι, HPC. <i>de Morb. 4, 27</i>.<br><span><b>Étym</b>. <i>incert</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γαστηρ - γαστήρ</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Tite (1)</li>\n<li>Livre</li>\n</ul>\n</td></tr>\n</table>","G1065":"<h1>ge</h1>\n<p>Strong n° 1065 <i>Prononciation [gheh]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>en effet, vraiment, au moins</li>\n<li>même</li>\n<li>voyant ceci, sans doute</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γε</b>, <i>particule enclitique, sert à attirer l’attention sur le mot ou la proposition à laquelle elle se rattache, et par suite marque :</i><br><b>   I</b> <i>une restriction,</i> du moins : Διός γε διδόντος, OD. <i>1, 390,</i> du moins si Zeus le permet ; κατά γε τὸν σὸν λόγον, XÉN. <i>Cyr. 3, 1, 18,</i> du moins à t’entendre dire ; <i>particul. après une propos. hypothétique :</i> εἰ πρὸς τοῦτο σιωπᾶν ἥδιόν σοι ἢ ἀποκρίνασθαι, τόδε γε εἰπέ, XÉN. <i>Cyr. 5, 5, 20,</i> s’il t’est plus agréable de te taire que de répondre à cela, dis au moins ceci ; <i>ou en relat. avec une propos. hypothétique :</i> φόϐον γε, εἰ μηδὲν μεῖζον, παρασχεῖν, PLAT. <i>Leg. 806</i> b, inspirer de la crainte, sinon qqe ch. de plus ; <i>en ce sens il se joint souv. aux conj</i>. εἰ, ἐάν (<i>ou</i> ἤν), ἄν, εἴπερ (<i>cf. lat</i>. si quidem) : εἴ γε σὺ ἀληθῆ λέγεις, PLAT. <i>Phædr. 242</i> d, si du moins (<i>ou</i> si toutefois) tu dis vrai ; εἰ μὴ κωφός γ' εἰμί, PLAT. <i>Gorg. 511</i> b, si toutefois je ne suis pas sourd ; ἢν ὠφελιμώτεροί γε ὦσι, XÉN. <i>Œc. 1, 14,</i> si toutefois ils sont plus avantageux ; ἂν δέ γε βούλῃ, PLAT. <i>Gorg. 448</i> a, si toutefois tu le veux ; εἴπερ γε ἄδικος, <i>ibid. 471</i> a, du moins s’il est injuste ; <i>aux pron</i>. εἰ σύ γε σῷ θυμῷ ἐθέλοις, IL. <i>23, 894,</i> si toi du moins tu le voulais bien dans ton cœur ; ὥς γ' ἐμοὶ ἔδοξε, PLAT. <i>Prot. 348</i> c, du moins à ce qu’il m’a semblé ; ἐπεὶ σοί γε δοκεῖ, PLAT. <i>Theæt. 173</i> c, puisque, pour toi du moins, c’est ton avis ; <i>à l’article :</i> τά γ' ἐν τοῖς βιϐλίοις, PLAT. <i>Phædr. 266</i> d, du moins ce qui est dans les livres ; <i>aux conj. :</i> οὐ μὲν σφῶΐ γ' ὀΐω πρίν γ' ἀποπαύσεσθαι, πρίν γε… αἵματος ἆσαι Ἀρῆα, IL. <i>5, 287,</i> je ne pense pas que vous cessiez (le combat) avant du moins que (l’un de vous deux) n’ait rassasié Arès de son sang ; <i>de même</i> πρὶν ἄν γε, AR. <i>Eq. 961, ou</i> πρίν γ' ἄν, AR. <i>Ran. 78 ;</i><br><b>   II</b> <i>une affirmation :</i><br><b>      1</b> à la vérité (<i>au sens de</i> μέν), <i>p. opp. à</i> δέ : σὺ δ' οὐ λέγεις γε, δρᾶς δέ, EUR. <i>Andr. 239,</i> pour toi, tu ne parles pas à la vérité, mais tu agis ;<br><b>      2</b> certes, assurément, en vérité : <i>dans le raisonnement : joint à un pron. relat</i>. οἷόν γέ μοι φαίνεται, PLAT. <i>Rsp. 329</i> a (je te dirai la chose) telle qu’en fait elle me paraît ; <i>à un adv</i>. οὐχ ὥς γε, SOPH. <i>Ant. 570,</i> non certes ainsi, certainement non ainsi, nullement ainsi à coup sûr ; <i>à une conj</i>. ὥσπερ γ' ἡ φάτις, SOPH. <i>O.R. 715,</i> comme en fait (avait dit) l’oracle, exactement comme, <i>etc. Dans ces constr. γε équivaut souv. à notre</i> puisque (<i>lat</i>. quippe, quippe qui, <i>etc.) ; avec un relat</i>. ὅς γε οὐδὲ γιγνώσκεις, PLAT. <i>Rsp. 343</i> a, toi qui en fait ne connais même pas, <i>etc., càd</i>. puisque tu ne connais même pas, <i>etc. (au sens du lat</i>. quippe qui) ; οἵ γέ σου καθύϐρισαν, SOPH. <i>Ph. 1364,</i> eux qui en fait se sont joués de toi, <i>càd</i>. (il faudrait nous dérober aux Atrides) puisqu’ils se sont joués de toi ; <i>avec un participe (au sens du lat</i>. quippe) : Ἀθηναῖός γε ὤν, PLAT. <i>Crat. 406</i> d, (tu n’oublieras pas Athèna) puisque tu es Athénien ; κρειττόνων γε ὄντων, PLAT. <i>Gorg. 488</i> e, (leurs lois ne sont-elles pas les meilleures,) puisqu’ils valent mieux ? <i>avec une conj</i>. ὁπότε γε, ἐπεί γε, ἐπειδή γε, <i>etc</i>. ATT. (SOPH. <i>O.C. 1699 ;</i> THC. <i>6, 18, etc</i>.) puisque en vérité (<i>lat</i>. quandoquidem). — <i>Particul. dans les propos. disjonctives, pour marquer plus fortement l’oppos., avec γε dans le 1<sup>er</sup> membre :</i> ἤτοι κεῖνόν γε δεῖ ἀπόλλυσθαι ἤ σε, HDT. <i>1, 11,</i> eh bien ! il vous faut périr ou celui-ci ou toi (<i>cf</i>. OD. <i>2, 132) ; dans le 2<sup>e</sup> membre :</i> εἰ θάνατον φύγοι ἢ ὅ γ' ὑπὸ μνηστήρων δαμείη, OD. <i>4, 789,</i> s’il a pu échapper à la mort ou s’il a été abattu par les prétendants ; <i>dans les deux membres :</i> ἢ σέ γε Μοῦσα ἐδίδαξε ἢ σέ γε Ἀπόλλων, OD. <i>8, 488,</i> c’est la Muse qui t’a enseigné, à moins que ce ne soit Apollon. — <i>Dans les réponses,</i> καὶ ἀληθῆ γε ἐρῶ, PLAT. <i>Gorg. 470</i> e, eh bien, je dirai la vérité telle qu’elle est ; πολλοῦ γε δεῖ οὕτως ἔχειν, PLAT. <i>Prot. 341</i> d, il s’en faut certes de beaucoup qu’il en soit ainsi ; <i>joint aux pron. personn</i>. ὀλεῖς με – οὔκουν ἔγωγε, SOPH. <i>Ph. 1388,</i> tu me perdras ; — moi ! certes non ; <i>à un adv</i>. μάλιστά γε, OD. <i>4, 366 ;</i> SOPH. <i>O.R. 994, etc. ;</i> πάνυ γε, σφόδρα γε, ATT. (PLAT. <i>Euthyphr. 8</i> e, <i>etc</i>.) tout à fait, absolument ; καλῶς γε, ὀρθῶς γε, ATT. parfaitement ; <i>avec une particule affirmative ou négative</i> (δή, μήν, μέν, τοι, οὖν, οὐδέν, <i>etc</i>.) : ἔδοξέ γε δή, PLAT. <i>Phædr. 277</i> b, oui, il m’a bien semblé ; μάλιστά γε δή, PLAT. <i>Soph. 237</i> b, certes parfaitement ; φαμέν γε μὴν οὕτως, PLAT. <i>Theæt. 208</i> e, nous sommes absolument de cet avis ; πάντως γε μήν, AR. <i>Eq. 232 ;</i> παντάπασί γε μήν, PLAT. <i>Tim. 20</i> d, tout à fait, absolument ; γε μέν, IL. <i>2, 703, 726 ;</i> HDT. <i>7, 152 ;</i> γε μὲν δή, ESCHL. <i>Ag. 661 ;</i> SOPH. <i>Tr. 484,</i> oui certes ; γέ τοι, AR. <i>Vesp. 934 ; Pl. 424, 1041,</i> certes à tout le moins ; γέ τοι δή, SOPH. <i>O.R. 1171 ;</i> PLAT. <i>Rsp. 476</i> e, oui, certes ; γε μέντοι, SOPH. <i>Ph. 93 ;</i> XÉN. <i>An. 2, 3, 9, etc</i>. sans doute, cependant ; φασί γε οὖν, PLAT. <i>Euthyd. 299</i> e, oui, on le dit ; εὖ γ' οὖν οἶδα, PLAT. <i>Hipp. ma. 292</i> e, certes, je le sais bien ; οὐδέποτέ γ', SOPH. <i>Ph. 999,</i> jamais certes ; οὐδὲ εἰκός γε, PLAT. <i>Crat. 406</i> d, certes, il n’y a pas apparence ; <i>etc. — Dans les exclamations, serments, etc</i>. οὔτοι μὰ τὴν Δήμητρά γ', AR. <i>Eq. 698,</i> non certes, par Dèmèter ; <i>cf</i>. AR. <i>Ach. 93, 836, etc. ;</i><br><b>      3</b> justement, précisément : φίλους τιθέντες τούς γε πολεμιωτάτους, EUR. <i>Hec. 848,</i> nous rendant amis justement les plus acharnés de nos ennemis ; ποίου δὲ τούτου πλήν γ' Ὀδυσσέως ἐρεῖς ; SOPH. <i>Ph. 441,</i> de qui vas-tu me parler là sinon justement d’Ulysse ? ;<br><b>      4</b> et même, bien plus : παρῆσάν τινες καὶ πολλοί γε, PLAT. <i>Phæd. 58</i> d, ils étaient là qqes-uns et même beaucoup ; <i>particul. dans les réponses :</i> ἔπεμψέ τίς σοι κρέα ; – καλῶς γε ποιῶν, AR. <i>Ach. 1049,</i> qqn t’a envoyé une provision de viandes ? — oui, et il a joliment fait ; <i>en ce sens avec le dernier terme d’une énumération :</i> οὔτε πόλις οὔτε πολιτεία οὐδέ γ' ἀνήρ, PLAT. <i>Rsp. 499</i> b, ni une ville, ni un gouvernement, ni même un homme ;<br><b>   III</b> <i>une conclusion :</i> eh bien donc ! donc : εἶμί γε, EUR. <i>H.f. 861,</i> eh bien donc, j’irai ! δρᾶ γ', εἴ τι δράσεις, EUR. <i>I.A. 817,</i> si tu veux faire qqe chose (entreprendre une action mémorable), fais-le donc, <i>ou</i> fais-le tout de suite ;<br><b>   IV</b> <i>Place de</i> γε : γε <i>suit d’ord. le mot qu’il détermine (v. la plupart des exemples préc.) ; p. suite, il peut se placer : avec un subst. accompagné de l’article, après l’article :</i> ὁ γ' ἐνθάδε λεώς, SOPH. <i>O.C. 43,</i> le peuple, au moins celui d’ici ; — <i>après un pron. possess</i>. ἐμόν γε θυμόν, IL. <i>20, 425 ; — après un relat</i>. ὅς γε, οἵ γε (<i>v. ci-dessus</i>) ; — <i>après un pron. interrog</i>. τίνα γε ; EUR. <i>Tr. 241,</i> qui donc ? — <i>dans les Com. entre le pron. démonstr. et la finale attique</i> ι : αὑτηγί, AR. <i>Ach. 784 ;</i> τουτογί, AR. <i>Vesp. 781 ; ttf</i>. ἐγγεταυθί (<i>pour</i> ἐνταυθί γε), AR. <i>Th. 646 ; — après une prép</i>. κατά γε τὸν σὸν λόγον (<i>v. ci-dessus</i>) ; — <i>dans les propos. où se trouve δέ, après ce</i> δέ : νῦν δέ γε, PLAT. <i>Theæt. 144</i> e ; — <i>après τε, lorsque τε se rattache étroitement au mot précéd. :</i> οἵ τέ γε, PLAT. <i>Gorg. 454</i> d ; οἷός τέ γε, XÉN. <i>Mem. 4, 5, 2 ;</i> PLAT. <i>Rsp. 412</i> b ; — γε <i>est qqf. répété dans les deux prop. corresp</i>. οὐ μὲν ὀΐω πρίν γε… πρίν γε, IL. <i>5, 287 (v. ci-dessus</i> I <i>vers la fin) ; ou même dans la même prop</i>. οὐδέν γ' ἄλλο πλήν γε καρκίνους, AR. <i>Vesp. 1507,</i> rien autre chose assurément que des crabes.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. γα, GR. COR. <i>p. 247 ; ttf. γε dans</i> PD. <i>et</i> THCR. ; <i>mais γα dans les composés</i> ἐγώνγα (<i>p</i>. ἔγωγε), AR. <i>Ach. 754 ; ou</i> ἔγωγα, THCR. <i>Idyl. 11, 25 ;</i> τύγα, THCR. <i>Idyl. 1, 148</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *ǵe, <i>particule emphatique ; cf. sscr</i>. ha, gha.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γε - γέ</font>\n<br><br>particule primaire de qualification (souvent avec d'autres préfixes)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Particule</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (4)</li>\n<li>Actes (3)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (3)</li>\n</ul>\n</td></tr>\n</table>","G1066":"<h1>Gedeon</h1>\n<p>Strong n° 1066 <i>Prononciation [ghed-eh-own']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Gédéon (Angl. Gideon) = « celui qui coupe, qui fait tomber »\n<ol><li>juge d'Israël qui les a délivrés des Madianites</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Γεδεών, ῶνος (ὁ)</b> JOS. <i>A.J. 5, 6, ou</i> Γεδεών (ὁ) <i>indécl</i>. NT. <i>Hebr. 11, 32,</i> Gédéon, <i>n. hébreu</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Γεδεων</font> &lt; גדעון - <font face=\"Georgia\">Γεδεών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1067":"<h1>geenna</h1>\n<p>Strong n° 1067 <i>Prononciation [gheh'-en-nah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>l'enfer est le lieu du châtiment futur appelé « Géhenne » ou « Géhenne de feu ». C'était à l'origine la vallée de l'Hinnon, au sud de Jérusalem, où les carcasses d'animaux étaient jetées et brûlées ; un symbole convenant aux méchants et à leur destruction future.</li></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γέεννα, ης (ἡ)</b> lieu de torture, NT. <i>Matth. 5, 22, etc</i>.<br><span><b>Étym</b>. <i>hébr</i>. gê-hinnôm, <i>litt</i>. la vallée d’Hinnôm, <i>représentée comme le lieu de l’expiation future</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γεεννα - γέεννα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (3)</li>\n<li>Luc (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G1068":"<h1>Gethsemane</h1>\n<p>Strong n° 1068 <i>Prononciation [gheth-say-man-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Gethsémané (Angl. Gethsemane) = « pressoir à huile »\n<ol><li>nom d'un lieu au pied du Mont des Oliviers, au delà du torrent du Cédron</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Γεθσημανι</font> &lt; גת־שמני - <font face=\"Georgia\">Γεθσημανί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G1069":"<h1>geiton</h1>\n<p>Strong n° 1069 <i>Prononciation [ghi'-tone]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un voisin</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γείτων, ων, ον</b>, <i>gén</i>. ονος :<br><b>   I</b> <i>subst</i>. voisin, voisine, OD. <i>4, 16 ; 9, 48 ;</i> HÉS. <i>O. 344 ; joint à</i> ὁ πλησίον, PLAT. <i>Theæt. 174</i> a ; <i>à</i> ὅμορος, LUC. <i>Tim. 43 ; p. opp. à</i> σύνοικος, PLAT. <i>Leg. 696</i> b ; ἐκ γειτόνων, PLAT. <i>Rsp. 531</i> a ; ANTIPH. (ATH. <i>571</i> f), <i>etc. ;</i> ἐκ τῶν γειτόνων, AR. <i>Pl. 435 ;</i> LYS. <i>93, 2,</i> dans le voisinage ; ἀπὸ γειτόνων, DS. <i>13, 84, m. sign. ;</i> ἐν γειτόνων οἰκεῖν, LUC. <i>Philops. 25,</i> habiter dans le voisinage ;<br><b>   II</b> <i>adj. :</i><br><b>      1</b> voisin (lieu, mer, ville, <i>etc</i>.) PD. <i>N. 9, 43 ; P. 1, 32 ;</i> ESCHL. <i>Pers. 67 ;</i> PLAT. <i>Leg. 877</i> a ; γ. τινός, EUR. <i>I.T. 1451 ;</i> XÉN. <i>An. 3, 2, 4 ; ou</i> τινί, EUR. <i>H.f. 1097 ;</i> XÉN. <i>An. 2, 3, 18 ;</i> PLAT. <i>Tim. 72</i> c, voisin de qqn <i>ou</i> de qqe ch. ;<br><b>      2</b> <i>fig</i>. voisin, analogue <i>ou</i> semblable : ἐν γειτόνων εἶναι, LUC. <i>Ic. 8,</i> être à peu près de même sorte.<br><span><b><span class=\"arrow\"></span></b> <i>Plur. neutre</i> γείτονα, ARSTT. <i>Plant. 2, 8, 8 ; contracté en</i> γείτω (<i>cf</i>. μείζονα <i>et</i> μείζω) <i>dans une inscr. att</i>. CIA. <i>2, 814, a, B, 36, 39 (374 av. J.C</i>.).<br><span><b>Étym</b>. γῆ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γειτων - γείτων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G1070":"<h1>gelao</h1>\n<p>Strong n° 1070 <i>Prononciation [ghel-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>rire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γελάω-ῶ</b> <span>(<i>impf</i>. ἐγέλων ; <i>fut</i>. γελάσομαι, <i>postér</i>. γελάσω ; <i>ao</i>. ἐγέλασα ; <i>pf. inus. ; pass. f</i>. γελασθήσομαι, <i>ao</i>. ἐγελάσθην, <i>pf. seul. en compos</i>.)</span><br><b>   I</b> <i>primit</i>. briller ; γέλασσε (<i>v. ci-dessous</i>) δὲ πᾶσα περὶ χθὼν χαλκοῦ ὑπὸ στεροπῆς, IL. <i>19, 362,</i> toute la terre alentour resplendit de l’éclat étincelant de l’airain ; γελᾷ δέ τε δώματα θεᾶν ὀπὶ λειριοέσσῃ, HÉS. <i>Th. 40,</i> et la demeure resplendit de l’éclat des déesses blanches comme le lis ; <i>p. anal. en parl. d’odeurs :</i> ὀδμῇ πᾶς τ' οὐρανὸς γαῖά τε πᾶσ' ἐγέλασσε, HH. <i>Cer. 14,</i> tout le ciel et toute la terre sont comme illuminés par le parfum (des fleurs) ;<br><b>   II</b> <i>p. suite, et p. anal. :</i><br><b>      1</b> (<i>à cause de la joie qui illumine le visage</i>) rire, <i>absol</i>. HOM. (IL. <i>21, 408, etc.) ; avec un adj</i>. γ. ἡδύ, ἁπαλόν, ἀχρεῖον, δακρυόεν, <i>etc</i>. HOM. (<i>v. ces mots</i>) ; γ. χείλεσιν, IL. <i>15, 101,</i> rire des lèvres, <i>càd</i>. d’un rire contraint ; γέλασαν δ' ἐπὶ πάντες Ἀχαιοί, IL. <i>23, 840,</i> et tous les Grecs en rirent ; <i>avec un suj. de chose :</i> ἐγέλασσε δέ οἱ φίλον ἦτορ, IL. <i>21, 389,</i> et son cœur se réjouit (<i>litt</i>. fut riant) ; <i>cf</i>. OD. <i>9, 413 ; avec un rég. de pers. :</i> γ. ἐπί τινι, IL. <i>2, 270 ; 23, 784 ;</i> OD. <i>20, 374, etc. ;</i> ESCHL. <i>Eum. 560 ; etc. ;</i> γ. τινα, THCR. <i>Idyl. 20, 1 ; rar</i>. γ. τινος, SOPH. <i>Ph. 1125 ;</i> γ. ἐπί τινος, XÉN. <i>Cyr. 1, 4, 4,</i> rire de qqn ; <i>avec un rég. de chose :</i> γ. ἐπί τινι, XÉN. <i>Mem. 4, 2, 5 ; Conv. 2, 18 ;</i> γ. τινι, SOPH. <i>Aj. 957 ;</i> AR. <i>Nub. 560, etc. ; ou</i> τι, XÉN. <i>Conv. 2, 19 ;</i> AR. <i>Nub. 820,</i> rire de qqe ch. ; <i>d’où, au pass.,</i> être un objet de dérision, être l’objet des railleries : πρός τινος, SOPH. <i>Ph. 1023 ;</i> παρά τινος, SOPH. <i>O.C. 1423,</i> de qqn ; <i>abs</i>. ESCHL. <i>Eum. 789 ;</i> SOPH. <i>Ant. 838 ;</i><br><b>      2</b> être riant, <i>en parl. de la terre, du ciel, etc. (cf. ci-dessus</i> I) A. RH. <i>4, 1171 ;</i> Q. SM. <i>6, 3 ; d’une mer calme,</i> ALCIPHR. <i>3, 1</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. Prés. épq</i>. γελόω, OD. <i>21, 105 ; inf. ion</i>. γελῆν, HPC. <i>Ep. 9, 338 Littré (mais</i> γελᾶν, HDT. <i>1, 99) ; part. épq. plur</i>. γελόωντες, OD. <i>20, 374, ou</i> γελώοντες, OD. <i>18, 111 ; 3 pl. dor. prés. ind</i>. γελᾶντι (<i>vulg</i>. γελεῦντι) THCR. <i>Idyl. 1, 89 ; fém. nomin. sg</i>. γελᾶσα (<i>vulg</i>. γελεῦσα) THCR. <i>Idyl. 1, 36 ; ou</i> γελάοισα (<i>sel. d’autres,</i> γελόωσα) THCR. <i>Idyl. 1, 95, 96. — Impf. épq</i>. γελώων (<i>var</i>. γελοίων) OD. <i>20, 347. — Fut. att</i>. γελάσομαι <span>[ᾰ]</span> XÉN. <i>Conv. 1, 16 ;</i> PLAT. PLUT. LUC. <i>etc. ; postér</i>. γελάσω <span>[ᾰ]</span> ANTH. <i>5, 179 ; 11, 29 ;</i> ANACR. <i>38, 8 ;</i> ATH. SYN. GAL. <i>etc. ; poét</i>. γελάσσω, SIB. <i>1, 182. — Ao. poét</i>. ἐγέλασσα, IL. <i>21, 389 ;</i> THGN. <i>9 ;</i> THCR. <i>Idyl. 20, 1, 15 (vulg</i>. ἐγέλαξα) ; <i>ou</i> γέλασα <span>[ᾰσ]</span> IL. <i>23, 840 ;</i> EUR. <i>I.T. 1274, Hel. 1349 ; ou</i> γέλασσα, IL. <i>2, 270 ; 15, 101 ; part. poét</i>. γελάσσας, IL. <i>11, 378 ; dor</i>. γελάσσαις, PD. <i>P. 9, 38 ; éol</i>. γελαίσας, SAPPH. <i>2, 5. — Pass. f. réc</i>. γελασθήσομαι, DL. <i>1, 4, 4 ;</i> LUC. <i>Am. 2. Ao</i>. ἐγελάσθην, THC. <i>3, 83 ;</i> PLAT. ISOCR. DÉM. <i>etc. Pf. et pl.q.pf. en compos. 3 sg.,</i> καταγεγέλασται, LUC. <i>D. mort. 1, 1 ;</i> κατεγεγέλαστο, LUC. <i>Ic. 19</i>.<br><span><b>Étym</b>. <i>pour</i> *γελάσ-ϳω, <i>de la R. indo-europ</i>. *gelh₂-, rire.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γελαω - γελάω</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G1071":"<h1>gelos</h1>\n<p>Strong n° 1071 <i>Prononciation [ghel'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un rire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γέλως, ωτος (ὁ) :<br>   I</b> le rire :<br><b>      1</b> <i>au propre,</i> γ. πολύς, XÉN. <i>Cyr. 2, 3, 18 ;</i> μέγιστος, PLAT. <i>Pol. 295</i> e, <i>ou</i> ἰσχυρός, PLAT. <i>Rsp. 388</i> e, grand, très grand <i>ou</i> fort éclat de rire ; ἄσϐεστος δ' ἄρ' ἐνῶρτο γέλως θεοῖσι, IL. <i>1, 599,</i> alors un rire inextinguible s’éleva parmi les dieux ; γ. γίγνεται, ATT. le rire naît ; γέλων <i>ou</i> γέλωτα παρέχειν, OD. <i>20, 8 ;</i> XÉN. <i>Cyr. 2, 2, 13 ; etc. ;</i> ποιεῖν, XÉN. <i>Cyr. 2, 2, 11 ;</i> PLAT. <i>Charm. 155</i> b ; κινεῖν, XÉN. <i>Conv. 1, 14 ;</i> παρασκευάζειν, PLAT. <i>Leg. 669</i> b ; τιθέναι, EUR. <i>Ion 1172,</i> faire naître, exciter <i>ou</i> provoquer le rire ; ὀφλισκάνειν, AR. <i>Nub. 1035,</i> faire rire à ses dépens ; ξυντιθέναι, SOPH. <i>Aj. 303 ;</i> ἄγειν, <i>ibid. 382,</i> prolonger le rire, rire largement <i>ou</i> longuement ; κατέχειν γέλωτα, XÉN. <i>Cyr. 2, 2, 5,</i> contenir <i>ou</i> réprimer le rire ; ἐπὶ γέλωτι, HDT. <i>9, 82 ;</i> AR. <i>Ran. 404,</i> pour provoquer le rire ; σὺν γέλωτι, XÉN. <i>An. 1, 2, 17 ;</i> ἅμα γέλωτι, PLAT. <i>Leg. 789</i> d ; μετὰ γέλωτος, PLUT. <i>Mar. 18,</i> en riant ;<br><b>      2</b> <i>en mauv. part,</i> sujet de rire, objet de risée : γέλωτα τίθεσθαί τι, HDT. <i>3, 29 et 38, ou</i> ἀποδεῖξαι, PLAT. <i>Theæt. 166</i> a ; ἐν γέλωτι ποιεῖσθαί τι, LUC. <i>H. conscr. 32,</i> faire de qqe. ch. un objet de risée ; ἐς γέλωτά τι τρέπειν, AR. <i>Vesp. 1260 ;</i> THC. <i>6, 53 ;</i> εἰς γέλωτά τι ἐμϐάλλειν, DÉM. <i>151, 19,</i> tourner qqe ch. en dérision ; γέλωτα γίγνεσθαί τινι, SOPH. <i>O.C. 902,</i> devenir un objet de risée pour qqn ; γέλως ἐσθ' ὡς χρώμεθα τοῖς πράγμασι, DÉM. <i>47, 6,</i> c’est une dérision que de manier ainsi nos affaires ; <i>cf</i>. DÉM. <i>185, 18 ;</i><br><b>   II</b> <i>p. anal. avec les plis que le rire dessine sur le visage,</i> plis <i>ou</i> rides que dessinent les vagues, OPP. <i>H. 4, 334</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dat. épq</i>. γέλῳ (<i>de l’éol</i>. γέλος, <i>sel</i>. GR. COR. <i>p. 608</i>), OD. <i>18, 100. Acc. épq</i>. γέλων, OD. <i>18, 350 (var. γέλω dans un seul ms.) ; 20, 8, 346 ; acc. poét</i>. γέλων, SOPH. <i>Aj. 303 ;</i> EUR. <i>Ion 1172, etc. ; postér. en prose,</i> PALÆPH. <i>31, 6 ;</i> POLYEN <i>1, 34. Plur. gén</i>. γελώτων, PLAT. <i>Leg. 732</i> c.<br><span><b>Étym</b>. γελάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γελως - γέλως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G1072":"<h1>gemizo</h1>\n<p>Strong n° 1072 <i>Prononciation [ghem-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>remplir</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γεμίζω</b> <span>(<i>f</i>. ίσω, <i>att</i>. ιῶ, <i>ao</i>. ἐγέμισα, <i>pf. inus. ; pass. part. ao</i>. γεμισθείς, <i>pf</i>. γεγέμισμαι)</span> remplir :<br><b>      1</b> <i>avec le gén. de la chose dont on remplit, en parl. de la cargaison d’un navire :</i> γ. τινός, THC. <i>7, 53 ;</i> XÉN. <i>Hell. 6, 2, 25 ;</i> DÉM. <i>569, 4,</i> remplir (un navire) de qque ch. ; <i>d’où au pass</i>. être lesté, DÉM. <i>466, 28 ; en gén</i>. remplir (un vase, une coupe) de, <i>gén</i>. ESCHL. <i>Ag. 443 ;</i> ARR. <i>Epict. 2, 20, 3 ; au pass</i>. être lesté, être gorgé (de nourriture, de vin, <i>etc.), en parl. des Cyclopes,</i> EUR. <i>Cycl. 505 ; d’abeilles,</i> ARSTT. <i>H.A. 9, 40, 14 ;</i><br><b>      2</b> <i>postér. avec l’acc. de la chose dont on remplit :</i> γ. ὕδωρ, PAUS. <i>3, 13, 2,</i> remplir (un vase) d’eau ; <i>au pass</i>. οἶνον, πῦρ γεμισθείς, ANTH. <i>12, 85,</i> rempli de vin, de feu.<br><span><b>Étym</b>. γέμω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γεμιζω - γεμίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 8 versets de 4 livres bibliques (NT)\n<ul>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Jean (3)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G1073":"<h1>gemo</h1>\n<p>Strong n° 1073 <i>Prononciation [ghem'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être rempli, plein</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γέμω</b> (<i>seul. prés. et impf</i>. ἔγεμον) être plein, <i>particul</i>. être chargé <i>ou</i> lesté, <i>en parl. d’un navire,</i> HDT. <i>8, 118 ;</i> XÉN. <i>Hell. 5, 1, 21 ; avec un gén</i>. γ. φορτίων, XÉN. <i>Œc. 8, 12 (cf</i>. THC. <i>7, 25</i>), être chargé de marchandises ; <i>en gén</i>. être rempli de, <i>gén</i>. XÉN. <i>An. 4, 6, 27 ;</i> PLAT. <i>Criti. 117</i> e ; <i>Rsp. 573</i> a ; <i>avec le dat</i>. DIONYS. (ATH. <i>405</i> d) ; CARCIN. (DS. <i>5, 5), etc. ; fig</i>. βοῆς τε καὶ δυσοσμίας γέμων, SOPH. <i>Ph. 876,</i> rassasié (jusqu’au dégoût) de cris et d’infection ; κόμπος τῆς ἀληθείας γέμων, ESCHL. <i>Ag. 613,</i> flatterie pleine de vérité ; θρασύτητος γέμων, PLAT. <i>Leg. 649</i> d (<i>cf</i>. PLAT. <i>Gorg. 525</i> a), plein de hardiesse.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *gem-, prendre, saisir.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γεμω - γέμω</font>\n<br><br>mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n<li>Romains (1)</li>\n<li>Apocalypse (7)</li>\n</ul>\n</td></tr>\n</table>","G1074":"<h1>genea</h1>\n<p>Strong n° 1074 <i>Prononciation [ghen-eh-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>naissance, natalité</li>\n<li>ceux d'une même postérité, une famille\n<ol type=\"a\">\n<li>descendance, membres d'une généalogie</li>\n<li>métaph : races d'hommes très proches entre eux en caractères</li>\n<li>dans un mauvais sens : race perverse</li>\n</ol>\n</li>\n<li>l'ensemble des hommes vivant à une même époque</li>\n<li>un âge (une génération) époque d'environ 30 à 33 ans</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γενεά, ᾶς (ἡ) :<br>A</b> <i>pass</i>. ce qui est engendré, <i>d’où :</i><br><b>   I</b> (<i>avec idée de qualité</i>) genre, espèce : γενεὴ (<i>ion</i>.) φύλλων, IL. <i>6, 146,</i> l’espèce des feuilles, <i>p. opp. à</i> γ. ἀνδρῶν, l’espèce des hommes ;<br><b>   II</b> <i>avec idée de durée et de succession</i>) :<br><b>      1</b> génération : δύο γενεαὶ ἀνθρώπων, IL. <i>1, 250 (cf. 6, 146 ; 19, 105 ; 23, 790 ;</i> OD. <i>19, 291</i>) deux générations <i>ou</i> âges d’hommes ; ἐς δεκάτην γενεήν, OD. <i>14, 325,</i> jusqu’à la 10<sup>e</sup> génération ; πολλαῖς γενεαῖς, THC. <i>2, 68 ;</i> ἐπὶ πολλὰς γενεάς, PLAT. <i>Tim. 23</i> c, après <i>ou</i> pendant de nombreuses générations ; ἐπὶ τῆς ἡμετέρας γενεᾶς, DH. <i>3, 15,</i> de notre temps ;<br><b>      2</b> âge <i>ou</i> période (de l’histoire) : γ. ἀνθρωπηΐη, HDT. <i>3, 122,</i> l’âge de l’humanité, les temps historiques, <i>p. opp. aux âges</i> héroïques <i>ou</i> mythiques ;<br><b>   III</b> (<i>avec idée de descendance ou d’origine</i>) :<br><b>      1</b> <i>en parl. de la parenté,</i> race, famille, <i>d’ord. en parl. des ancêtres ou des parents immédiats,</i> IL. <i>6, 145, 152 ; 20, 214 ;</i> ἐμοὶ γενεὴ ἐξ Ἀξιοῦ, IL. <i>21, 157,</i> je descends, par ma famille, d’Axios ; γ. Πριάμοιο, IL. <i>20, 306,</i> la famille de Priam ; ἀλλήλων γενεὴν ἴδμεν, IL. <i>20, 203,</i> nous connaissons chacun la race l’un de l’autre ; <i>joint à</i> τόκος, IL. <i>15, 141 ;</i> ταύτης εἶναι γενεῆς καὶ αἵματος, IL. <i>6, 211,</i> être de cette race et de ce sang ; γενεήν τινος εἶναι, IL. <i>21, 137 ;</i> OD. <i>15, 225,</i> être de la race <i>ou</i> de la famille de qqn ; γενεῇ, OD. <i>1, 387,</i> par droit de famille, par droit de naissance ; <i>particul. en parl. de la noblesse de la race,</i> IL. <i>11, 786 ; de même, en parl. de chevaux de prix,</i> IL. <i>5, 265, 268 ; — qqf. en parl. des descendants, de la postérité,</i> ORACL. (HDT. <i>6, 86), ou d’une seule pers</i>. rejeton, descendant, IL. <i>21, 191 ;</i> OD. <i>4, 27 ;</i> SOPH. <i>Aj. 190, etc. ; en prose réc</i>. γενεὰς ἔχειν, POL. <i>20, 6, 6,</i> avoir des descendants ;<br><b>      2</b> <i>en parl. de la nationalité,</i> race, nation, tribu, peuple : Αἰτωλὸς γενεήν, IL. <i>23, 471,</i> Étolien d’origine ; Περσῶν γενεά, ESCHL. <i>Pers. 912,</i> la race des Perses ;<br><b>B</b> <i>intr</i>. naissance, <i>d’où :</i><br><b>      1</b> temps de la naissance : ἐκ γενεῆς, HDT. <i>3, 33 ; 4, 23 ;</i> ἀπὸ γενεᾶς, XÉN. <i>Cyr. 1, 2, 8,</i> depuis la naissance ; <i>d’où</i> âge : γενεῇ <i>ou</i> γενεῆφι ὁπλότερος, IL. <i>2, 707 ; ou</i> νεώτερος, IL. <i>21, 439,</i> postérieur par la naissance, plus jeune ; ὁπλότατος, IL. <i>7, 153 ; ou</i> νεώτατος, IL. <i>9, 58,</i> le plus jeune ; πρότερος, IL. <i>15, 166,</i> plus âgé, aîné ;<br><b>      2</b> lieu de la naissance : γ. δέ τοι ἐπὶ λίμνῃ Γυγαίῃ, IL. <i>20, 390,</i> c’est au bord du lac Gygæè qu’est le lieu de ta naissance ; <i>en parl. de l’aire d’un aigle,</i> OD. <i>15, 175 ;</i><br><b>C</b> <i>trans</i>. action d’engendrer, d’enfanter, OPP. <i>H. 1, 479</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. γενεή (<i>v. ci-dessus). Dat. épq</i>. γενεῆφι, IL. <i>9, 58 ; 14, 112 ; 21, 439. Dat. pl</i>. γενεῇς (<i>var</i>. γενεαῖς) THCR. <i>Idyl. 12, 18</i>.<br><span><b>Étym</b>. γίγνομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γενεα - γενεά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n42 fois dans 37 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (13)</li>\n<li>Marc (5)</li>\n<li>Luc (14)</li>\n<li>Actes (5)</li>\n<li>Ephésiens (2)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1075":"<h1>genealogeo</h1>\n<p>Strong n° 1075 <i>Prononciation [ghen-eh-al-og-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>chercher ses origines familiales, tracer l'arbre généalogique, descendre de</li>\n<li>un pedigree (une généalogie)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γενεαλογέω-ῶ</b> (<i>v. ci-dessous</i>) <span>[ᾱ]</span><br><b>      1</b> faire la généalogie de : τινα, HDT. <i>2, 143,</i> de qqn ; τινα ἔκ τινος, PLAT. <i>Tim. 22</i> a ; τινά τινος, PLUT. <i>M. 894</i> b, rechercher <i>ou</i> indiquer la généalogie de qqn ; γ. τινα γενέσθαι, PLUT. <i>Lyc. 2, ou</i> γ. τινα εἶναι, PAUS. <i>5, 14, 9,</i> montrer comment une personne descend d’une autre ; <i>avec un acc. de chose :</i> γ. γένεσιν, HDT. <i>2, 146 ; ou</i> τὴν συγγένειαν, XÉN. <i>Conv. 4, 51,</i> rechercher <i>ou</i> indiquer l’origine <i>ou</i> la parenté de qqn ; <i>au pass</i>. être dit à titre de renseignements sur la famille <i>ou</i> l’origine (de qqn) : ταῦτα μέν νυν γεγενεηλόγηται, HDT. <i>6, 53,</i> voilà ce qu’on sait de leur famille ; <i>impers</i>. ἐγενεαλογήθη, SPT. <i>1Par. 5, 1,</i> on dressa sa généalogie ;<br><b>      2</b> <i>p. ext</i>. rechercher l’origine : γ. περί τινος, LUC. <i>Salt. 34, ou</i> γ. τι, <i>ibid. 7,</i> de qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Act. seul. prés</i>. XÉN. PLAT. PAUS. <i>ll. cc. ; ion</i>. γενεηλογέω, HDT. <i>2, 146 ; et part. ao. ion</i>. γενεηλογήσας, HDT. <i>2, 143. Pass. prés. part</i>. γενεαλογούμενος, NT. <i>Hebr. 7, 6. Ao. v. ci-dessus ; part. plur. neutre</i> γενεαλογηθέντα, PLAT. <i>Tim. 23</i> b. <i>Pf. 3 sg. ion</i>. γεγενεηλόγηται, HDT. <i>l. c</i>.<br><span><b>Étym</b>. γενεαλόγος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γενεαλογεω - γενεαλογέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G1076":"<h1>genealogia</h1>\n<p>Strong n° 1076 <i>Prononciation [ghen-eh-al-og-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une généalogie, enregistrement d'une lignée ou descendance</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γενεαλογία, ας (ἡ)</b> <span>[ᾱλ]</span> généalogie, PLAT. <i>Crat. 396</i> c ; ISOCR. <i>223</i> b ; <i>au plur</i>. POL. <i>9, 2, 1 ; ion</i>. Γενεηλογίαι, Généalogies, <i>titre d’un ouvrage d’Hécatée</i>.<br><span><b>Étym</b>. γενεαλόγος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γενεαλογια - γενεαλογία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Timothée (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G1077":"<h1>genesia</h1>\n<p>Strong n° 1077 <i>Prononciation [ghen-es'-ee-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>célébration d'anniversaire, fête d'anniversaire de naissance\n<ol type=\"a\">\n<li>ce mot fut d'abord utilisé pour commémorer l'anniversaire de la mort d'un ami</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>γενέσιος, ος, ον :<br>   I</b> qui concerne la famille, protecteur de la famille, PLUT. <i>M. 402</i> a ; PAUS. <i>2, 38, 4 ;</i><br><b>   II</b> qui concerne la naissance, JOS. <i>A.J. 12, 4, 7 ; subst</i>. τὰ γενέσια :<br><b>      1</b> anniversaire de la naissance, ALCIPHR. <i>3, 18 et 55 ;</i> NT. <i>Matth. 14, 6 ; Marc. 6, 21 ;</i> DC. <i>47, 18, etc. ;</i><br><b>      2</b> <i>p. ext</i>. anniversaire, <i>en gén. ; d’où</i> anniversaire de la mort, HDT. <i>4, 26</i>.<br><span><b>Étym</b>. γένος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γενεσια - γενέσια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre pluriel</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n</ul>\n</td></tr>\n</table>","G1078":"<h1>genesis</h1>\n<p>Strong n° 1078 <i>Prononciation [ghen'-es-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>source, origine\n<ol type=\"a\">\n<li>livre de la lignée, énumération des ancêtres et progéniture</li>\n</ol>\n</li>\n<li>naissance, natalité</li>\n<li>ce qui suit l'origine: existence, vie\n<ol type=\"a\">\n<li>le cours de la vie, ou la roue de l'origine humaine, où les hommes commencent par naître, puis marcher, c'est donc la roue de la vie (<a class=\"ref\" data-r=\"JAS3.6\">Jacques 3.6</a>).</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γένεσις, εως (ἡ) :<br>   I</b> force productrice, cause, principe, origine, source de vie, IL. <i>14, 201, 246 ;</i> HDT. <i>2, 146 ;</i> PLAT. <i>Theæt. 180</i> d ; <i>etc. ; — p. suite :</i><br><b>      1</b> production, génération, création, <i>p. opp. à</i> φθορά, PLAT. <i>Phil. 55</i> a ; <i>Parm. 136</i> b, <i>etc. ;</i> production d’objets travaillés de main d’homme (vêtements, <i>etc</i>.), PLAT. <i>Pol. 281</i> b, <i>etc. ; Leg. 920</i> e ; production de choses abstraites (vertus, qualités, <i>etc</i>.), PLAT. <i>Rsp. 359</i> a ; <i>abs</i>. la Genèse, <i>titre du 1<sup>er</sup> livre du Pentateuque,</i> SPT. ;<br><b>      2</b> origine, HDT. <i>2, 146 ;</i> SOPH. <i>Tr. 380 ; d’où, en gén.,</i> naissance, HDT. <i>1, 204 ; 6, 69 ; t. d’astrol</i>. jour de la naissance, <i>d’où</i> horoscope, ANTH. <i>11, 164, 183 ;</i><br><b>      3</b> action de devenir, <i>p. opp. à</i> être, PLAT. <i>Rsp. 525</i> b, <i>etc. ;</i><br><b>   II</b> tout être créé, <i>d’où :</i><br><b>      1</b> l’ensemble des êtres créés, la création, PLAT. <i>Phædr. 245</i> e ; <i>Tim. 29</i> e ;<br><b>      2</b> race, <i>càd</i>. espèce <i>ou</i> sorte d’animaux, PLAT. <i>Pol. 265</i> b, <i>etc. ; en parl. de pers</i>. famille, PLAT. <i>Leg. 691</i> d ;<br><b>      3</b> (<i>avec idée de durée</i>) génération, âge, PLAT. <i>Phædr. 252</i> d ; <i>Pol. 310</i> d ;<br><b>   III</b> organes de la génération, ANTH. <i>9, 311</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. duel</i> τοῖν γενεσέοιν, PLAT. <i>Phæd. 71</i> e.<br><span><b>Étym</b>. γίγνομαι, <i>cf</i>. γένος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γενεσις - γένεσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Jacques (2)</li>\n</ul>\n</td></tr>\n</table>","G1079":"<h1>genete</h1>\n<p>Strong n° 1079 <i>Prononciation [ghen-et-ay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>naissance, depuis la naissance</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γενετή, ῆς (ἡ)</b> <i>seul. dans les locut</i>. ἐκ γενετῆς, IL. <i>24, 535 ;</i> OD. <i>18, 6 ;</i> ARSTT. <i>Nic. 6, 13, 1, etc. ;</i> POL. <i>3, 20, 4 ; etc. et</i> ἀπὸ γενετῆς, JAMBL. <i>V. Pyth. 171,</i> dès la naissance.<br><span><b>Étym</b>. γίγνομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γενετη - γενετή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G1080":"<h1>gennao</h1>\n<p>Strong n° 1080 <i>Prononciation [ghen-nah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>pour les enfants\n<ol type=\"a\">\n<li>être né</li>\n<li>être engendré\n<ol>\n<li>des femmes donnant le jour à un enfant</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>métaph :\n<ol type=\"a\">\n<li>engendrer, exciter</li>\n<li>pour les Juifs : amener quelqu'un à la vie, convertir quelqu'un</li>\n<li>la manière dont Dieu a fait son fils</li>\n<li>de Dieu faisant des fils avec les hommes, par l'œuvre de Christ</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γεννάω-ῶ</b> <span>(<i>impf</i>. ἐγέννων, <i>f</i>. γεννήσω, <i>ao</i>. ἐγέννησα, <i>pf</i>. γεγέννηκα)</span><br><b>   I <i>tr.</i></b> engendrer, enfanter, produire :<br><b>      1</b> <i>au propre, d’ord. en parl. du père,</i> ESCHL. <i>Suppl. 48 ;</i> SOPH. <i>El. 1412 ;</i> EUR. <i>I.T. 499 ; etc. ; qqf. en parl. de la mère (en ce sens, d’ord</i>. τίκτειν), ESCHL. <i>Suppl. 47 ;</i> ARSTT. <i>G.A. 3, 5, 6 ;</i> LUC. <i>Sacr. 6, etc. ;</i> οἱ γεννήσαντες, XÉN. <i>Mem. 2, 1, 27 ;</i> PLAT. <i>Rsp. 538</i> a, les parents ; τὸ γεννώμενον, HDT. <i>1, 108,</i> l’enfant ;<br><b>      2</b> <i>fig</i>. engendrer, produire, faire naître (une pensée, une vertu, l’amour, <i>etc</i>.) PLAT. <i>Rsp. 490</i> b ; <i>Conv. 209</i> e ; <i>Tim. 91</i> b, <i>etc. ;</i><br><b>   II</b> développer, faire croître : σῶμα, SOPH. <i>Aj. 1077,</i> le corps ;<br><b><i>Moy.</i></b> (γεννάομαι-ῶμαι ; <i>f</i>. γεννήσομαι, <i>v. ci-dessous ; ao</i>. ἐγεννησάμην) faire naître de soi-même, créer, PLAT. <i>Tim. 34</i> b, <i>Menex. 238</i> a.<br><span><b><span class=\"arrow\"></span></b> <i>Act. fut. dor</i>. γεννάσω <span>[ᾱ]</span> EUR. <i>I.A. 1065. Ao. dor</i>. ἐγέννασα <span>[νᾱ]</span> ESCHL. <i>Suppl. 48. Moy. fut. au sens pass</i>. γεννήσομαι, DS. <i>19, 2 Bkk. ;</i> CALLISTH. <i>1, 4</i>.<br><span><b>Étym</b>. γέννα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γενναω - γεννάω</font>\n<br><br>Voir définition </td>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n97 fois dans 65 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (45)</li>\n<li>Marc (1)</li>\n<li>Luc (4)</li>\n<li>Jean (18)</li>\n<li>Actes (7)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (3)</li>\n<li>2 Timothée (1)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (4)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (10)</li>\n</ul>\n</td></tr>\n</table>","G1081":"<h1>gennema</h1>\n<p>Strong n° 1081 <i>Prononciation [ghen'-nay-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui est né ou engendré\n<ol type=\"a\">\n<li>progéniture de l'homme ou de l'animal</li>\n<li>les fruits de la terre, les produits de l'agriculture</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γέννημα, ατος (τὸ) :<br>   I</b> <i>pass</i>. ce qui est engendré <i>ou</i> produit :<br><b>      1</b> enfant, rejeton, SOPH. <i>Tr. 315 ; O.R. 1167 ; Ant. 623 ; en parl. de petits d’animaux,</i> NT. <i>Matth. 3, 7 ;</i><br><b>      2</b> <i>au plur</i>. produits du sol, fruits, <i>etc</i>. POL. <i>1, 71, 1 ; 3, 87, 1, etc. ;</i> SPT. <i>Lev. 23, 39, etc. ;</i><br><b>      3</b> ouvrage, œuvre, PLAT. <i>Rsp. 597</i> e ;<br><b>      4</b> <i>au sens mor</i>. produit de la nature <i>ou</i> de l’éducation, nature, caractère, SOPH. <i>Ant. 471 ;</i><br><b>   II</b> <i>act</i>. fécondation, ESCHL. <i>Pr. 850 ; d’où</i> celui qui engendre, PLAT. <i>Soph. 266</i> d.<br><span><b>Étym</b>. γεννάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γεννημα - γέννημα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (1)</li>\n<li>Luc (3)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1082":"<h1>Gennesaret</h1>\n<p>Strong n° 1082 <i>Prononciation [ghen-nay-sar-et']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Génésareth (Angl. Gennesaret) = « une harpe »\n<ol>\n<li>lac aussi appelé mer de Galilée ou mer de Tibériade. Le lac mesure 20 km sur 11 km et se trouve à 200 mètres au dessous de la Mer Méditerranée.</li>\n<li>région très agréable et fertile autour de la Mer de Galilée</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Γεννησαρέτ</b> <i>ou</i> <b>-ρέθ (ἡ)</b> <i>avec ou sans</i> λίμνη, le lac de Gennèsaret <i>ou</i> Gennèsareth, <i>en Galilée,</i> NT. <i>Luc. 5, 1</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Γεννησαρετ</font> &lt; גניסר - <font face=\"Georgia\">Γεννησαρέτ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1083":"<h1>gennesis</h1>\n<p>Strong n° 1083 <i>Prononciation [ghen'-nay-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>engendré</li>\n<li>nativité, naissance</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γέννησις, εως (ἡ)</b> action d’engendrer, génération, production, <i>d’où</i> naissance, PLAT. <i>Conv. 206</i> e, <i>209</i> d ; <i>t. eccl. en parl. des trois modes de naissance</i> (naissance, baptême, résurrection), NAZ. <i>2, 360 c Migne</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Acc. pl. dor</i>. γεννάσεις <span>[ᾱ]</span> EUR. <i>I.A. 1065</i>.<br><span><b>Étym</b>. γεννάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γεννησις - γέννησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1084":"<h1>gennetos</h1>\n<p>Strong n° 1084 <i>Prononciation [ghen-nay-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>engendré, né</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γεννητός, ή, όν :<br>   I</b> <i>pass. :</i><br><b>      1</b> engendré, PLUT. <i>M. 880</i> b ; υἱὸς γ. PLAT. <i>Leg. 923</i> e, enfant né de mariage (<i>p. opp. à</i> ποιητός, adopté, adoptif) ; <i>subst</i>. γεννητοὶ γυναικῶν, NT. <i>Matth. 11, 11, etc</i>. enfants nés des femmes ;<br><b>      2</b> <i>p. suite,</i> mortel, LUC. <i>Ic. 2 ; p. opp. à</i> ἀθάνατος, DH. <i>5, 29 ;</i><br><b>   II</b> <i>act</i>. qui engendre <i>ou</i> produit, <i>p. opp. à</i> φθαρτός, ARSTT. <i>Metaph. 5, 3, 1</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. γεννατός <span>[ᾱ]</span> T. LOCR. <i>97</i> d.<br><span><b>Étym</b>. <i>vb. de</i> γεννάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γεννητος - γεννητός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1085":"<h1>genos</h1>\n<p>Strong n° 1085 <i>Prononciation [ghen'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>race\n<ol type=\"a\">\n<li>descendance, postérité</li>\n<li>famille</li>\n<li>race, nation\n<ol>\n<li>nationalité ou descendance d'un peuple particulier</li>\n</ol>\n</li>\n<li>l'ensemble des individus d'une même nature, genre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γένος, εος-ους (τὸ) :<br>A</b> naissance, <i>d’où :</i><br><b>   I</b> <i>propr</i>. naissance, <i>càd. :</i><br><b>      1</b> temps de la naissance : γένει ὕστερος, IL. <i>3, 215,</i> le dernier par la naissance, le plus jeune ;<br><b>      2</b> lieu <i>ou</i> condition de la naissance : γένει πολίτης, DÉM. <i>628, 8,</i> citoyen par la naissance ; γένει υἱός, DÉM. <i>1081, 7,</i> fils de naissance, <i>p. opp. à</i> fils d’adoption ;<br><b>   II</b> <i>en gén</i>. origine, descendance : ἀμφοτέροισιν ὁμὸν γένος, IL. <i>13, 354,</i> tous deux ont la même origine ; <i>avec un n. de pers. comme n. d’origine :</i> γένος εἶναι ἔκ τινος, IL. <i>5, 544 ;</i> OD. <i>21, 235, etc., ou</i> γένος εἶναί τινος, IL. <i>21, 186 ;</i> OD. <i>4, 63 ; etc</i>. descendre de qqn ; <i>avec un n. de lieu comme n. d’orig. :</i> ἐξ Ἰθάκης γένος εἰμί, OD. <i>15, 267 (cf</i>. IL. <i>14, 199 ;</i> PLAT. <i>Soph. 216</i> a, <i>etc</i>.) ; γένος μέν εἰμι τῆς Σκύρου, SOPH. <i>Ph. 239,</i> je suis originaire d’Ithaque, de Skyros (Scyros) ; <i>qqf. avec l’art</i>. ποδαπὸς τὸ γένος εἶ ; AR. <i>Pax 187,</i> de quel pays es-tu ? ;<br><b>B</b> tout être créé, toute réunion d’êtres créés :<br><b>   I</b> (<i>avec idée de</i> qualité <i>ou de</i> condition) <i>en parl. d’êtres ayant une origine commune (dieux, hommes, animaux, choses), càd</i>. race, genre, espèce : θεῶν γένος, SOPH. <i>Aj. 392,</i> la race des dieux, les dieux ; ἡμιθέων γ. ἀνδρῶν, IL. <i>12, 23,</i> la race des hommes demi-dieux, les hommes demi-dieux ; γ. βοῶν, OD. <i>20, 212,</i> la race des bœufs ; γ. ἵππειον, SOPH. <i>Ant. 342,</i> la race des chevaux ; γ. ἡμιόνων, IL. <i>2, 852,</i> la race des mulets ;<br><b>   II</b> <i>particul. en parl. d’hommes,</i> race, famille, parenté :<br><b>      1</b> <i>en parl. de la famille propr. dite, en gén. :</i> αἷμά τε καὶ γένος, OD. <i>8, 583,</i> le sang et la race ; γένους φανῆναί τινος, SOPH. <i>O.R. 1383,</i> être montré de la famille de qqn : γένει προσήκειν τινί, XÉN. <i>An. 1, 6, 1,</i> être apparenté à qqn ; οἱ ἐν γένει = συγγενεῖς, SOPH. <i>O.R. 1430,</i> les parents ; ἐγγύτατα γένους, ESCHL. <i>Suppl. 388,</i> à un degré de parenté très proche ; ἐγγυτέρω γένους, IS. <i>72, 30,</i> à un degré de parenté plus proche ; <i>abs. en parl. de familles nobles (lat</i>. gens) : ὅθι τοι γένος ἐστὶ καὶ αὐτῇ, OD. <i>6, 35,</i> là où toi aussi tu as une famille de noble race ; <i>cf</i>. HDT. <i>1, 125, etc. ;</i> PLAT. <i>Gorg. 523</i> c ; <i>Leg. 711</i> e ; οἱ ἀπὸ γένους, PLUT. <i>Rom. 21 ; Cato ma. 1</i> les gens de familles nobles, les gens de race ; — <i>spécial. en parl. des parents immédiats ou des ancêtres :</i> οὐ γὰρ σφῷν γένος ἀπόλωλε τοκήων, OD. <i>4, 62,</i> car tous deux vous êtes de familles dont le renom subsiste encore ; γένος πατέρων αἰσχυνέμεν, IL. <i>6, 209,</i> déshonorer la race de ses pères ; — <i>en parl. des enfants immédiats ou des descendants : d’un seul descendant :</i><br><b>      2</b> σὸν γένος, IL. <i>19, 124 (cf</i>. IL. <i>21, 186 ;</i> OD. <i>16, 401</i>), ton rejeton, ton enfant ; θεῖον γένος, IL. <i>6, 180, ou</i> δῖον γ. IL. <i>9, 538,</i> rejeton des dieux, <i>en parl. de la Chimère et d’Artémis ; collectiv. des enfants :</i> γένους ἐπάρκεσις, SOPH. <i>O.C. 447,</i> l’appui que le père a droit d’exiger de ses enfants ; <i>ou des descendants, de la postérité :</i> ἐκεῖνοι καὶ τὸ γ. τὸ ἀπ' ἐκείνων, THC. <i>1, 126,</i> eux et leurs descendants ; <i>particul. en parl. de la descendance directe (p. opp. aux</i> collatéraux = συγγένεια), IS. <i>72, 33 ;</i><br><b>      3</b> <i>p. anal. en parl. d’associations religieuses, civiles, politiques, etc. particul. à Athènes,</i> réunion de citoyens dont l’ensemble formait une phratrie (<i>v</i>. γεννήτης), PLAT. <i>1 Alc. 120</i> e ; ARSTT. <i>fr. 347 ; chez les Orientaux (Égyptiens, Perses, etc</i>.) caste, HDT. <i>2, 164 ;</i> PLAT. <i>Rsp. 434</i> b ; ARSTT. <i>Pol. 7, 10, 1 ; de même, en parl. de professions,</i> classe, corporation : τὸ μαντικὸν γ. SOPH. <i>Ant. 1055,</i> la classe des devins ; τὸ φιλόσοφον γ. PLAT. <i>Rsp. 501</i> e, la classe des philosophes ; τὸ γ. τῶν γεωργῶν, PLAT. <i>Tim. 17</i> c, la classe des laboureurs ;<br><b>      4</b> <i>avec idée de nationalité,</i> famille de peuples, race, nation, peuple, tribu : τὸ Δωρικὸν γ. HDT. <i>1, 56 (cf. 1, 101</i>) la race dorienne ;<br><b>      5</b> <i>t. de science,</i> famille d’êtres <i>ou</i> de choses abstraites, classe, <i>particul</i>. genre (<i>p. opp. à</i> espèce = εἶδος), PLAT. <i>Parm. 129</i> c ; τὰ γένη εἰς εἴδη πλείω καὶ διαφέροντα διαιρεῖται, ARSTT. <i>Metaph. 10, 1, 12,</i> les genres se divisent en espèces plus nombreuses et différentes (<i>cf</i>. ARSTT. <i>Top. 1, 5, 6, etc.), l’</i>espèce (εἶδος) <i>pouvant, à son tour, devenir un</i> genre (γένος) <i>par rapport aux subdivisions secondaires</i> (<i>v</i>. ARSTT. <i>H.A. 1, 1, 30, etc.) ; de même</i> genre, <i>considéré comme un tout (p. opp. aux</i> parties = μέρη) PLAT. <i>Phil. 12</i> e ; <i>d’où</i> τὰ γένη, les éléments, PLAT. <i>Tim. 54</i> b ;<br><b>C</b> (<i>avec idée de durée</i>) génération, âge : ἀνδρῶν γ. OD. <i>3, 245,</i> génération d’hommes ; γ. χρύσειον, <i>etc</i>. HÉS. <i>O. 109,</i> l’âge d’or ;<br><b>D</b> (<i>avec idée de sexe</i>) sexe, PLAT. <i>Conv. 189</i> d ; <i>p. anal. t. de gr</i>. genre, ARSTT. <i>Rhet. 3, 5, 5 ;</i> D. THR. <i>634, 15, 17, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. ion</i>. γένευς, OD. <i>15, 533. Plur. dans Hom. seul</i>. OD. <i>3, 245. Duel</i> γένεε, PLAT. <i>Pol. 260</i> b, <i>ou</i> γένει, PLAT. <i>Rsp. 547</i> b. — <i>Au sens de</i> « familles » <i>le plur. γένη se trouve construit avec un partic. masc</i>. (τιμῶντες) <i>dans une inscr. att. de 300 envir. av. J.C. (v. Meisterhans, p. 158, § 80, 2</i>).<br><span><b>Étym</b>. γίγνομαι, <i>cf. lat</i>. genus, <i>sscr</i>. jánas-.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γενος - γένος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n21 fois dans 21 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Actes (9)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Pierre (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1086":"<h1>Gergesenos</h1>\n<p>Strong n° 1086 <i>Prononciation [gher-ghes-ay-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>appelés aussi Géraséniens (voir ), ils devaient demeurer sur la rive orientale du lac de Génésareth</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Γεργησηνος</font> &lt; גרגשים - <font face=\"Georgia\">Γερασηνός</font>\n<br><br>Voir définition \n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G1087":"<h1>gerousia</h1>\n<p>Strong n° 1087 <i>Prononciation [gher-oo-see'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un sénat, conseil d'anciens\n<ol type=\"a\">\n<li>assure le conseil des nations ou des villes</li>\n<li>le Sanhédrin</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γερουσία, ας (ἡ) :<br>      1</b> assemblée des anciens <i>ou</i> sénat, <i>à Sparte,</i> DÉM. <i>489, 19 ;</i> ARSTT. <i>Pol. 2, 9, 22 ; etc. ; en Phrygie,</i> EUR. <i>Rhes. 401 ; à Carthage,</i> ARSTT. <i>Pol. 9, 11, 3 ; à Rome,</i> PLUT. <i>M. 789</i> f ; <i>en parl. des Anciens d’Israël,</i> SPT. <i>Ex. 3, 16, 18, etc. ;</i><br><b>      2</b> ambassade (<i>cf. la forme et le sens de</i> πρεσϐεία), EUR. <i>Rhes. 936</i>.<br><span><b>Étym</b>. <i>att. pour</i> γεροντία, <i>v. ce mot ; cf</i>. γερωΐα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γερουσια - γερουσία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)\n<ul type=\"square\">\n<li>Actes 5.21</li>\n</ul>\n</li>\n</ul>\n</td></tr>\n</table>","G1088":"<h1>geron</h1>\n<p>Strong n° 1088 <i>Prononciation [gher'-own]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un vieil homme, vieillard</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γέρων, οντος (ὁ) :<br>   I</b> <i>subst. :</i><br><b>      1</b> vieillard, IL. <i>1, 26 ;</i> OD. <i>3, 226, etc. ;</i> ESCHL. <i>Ag. 584 ;</i> SOPH. <i>Ant. 281, etc. ;</i><br><b>      2</b> <i>p. suite, avec idée de dignité,</i> οἱ γέροντες, <i>dans Hom</i>. les vieillards, les anciens, les chefs qui formaient le conseil du roi, IL. <i>2, 53 ; 4, 344 ;</i> OD. <i>2, 14, etc. ; postér</i>. les sénateurs, <i>à Sparte,</i> HDT. <i>1, 65 ; 6, 57 ;</i> PLAT. <i>Leg. 692</i> a ; ARSTT. <i>Pol. 2, 6, 17, etc. ; dans les autres États doriens, à Élis,</i> ARSTT. <i>Pol. 5, 6, 11 ; en Crète, ibid. 2, 10, 6 ; etc. ;</i><br><b>      3</b> quenouille, <i>parce que le haut de l’instrument figurait une tête de vieillard,</i> PHÉRÉCR. (POLL. <i>7, 73</i>) ;<br><b>   II</b> <i>adj. :</i><br><b>      1</b> ancien, vieux, <i>en parl. de choses ; qqf. au neutre :</i> γέρον σάκος, OD. <i>22, 184,</i> vieux bouclier ; γέρον γράμμα, ESCHL. <i>fr. 305,</i> écrit ancien ; <i>de même au plur</i>. γέροντα βουλεύειν, SOPH. <i>fr. 682,</i> méditer des projets déjà anciens ; <i>d’ord. au masc</i>. γ. λόγος, ESCHL. <i>Ag. 750,</i> parole ancienne ; γ. φόνος, ESCHL. <i>Ch. 805,</i> meurtre ancien ; γ. οἶνος, EUB. (ATH. <i>28</i> f) vieux vin ; γ. πέπλος, THCR. <i>Idyl. 7, 17,</i> vieux manteau ; <i>en parl. d’animaux,</i> γ. ἵππος, SOPH. <i>El. 25,</i> cheval vieilli ; οἱ γέροντες τῶν ἰχθύων, τῶν ἐλάφων, ARSTT. <i>H.A. 8, 30, 6 ; 9, 5, 5,</i> ceux des poissons, des cerfs qui sont devenus vieux ;<br><b>      2</b> <i>en parl. de deux pers</i>. le plus âgé de deux : Ἀντίγονος ὁ γ. PLUT. <i>Pel. 2,</i> Antigone l’ancien.<br><span><b><span class=\"arrow\"></span></b> <i>Voc</i>. γέρον, OD. <i>4, 485 ;</i> THCR. <i>Idyl. 25, 43, etc</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. ǵerh₂-, être/devenir vieux ; <i>cf</i>. γέρας, γῆρας, γραῦς, <i>sscr</i>. járant-, vieillard.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γερων - γέρων</font>\n<br><br>affinité incertaine, cf </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G1089":"<h1>geuomai</h1>\n<p>Strong n° 1089 <i>Prononciation [ghyoo'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>goûter, essayer la saveur de</li>\n<li>percevoir la saveur, participer, jouir de\n<ol type=\"a\">\n<li>sentir, procéder à une épreuve de, éprouver</li>\n</ol>\n</li>\n<li>prendre de la nourriture, manger, se nourrir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>γεῦμα, ατος (τὸ) :<br>      1</b> goût (d’un aliment, d’une chose qqconque) AR. <i>Ach. 187 ;</i> ARSTT. <i>H.A. 1, 6, 8 ; etc. ;</i><br><b>      2</b> ce qu’on goûte, aliment, HPC. <i>Acut. 385 ;</i><br><b>      3</b> action de goûter, EUR. <i>Cycl. 150 ;</i> PLUT.<br><span><b>Étym</b>. γεύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γευομαι - γεύομαι</font>\n<br><br>un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n15 fois dans 15 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Jean (2)</li>\n<li>Actes (3)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (3)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1090":"<h1>georgeo</h1>\n<p>Strong n° 1090 <i>Prononciation [gheh-or-gheh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>faire de l'agriculture, cultiver le sol</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γεωργέω-ῶ</b>, <i>f</i>. ήσω :<br><b>   I</b> travailler la terre, <i>d’où :</i><br><b>      1</b> <i>abs</i>. être cultivateur, laboureur <i>ou</i> fermier, <i>abs</i>. XÉN. <i>Œc. 14, 2 ;</i> PLAT. <i>Leg. 805</i> e ; <i>Euthyphr. 4</i> c ; AND. <i>12, 28 ;</i> LYS. DÉM. <i>etc. ;</i><br><b>      2 <i>tr.</i></b> cultiver, labourer : γῆν, PLAT. <i>Theag. 121</i> b, <i>etc. ;</i> νήσους THC. <i>3, 88, etc. ;</i> χώραν, HDN <i>6, 4, 11,</i> cultiver la terre, des îles, un pays ; <i>p. ext</i>. cultiver une plante : γ. ἐλαίαν, οἶνον, GEOP. <i>9, 2, 6 ; 6, 7, 2,</i> cultiver l’olivier, la vigne ; γεωργούμενα φυτά, ARSTT. <i>Probl. 10, 45,</i> plantes cultivées ;<br><b>      3</b> <i>p. ext. en parl. d’un fleuve,</i> entretenir, féconder, fertiliser (une terre), HLD. <i>2, 28 ;</i> PHILSTR. <i>781, 944 ;</i><br><b>      4</b> <i>en parl. d’un pays,</i> produire (du vin, de l’huile) DC. <i>49, 36 ;</i><br><b>   II</b> <i>fig</i>. cultiver : τέχνην, HLD. <i>5, 7,</i> un art ; φιλίαν, PLUT. <i>M. 776</i> b, l’amitié ; γ. ἔκ τινος, DÉM. <i>442, 6,</i> tirer profit de qqe ch., vivre de qqe ch.<br><span><b>Étym</b>. γεωργός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γεωργεω - γεωργέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1091":"<h1>georgion</h1>\n<p>Strong n° 1091 <i>Prononciation [gheh-ore'-ghee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un champ cultivé, agriculture, labourage</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γεώργιον, ου (τὸ) :<br>      1</b> champ cultivé, verger, bien de campagne, ferme, THÉAGÈS (SCH.-PD. <i>N. 3, 21</i>) ; STR. <i>671 ;</i> DH. <i>1, 37 ;</i> SPT. <i>Gen. 26, 14 ; Prov. 24, 5 ; Sir. 27, 6, etc. ;</i><br><b>      2</b> fruit, récolte, SPT. <i>Prov. 24, 5</i>.<br><span><b>Étym</b>. γεωργός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γεωργιον - γεώργιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1092":"<h1>georgos</h1>\n<p>Strong n° 1092 <i>Prononciation [gheh-ore-gos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un agriculteur, laboureur, vigneron, viticulteur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γε·ωργός, ός, όν :<br>   I</b> <i>adj</i>. qui travaille la terre, <i>en parl. d’un bœuf,</i> AR. <i>Ach. 1036 ;</i> γ. ὄχλος, DH. <i>10, 54,</i> la foule des paysans ;<br><b>   II</b> <i>subst</i>. cultivateur :<br><b>      1</b> <i>propr</i>. cultivateur, laboureur, <i>en gén. :</i> γ. γῆς, SPT. <i>Gen. 9, 20,</i> celui qui cultive le sol, cultivateur ; <i>abs</i>. HDT. <i>4, 18 ;</i> AR. <i>Pax 296 ;</i> PLAT. <i>Phædr. 276</i> b ; <i>particul</i>. propriétaire rural, fermier, ARSTT. <i>Pol. 4, 12, 3 ;</i><br><b>      2</b> <i>p. ext</i>. vigneron, EL. <i>N.A. 7, 28 ; ou</i> jardinier, PHILSTR. <i>78</i>.<br><span><b>Étym</b>. γῆ, ἔργον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γεωργος - γεωργός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n19 fois dans 17 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Marc (5)</li>\n<li>Luc (5)</li>\n<li>Jean (1)</li>\n<li>2 Timothée (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G1093":"<h1>ge</h1>\n<p>Strong n° 1093 <i>Prononciation [ghay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>terre arable</li>\n<li>le sol, la terre où l'on se trouve</li>\n<li>le terrain, le sol, en opposition à la mer ou à l'eau</li>\n<li>la terre dans son ensemble\n<ol type=\"a\">\n<li>la terre par opposition aux cieux</li>\n<li>la terre habitée, le monde des hommes et des animaux</li>\n</ol>\n</li>\n<li>un pays, contrée entourée de frontières, un territoire, une région</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γῆ, ῆς (ἡ) :<br>   I</b> terre :<br><b>      1</b> <i>comme corps dans l’espace,</i> PLAT. <i>Phæd. 97</i> d ; <i>p. opp. au ciel,</i> EUR. <i>Med. 56 ;</i> LUC. <i>Alex. 54 ; particul. p. opp. au soleil et aux astres,</i> IL. <i>19, 259 ;</i> PLAT. <i>Leg. 886</i> a ;<br><b>      2</b> <i>p. opp. aux autres éléments (air, eau et feu</i>), PLAT. <i>Prot. 320</i> d, <i>Leg. 889</i> b, <i>etc. ;</i> ARSTT. <i>Metaph. 1, 8, 2, etc. ; particul. dans la locut</i>. γῆν καὶ ὕδωρ αἰτεῖν, HDT. <i>5, 17, etc</i>. LYCURG. <i>156, 43, ou</i> διδόναι, HDT. <i>5, 18,</i> demander <i>ou</i> remettre la terre et l’eau, <i>en parl. de conquérants, ou de peuples qui se soumettent ;</i><br><b>      3</b> <i>p. opp. à la mer :</i> κατὰ γῆν, THC. <i>1, 18,</i> par terre ; <i>p. opp. à</i> ναυσί, THC. <i>1, 18, etc. ;</i> κατὰ γῆς στέλλεσθαι, XÉN. <i>An. 5, 6, 5,</i> aborder à terre ;<br><b>      4</b> <i>p. opp. aux enfers :</i> ἐπὶ γῆς, SOPH. <i>O.R. 416,</i> sur terre, <i>p. opp. à</i> νέρθε ; κατὰ γῆς, ESCHL. <i>Ch. 377, etc. ;</i> SOPH. <i>O.C. 1775, etc. ;</i> κάτω γῆς, SOPH. <i>O.R. 968 ;</i> νέρθε γῆς, ἔνερθε γῆς, TRAG. <i>etc</i>. sous la terre, dans les enfers ;<br><b>   II</b> terre, <i>comme habitation de l’homme ;</i> ensemble de la terre, monde, univers : ποῦ γῆς ; SOPH. <i>O.R. 108 ; Tr. 236 ; avec mouv</i>. ποῖ γᾶς ; (<i>dor</i>.) SOPH. <i>O.R. 1309 ; Ph. 1211 ;</i> dans quelle partie de la terre ? ;<br><b>   III</b> partie de la terre, pays, contrée : γῆν πρὸ γῆς, ESCHL. <i>Pr. 682 ;</i> AR. <i>Ach. 235,</i> de terre en terre, de pays en pays ; καὶ γῆν καὶ πόλιν, ESCHL. <i>Eum. 993,</i> et la contrée et la ville ; γῆ μελάμφυλλος, SOPH. <i>O.C. 482,</i> région couverte de sombre feuillage, <i>càd</i>. boisée ; <i>cf</i>. LUC. <i>Alex. 46 ;</i> CIC. <i>Att. 14, 10 ;</i> ἡ ἡμετέρα γῆ, <i>ou simpl</i>. ἡ ἡμετέρα, ATT. notre pays ; ECCL. ἡ ἁγία γῆ, SPT. <i>Sap. 12, 3 ; 2 Macc. 1, 7,</i> la Terre sainte, <i>càd</i>. la Palestine ; <i>dans les Trag. qqf. syn. de</i> πόλις, le territoire voisin de la ville et la ville elle-même, <i>en parl. de Troie,</i> EUR. <i>Tr. 868, etc. ;</i><br><b>   IV</b> terre, <i>comme élément producteur :</i> τὰ ἐκ τῆς γῆς φυόμενα, XÉN. <i>Mem. 4, 3, 10,</i> les productions nées de la terre ; τὴν γῆν ἐργάζεσθαι, PLAT. <i>Rsp. 420</i> e, travailler la terre ; <i>p. suite,</i> bien de terre, campagne, ferme, LYS. <i>906 fin ;</i> DÉM. <i>946, 6 ;</i><br><b>   V</b> terre, poussière, <i>en parl. d’un mort,</i> SOPH. <i>El. 244 ;</i><br><b>   VI</b> terre, minerai, GAL. <i>13, 246</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Plur. et duel rares : plur. nomin</i>. γαῖ, ARSTT. <i>Probl. 23, 29 ; acc</i>. γᾶς, STR. <i>126 ; duel gén</i>. γαῖν, ESCHL. <i>Pers. 736. — Poét. non contracte :</i> γέα, <i>d’où nomin. pl</i>. γέαι, ANTH. <i>9, 430 ; gén</i>. γεῶν, HDT. <i>4, 198 (p.-ê</i>. γέων). — <i>Dor</i>. γᾶ, SOPH. <i>O.R. 480, 1309 ; Ph. 1211, etc. ;</i> EUR. <i>Hipp. 672 ; Or. 1519, etc. ; cf</i>. PD. THCR. <i>etc. — Épq</i>. γαῖα, αἶα (<i>v. ces mots</i>).<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γη - γῆ</font>\n<br><br>contracté d'un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n248 fois dans 222 versets de 14 livres bibliques (NT)\n<ul>\n<li>Matthieu (42)</li>\n<li>Marc (19)</li>\n<li>Luc (25)</li>\n<li>Jean (13)</li>\n<li>Actes (34)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (3)</li>\n<li>Ephésiens (4)</li>\n<li>Colossiens (4)</li>\n<li>Hébreux (10)</li>\n<li>Jacques (5)</li>\n<li>2 Pierre (4)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (81)</li>\n</ul>\n</td></tr>\n</table>","G1094":"<h1>geras</h1>\n<p>Strong n° 1094 <i>Prononciation [ghay'-ras]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>le grand âge, les vieux, la vieillesse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γῆρας</b>, <i>gén</i>. <b>αος-ως</b>, <i>dat</i>. <b>αϊ-ᾳ</b>, <i>acc</i>. <b>ας (τὸ) :<br>      1</b> vieillesse, IL. <i>5, 153, etc</i>. OD. <i>2, 16, etc. ;</i> ἐν τῷ γήρᾳ, PLAT. <i>Rsp. 329</i> c ; ἐπὶ γήρως, AR. <i>Eq. 524,</i> dans la vieillesse ; <i>fig</i>. οὐκ ἔστι γῆρας τοῦδε τοῦ μιάσματος, ESCHL. <i>Sept. 682,</i> même avec le temps cette souillure ne s’affaiblit pas ;<br><b>      2</b> vieille peau dont se dépouillent les serpents, ARSTT. <i>H.A. 5, 17, 10 ; 8, 17, 11 ; fig</i>. AR. <i>Pax 336, Lys. 670</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. poét</i>. γήραος, IL. <i>22, 60 ; 24, 487 ;</i> OD. <i>15, 246 ;</i> PD. <i>O. 8, 94. Dat. poét</i>. γήραϊ, IL. <i>3, 150 ; 19, 336 ;</i> OD. <i>11, 136 ; 23, 283 ; 24, 233</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. ǵerh₂-, être vieux ; <i>cf</i>. γέρας, γέρων, γραῦς ; <i>v</i>. *γῆρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γηρας - γῆρας</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1095":"<h1>gerasko</h1>\n<p>Strong n° 1095 <i>Prononciation [ghay-ras'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>devenir vieux, vieillir</li>\n<li>des choses et des institutions : prendre de l'âge, vieilli</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γηράσκω</b> (<i>seul. prés., impf. et ao.2 inf</i>. γηράναι <i>et part</i>. γηράς) vieillir, IL. <i>2, 663, etc. ;</i> TRAG. ATT. ; <i>en parl. de fruits,</i> mûrir, OD. <i>7, 120 ; en parl. de choses,</i> s’affaiblir, EUR. <i>H.f. 1223 (reconnaissance</i>), MÉN. <i>4, 209 Meineke ; en parl. du temps,</i> ESCHL. <i>Pr. 981 ;</i><br><b><i>Moy</i>. γηράσκομαι</b> <i>m. sign</i>. HÉS. <i>fr. 163 Göttling</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. ind</i>. OD. <i>7, 120 ;</i> ATT. (SOPH. <i>O.R. 872 ;</i> XÉN. <i>Vect. 1, 4, etc.) ; inf. épq</i>. γηρασκέμεν, OD. <i>4, 210. Impf. 3 sg. poét</i>. γήρασκε, IL. <i>17, 325. Ao.2 ind. 3 sg</i>. ἐγήρα, IL. <i>7, 148 ;</i> OD. <i>14, 67 ; inf</i>. γηράναι <span>[ᾰ]</span> (<i>sel. d’autres</i> γηρᾶναι, <i>c. d’un ao.1</i> *ἐγήρανα <span>[ᾱ]</span>), ESCHL. <i>Ch. 908 ;</i> SOPH. <i>O.C. 870 ; part</i>. γηράς, IL. <i>17, 197 (cf</i>. ἀποδράς <i>de</i> ἀποδιδράσκω) ; <i>d’où dat. pl</i>. γηράντεσσι, HÉS. <i>O. 188. Autre part. ao.2</i> γηρείς, -έντος, XÉNOPHAN. (EM.).<br><span><b>Étym</b>. γῆρας.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γηρασκω - γηράσκω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1096":"<h1>ginomai</h1>\n<p>Strong n° 1096 <i>Prononciation [ghin'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>devenir : venir dans l'existence, commencer à être</li>\n<li>devenir, revenir au passé, arriver\n<ol type=\"a\">\n<li>pour des événements</li>\n</ol>\n</li>\n<li>provenir de, apparaître dans l'histoire\n<ol type=\"a\">\n<li>d'un homme apparaissant en public</li>\n</ol>\n</li>\n<li>être fait, terminé\n<ol type=\"a\">\n<li>miracles : réalisé, qui a eu lieu</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γίνομαι</b>, <i>v</i>. γίγνομαι, <i>fin</i>.<br>\n<b>γίγνομαι</b> <span>(<i>impf</i>. ἐγιγνόμην, <i>f</i>. γενήσομαι, <i>ao.2</i> ἐγενόμην, <i>pf</i>. γέγονα <i>et</i> γεγένημαι)</span><br><b>A</b> <i>propr</i>. devenir, <i>p. opp. à</i> « être (εἶναι) », PLAT. <i>Phæd. 102</i> e, <i>ou à</i> « être immuable (τὸ κατὰ ταὐτὰ καὶ ὡσαύτως ἔχον) », PLAT. <i>Tim. 29</i> a ;<br><b>B</b> <i>p. suite :</i><br><b>   I</b> naître, <i>p. opp. à</i> θανεῖν, HÉS. <i>O. 173, ou à</i> ἀπόλλυσθαι, PLAT. <i>Parm. 163</i> d ; <i>particul. en parl. de pers</i>. ESCHL. <i>Eum. 347 ;</i> γ. ἔκ τινος, IL. <i>5, 548, etc</i>. naître de qqn ; <i>d’où au pf</i>. être né : γεγονέναι ἔκ τινος, HDT. <i>7, 11 ;</i> EUR. <i>I.A. 406, etc. ;</i> ἀπό τινος, HDT. <i>8, 22 ;</i> XÉN. <i>Cyr. 4, 1, 24 ;</i> PLAT. <i>Soph. 265</i> c, <i>etc. ; rar</i>. τινος, EUR. <i>Hec. 380,</i> de qqn ; <i>abs</i>. νέον γεγαώς (<i>v. ci-dessous</i>), OD. <i>19, 400,</i> nouveau-né ; γεγονέναι καλῶς, ISOCR. <i>147</i> b ; <i>ou</i> εὖ, HDT. <i>3, 69,</i> être de bonne naissance ; κάλλιον, HDT. <i>1, 146,</i> être d’une naissance plus illustre ; κακῶς γεγονέναι, AR. <i>Eq. 218,</i> être de basse origine ; ὑπὲρ τὰ στρατεύσιμα ἔτη γεγονώς, XÉN. <i>Cyr. 1, 2, 4,</i> qui a dépassé l’âge du service militaire ; <i>d’ord. pour marquer l’âge, avec un n. de nombre cardinal :</i> ἔτεα τρία καὶ δέκα γεγονώς, HDT. <i>1, 119,</i> âgé de treize ans ; ἀμφὶ τὰ ἑκκαίδεκα ἔτη γενόμενος, XÉN. <i>Cyr. 1, 4, 16,</i> âgé d’environ seize ans ; <i>rar. avec un n. de nombre ordinal :</i> τέταρτον καὶ ὀγδοηκοστὸν ἔτος γεγονώς, LUC. <i>Macr. 22,</i> âgé de 84 ans ; <i>pléonast</i>. γ. ἀπὸ γενεᾶς, XÉN. <i>Cyr. 1, 2, 13,</i> avoir tel âge en comptant depuis la naissance ; — <i>en parl. de plantes,</i> OD. <i>9, 51 ;</i> XÉN. <i>Mem. 2, 9, 4 ; 3, 6, 13 ;</i> ARSTT. <i>Rhet. 2, 15 ;</i><br><b>   II</b> <i>en parl. de choses,</i> se produire, avoir lieu :<br><b>      1</b> <i>en parl. de phénomènes physiques :</i> πνεῦμα γίγνεται, THC. <i>2, 84,</i> il s’élève du vent ; ὡς ἡ ἡμέρα ἐγένετο, THC. <i>7, 81,</i> lorsque le jour parut ; ἅμα ἕῳ γιγνομένῃ, THC. <i>4, 32,</i> au point du jour ; ἕως ἂν φῶς γένηται, PLAT. <i>Prot. 311</i> a, jusqu’à ce que le jour ait paru ;<br><b>      2</b> <i>en parl. du temps :</i> ὡς τρίτη ἡμέρη ἐγένετο, HDT. <i>1, 113,</i> lorsque le 3<sup>e</sup> jour fut arrivé ; πρὶν ἓξ μῆνας γεγονέναι, PLAT. <i>Prot. 320</i> a, avant que six mois se soient écoulés ; χρόνου γενομένου, DS. <i>20, 109,</i> le temps s’étant écoulé ;<br><b>      3</b> <i>en parl. d’événements :</i> γίγνεται πόλεμος, μάχη, <i>etc</i>. ATT. une guerre, un combat, a lieu ; ἡ νόσος ἤρξατο γίγνεσθαι, THC. <i>2, 47,</i> le mal commença de se manifester ; ψήφισμα, κρίσις γίγνεται, XÉN. <i>Cyr. 2, 2, 21,</i> un décret est publié, un jugement est rendu ; πιστὰ γίγνεται, XÉN. <i>Cyr. 7, 4, 3,</i> des promesses sont faites ; γίγνονται ὅρκοι, DÉM. <i>390, 28,</i> des serments sont prononcés ; <i>particul. en parl. de fêtes, de sacrifices :</i> τὰ Ὀλύμπια γίγνεται, XÉN. <i>Hell. 7, 4, 28,</i> on célèbre les fêtes d’Olympie ; τὰ ἱερὰ καλὰ ἐγίγνετο, XÉN. <i>An. 6, 2, 9,</i> le sacrifice s’accomplissait favorable ; <i>en génér</i>. ὅσσα γίνεται (<i>v. ci-dessous</i>) ἐπὶ χθονί, OD. <i>12, 191,</i> tout ce qui arrive sur terre ; <i>abs</i>. τὸ γιγνόμενον, PLAT. <i>Theæt. 161</i> b, ce qui se produit ; τὸ γενόμενον, THC. <i>6, 54 ; ou</i> τὰ γενόμενα, XÉN. <i>Cyr. 3, 1, 9,</i> ce qui s’est passé, l’événement, les faits, la réalité ; τὰ γεγενημένα, XÉN. <i>An. 5, 10, 14,</i> les événements accomplis, le passé ; τὰ γεγονότα, <i>m. sign. p. opp. à</i> ὄντα <i>et à</i> μέλλοντα, PLAT. <i>Rsp. 392</i> d ; <i>à</i> ὄντα <i>et à</i> ἐσόμενα, PLAT. <i>Leg. 896</i> a ; τὸ γενησόμενον, THC. <i>1, 138,</i> ce qui arrivera, l’avenir ; <i>avec un rég</i>. γίγνεταί τι ὑπό τινος, THC. <i>6, 88 ;</i> XÉN. <i>An. 7, 1, 30 ;</i> PLAT. <i>Theæt. 200</i> e ; <i>ou</i> ἔκ τινος, HDT. <i>1, 1 ; ou</i> ἀπό τινος, XÉN. <i>An. 5, 6, 30 ; ou</i> παρά τινος, PLAT. <i>Rsp. 614</i> a, qqe ch. arrive du fait de qqn ; <i>avec un dat. accompagné d’un partic</i>. οὐκ ἂν ἔμοι γε ἐλπομένῳ τὰ γένοιτο, OD. <i>3, 228,</i> non, je n’oserais espérer qu’une pareille chose arrive ; ἡδομένοισιν ἡμῖν οἱ λόγοι γεγόνασι, HDT. <i>9, 46,</i> nous avons eu plaisir à entendre ces paroles ; <i>avec un inf</i>. γίγνεται εὑρεῖν, THGN. <i>639,</i> il arrive qu’on trouve, il est possible de trouver ; γένοιτό μοι λαϐεῖν, XÉN. <i>Cyr. 6, 3, 11,</i> puisse-t-il m’arriver de prendre ! <i>avec</i> ὥστε : ἐγένετο ὥστε <i>avec la prop. inf</i>. XÉN. <i>Hell. 5, 3, 10 ;</i> γέγονεν ὥστε, ISOCR. <i>124</i> a (<i>cf</i>. XÉN. <i>Cyr. 8, 2, 2</i>), il arriva, il est arrivé que, <i>etc. ; abs</i>. γένοιτο ! qu’il en soit ainsi ! <i>traduct. de l’hébr</i>. amen <i>dans les Livres saints,</i> SPT. <i>Ps. 40, 14 ; Esaï. 25, 1, etc. ;</i><br><b>      4</b> <i>en parl. d’un résultat :</i> ὁ γεγονὼς ἀριθμός, PLAT. <i>Ap. 36</i> a, le total qui a été atteint ; καρποὶ οἱ ἐξ ἀγελῶν γιγνόμενοι, XÉN. <i>Cyr. 1, 1, 2,</i> le produit qu’on retire des troupeaux ; τὸ ἀπὸ τῶν αἰχμαλώτων γενόμενον ἀργύριον, XÉN. <i>An. 5, 3, 4,</i> l’argent qu’on retire de la rançon des prisonniers de guerre ; οἱ γιγνόμενοι δασμοί, XÉN. <i>An. 1, 1, 8,</i> le produit des impôts ;<br><b>      5</b> <i>en parl. d’une conséquence,</i> avoir son effet, s’accomplir : γενομένης τῆς ἀπειλῆς, DÉM. <i>24, 141 Bait.-Sauppe,</i> la menace ayant été proférée ;<br><b>   III</b> devenir (par suite d’un changement) :<br><b>      1</b> <i>avec un attrib</i>. πρὶν δηΐοισι χάρμα γενέσθαι, IL. <i>6, 82,</i> avant que (les fuyards) ne deviennent la risée (de l’ennemi) ; αἴ κέν τι φόως Δαναοῖσι γένηαι, IL. <i>8, 282,</i> si tu pouvais devenir la joie (<i>càd</i>. le salut) des Grecs ; <i>avec un adj</i>. ἐκ πλουσίου πένης γεγονώς, XÉN. <i>An. 7, 7, 28,</i> devenu pauvre de riche qu’il était ; πάντα γιγνόμενος, OD. <i>4, 417,</i> prenant toutes les formes (<i>litt</i>. devenant tout), <i>en parl. de Protée ;</i> παντοῖος γινόμενος (<i>v. ci-dessous), avec μή et l’inf</i>. HDT. <i>3, 124,</i> s’efforçant par tous les moyens d’empêcher que ; <i>avec un pron</i>. τί γένωμαι ; ESCHL. <i>Sept. 297 ;</i> τί γενώμεθα ; THCR. <i>Idyl. 15, 51,</i> que deviendrai-je ? que deviendrons-nous ? οὐκ ἔχοντες ὅ τι γένωνται, THC. <i>2, 52,</i> ne sachant que devenir ; <i>rar. avec le pron. au masc</i>. οὐδ' ἔχω τίς ἂν γενοίμαν (<i>dor</i>.), ESCHL. <i>Pr. 904,</i> et je ne sais que devenir ; <i>avec un adv</i>. εὖ, καλῶς, κακῶς μοι γίγνεται, HDT. <i>1, 8 ;</i> XÉN. <i>An. 1, 7, 5, etc</i>. cela va bien, mal pour moi ; <i>avec un nom :</i> κωλυτὴς γ. τινος, THC. <i>3, 23,</i> je mets obstacle à qqe ch. ; <i>avec un part</i>. μὴ προδοὺς ἡμᾶς γένῃ, SOPH. <i>Aj. 589,</i> ne va pas nous trahir ; μὴ ἀπαρνηθεὶς γίγνῃ, PLAT. <i>Soph. 217</i> c, ne va pas nier ; <i>cf</i>. γίγνομαι ἔξαρνος, ἐμποδών, ἐκποδών, <i>etc. (v. ces mots</i>) ;<br><b>      2</b> <i>avec un rég. au gén. partitif ou collectif :</i> γ. τῶν βασιληΐων δικαστέων, HDT. <i>5, 25,</i> devenir l’un des juges royaux ; γεραιτέρων γ. XÉN. <i>Cyr. 1, 2, 15,</i> entrer dans la classe des vieillards ; τῆς βουλῆς γ. DC. <i>36, 11,</i> devenir membre du sénat ; <i>au gén. possessif :</i> γ. αὑτοῦ, SOPH. <i>O.C. 660,</i> devenir son maître ; <i>p. suite,</i> être le maître de ses propres actions, PLAT. <i>Phædr. 250</i> a ; DÉM. <i>42, 11 (cf</i>. ἐντὸς ἑαυτοῦ γ. HDT. <i>1, 119 ;</i> ἐν ἑαυτῷ γ. XÉN. <i>An. 1, 5, 17, m. sign</i>.) ; ἡ νίκη γίγνεταί τινος, XÉN. <i>Hell. 4, 3, 20,</i> la victoire se déclare pour qqn ; <i>en parl. de choses :</i> αἱ τριχίδες εἰ γενοίαθ' ἑκατὸν τοὐϐολοῦ, AR. <i>Eq. 662,</i> si les sardines en venaient à coûter une obole le cent ; ὁ σῖτος ἐγένετο ἑκκαίδεκα δραχμῶν, DÉM. le blé vint au prix de 16 drachmes ; — <i>avec une prép</i>. γίγνεσθαι ἀπό <i>ou</i> ἐκ δείπνου, HDT. <i>2, 78, etc</i>. quitter le souper, avoir soupé ; γ. ἐξ ὀφθαλμῶν τινι, HDT. <i>5, 24,</i> disparaître de la vue de qqn ; γίγνεσθαι ἐξ ἀνθρώπων, PAUS. <i>4, 26, 6,</i> disparaître d’entre les hommes, mourir ; γ. ἐν πολέμῳ, THC. <i>1, 78,</i> s’engager <i>ou</i> être engagé dans une guerre ; ἐν καιρῷ γ. XÉN. <i>Hell. 4, 3, 2,</i> être opportun ; δι' ἔχθρας γ. τινι, AR. <i>Ran. 1412,</i> devenir l’ennemi de qqn ; γ. ἐπ' ἐλπίδος, PLUT. <i>Sol. 14,</i> concevoir une espérance ; καθ' ἓν γ. THC. <i>3, 10,</i> se réunir <i>ou</i> se concerter pour une action commune ; καθ' αὑτοὺς γ. DÉM. <i>145, 11,</i> être réduit à l’isolement, à ses propres ressources ; γ. μετά τινος, XÉN. <i>Cyr. 8, 7, 27, ou</i> σύν τινι, XÉN. <i>Ages. 2, 13,</i> être du côté <i>ou</i> du parti de qqn ; γίγνεσθαι ἐπὶ τόπῳ, XÉN. <i>An. 3, 4, 49, ou</i> πρὸς τόπῳ, PLAT. <i>Phæd. 118</i> a, se trouver dans un lieu <i>ou</i> près d’un lieu ; γίγνεσθαι ὑπό τινι, être sous la dépendance de qqn, HDT. <i>7, 11 ;</i> THC. <i>7, 64, ou</i> sous la protection de qqn, XÉN. <i>Cyr. 7, 1, 34</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Syntaxe :</i><br><b>      1</b> <i>La 3<sup>e</sup> pers. sg. des temps de</i> γίγνομαι (γίγνεται, γίγνηται, ἐγένετο, <i>etc.) se construit qqf. avec un suj. plur. à peu près avec la valeur impers. de notre construction :</i> il y a trois jours, il arriva plusieurs voyageurs, <i>etc. :</i> καὶ γὰρ πάχναι καὶ χάλαζαι καὶ ἐρυσῖϐαι… γίγνεται, PLAT. <i>Conv. 188</i> b, et en effet les gelées, la grêle, la rouille, tout cela arrive, <i>etc. ;</i> ἵνα γίγνηται ἀρχαί τε καὶ γάμοι, PLAT. <i>Rsp. 363</i> a, afin qu’il trouve à remplir des charges, à conclure des mariages ; ἐγένετο ἡμέραι ὀκτώ, NT. <i>Luc. 9, 28,</i> il se passa huit jours ;<br><b>      2</b> <i>Dans la traduct. des Livres saints, la formule καὶ ἐγένετο est qqf. suivie d’une propos. à un mode pers. au sens de</i> « et il arriva que » : καὶ ἐγένετο μετὰ τεσσαράκοντα ἡμέρας ἠνέῳξε Νῶε τὴν θυρίδα τῆς κιϐωτοῦ, SPT. <i>Gen. 8, 6,</i> et il arriva qu’après 40 jours Noé ouvrit la porte de l’arche ; <i>de même</i> καὶ ἐγενήθη, SPT. <i>Deut. 2, 16 ; ou</i> ἐγένετο δέ, NT. <i>Luc. 5, 1 ; 6, 12 ; 9, 56 ; etc. — Formes : Prés</i>. γίγνομαι, IL. <i>2, 468 ;</i> OD. <i>2, 320 ;</i> ATT. (ESCHL. <i>Pers. 708 ;</i> SOPH. <i>O.C. 259 ;</i> AR. <i>Eq. 180 ;</i> THC. <i>3, 42 ; etc.) ; en ion. et en grec commun à partir d’Aristote, d’ord</i>. γίνομαι <span>[ῑ]</span> HDT. <i>8, 60 ; etc. (sel</i>. MŒR. <i>p. 108,</i> γίγνομαι ἀττικῶς, γίνομαι ἑλληνικῶς). <i>Dans les inscript. att. seul</i>. γίγνομαι <i>de 445 à 292 av. J.C. ; seul</i>. γίνομαι, <i>de 290 à 30 av. J.C. ; sous l’empire, d’ord. γίνομαι, rar</i>. γίγνομαι (<i>v. Meisterh. p. 141, 20). — Impf</i>. ἐγιγνόμην, IL. <i>13, 86 ;</i> ATT. (SOPH. <i>O.C. 272 ;</i> THC. <i>3, 12, etc.) ; poét</i>. γιγνόμην, IL. <i>13, 684 ; ion</i>. ἐγινόμην <span>[ῑ]</span> HDT. <i>8, 12, etc. — Fut</i>. γενήσομαι, ESCHL. <i>Eum. 66 ;</i> SOPH. <i>Ph. 1067 ;</i> EUR. <i>Ion 981 ;</i> THC. <i>6, 6, etc. ; dor</i>. γενησοῦμαι, LYSIS <i>Ep. ad Hpc. p. 53. — Autre fut. à forme pass. 3 sg</i>. γενηθήσεται, PLAT. <i>Parm. 141</i> e <i>dout. — Ao.1 à forme pass. (dor. et ion</i>.) ἐγενήθην, EPICH. (PHRYN. <i>p. 108</i>) ; ARCHYT. (GAL. <i>p. 674</i>) ; HPC. <i>1202</i> a, <i>1208</i> e ; ANTH. <i>5, 63 ; postér. att</i>. PHILÉM. (<i>Com. fr. 4, 47), et chez les écriv. réc</i>. POL. <i>2, 67 ; 5, 22 ;</i> DL. <i>9, 7, 7. — Ao.1 à forme moy. sbj. 2 sg</i>. γενήσῃ, EUR. <i>I.A. 1172. — Ao.2, 1 sg</i>. ἐγενόμην, IL. <i>15, 653 ;</i> PD. <i>I. 4, 14 ;</i> HDT. <i>8, 6 ;</i> ATT. (THC. <i>1, 74, etc.) ; dor</i>. ἐγενόμαν <span>[ᾱ]</span> ESCHL. <i>Pers. 934 ; ou</i> γενόμαν, PD. <i>N. 6, 22 ; 2 sg. ion</i>. γένεο, HÉS. <i>Th. 657 ; épq</i>. γένευ, IL. <i>5, 897 ; 3 sg. sync</i>. ἔγεντο (<i>p</i>. ἐγένετο), HÉS. <i>Th. 705 ;</i> PD. <i>P. 3, 87 ;</i> THCR. <i>Idyl. 1, 88, etc. ou</i> γέντο, HÉS. <i>Th. 199 ;</i> EMPÉD. <i>207 Stein ;</i> MOSCH. <i>3, 29 ;</i> A. RH. <i>4, 225 ; 3 pl. poét</i>. γένοντο, IL. <i>11, 310 ;</i> PHOCYL. <i>3, 1 ;</i> AR. <i>Av. 701 ; ion</i>. ἐγενέατο, HDT. <i>2, 166 (mais ἐγένοντο sel. d’autres) ; impér. 2 sg. poét</i>. γενεῦ, ANACR. <i>2, 9 ; opt. 3 pl. épq., poét. et ion</i>. γενοίατο, IL. <i>2, 340 ;</i> HDT. <i>1, 67 ; 2, 2 ;</i> AR. <i>Eq. 662. — Ao. itér. 3 sg</i>. γενέσκετο, OD. <i>11, 208. — Pf</i>. γέγονα, IL. <i>19, 122 ;</i> HDT. <i>1, 5 ;</i> ATT. (ESCHL. <i>Sept. 142 ;</i> XÉN. <i>Cyr. 1, 2, 13, etc.) ; d’où pl.q.pf. 3 sg</i>. ἐγεγόνει, XÉN. <i>Ages. 2, 8 ;</i> PLAT. <i>Charm. 153,</i> b, <i>etc. ; ion</i>. ἐγεγόνεε, HDT. <i>2, 2 ; 8, 27. — Pf. poét</i>. γέγαα <span>[γᾰ]</span>, <i>d’où indic. 2 pl</i>. γεγάατε <span>[ᾰᾱ]</span> BATR. <i>143 ; 3 pl</i>. γεγάασι <span>[ᾰᾱ]</span> IL. <i>4, 325 ;</i> OD. <i>24, 84 ;</i> HÉS. <i>O. 108 ; etc. ; ou</i> γεγᾶσι, EMPÉD. <i>23, 10 Diels ; inf. épq</i>. γεγάμεν, PD. <i>O. 9, 110 ; part. épq. nomin. masc</i>. γεγαώς, MAN. <i>2, 421 ; fém</i>. γεγαυῖα, MAN. <i>3, 535 ; dat. neutre</i> γεγαῶτι, MAN. <i>6, 246 ; acc. masc</i>. γεγαῶτα, IL. <i>9, 456 ;</i> OD. <i>4, 144 ; fém</i>. γεγαυῖαν, A. RH. <i>1, 719 ; plur. masc</i>. γεγαῶτες, THCR. <i>Idyl. 17, 25 ;</i> MAN. <i>6, 694 ; fém</i>. γεγαυῖαι, HH. <i>Merc. 552 ; acc. masc</i>. γεγαῶτας, IL. <i>2, 866 ;</i> IBYC. <i>16 ; duel</i> γεγαῶτε, THCR. <i>Idyl. 22, 176 ; formes contractes : sg. nomin. masc</i>. γεγώς, SOPH. <i>Aj. 472 ; fém</i>. γεγῶσα, EUR. <i>Andr. 434 ;</i> AR. <i>Lys. 641, etc. ; plur</i>. γεγῶτες, EUR. <i>Med. 558 ;</i> -ώτων, EUR. <i>Med. 490 ;</i> -ῶσι, EUR. <i>El. 531 ;</i> -ῶτας, SOPH. <i>fr. 94, 4 ; duel</i> γεγῶτε, EUR. <i>Hel. 1685. — Pf. dor. inf</i>. γεγάκειν <span>[ᾱ]</span> <i>p</i>. *γεγακέναι, PD. <i>O. 6, 49. — Pf. à forme pass</i>. γεγένημαι (<i>dans les inscript. att. à partir de 376 av. J.C. aussi usité que</i> γέγονα, <i>sans différence de sens ; v. Meisterh. p. 155, 8</i>), ESCHL. <i>Ch. 379 ;</i> EUR. <i>Cycl. 637 ;</i> AR. <i>Eq. 764 ;</i> THC. <i>4, 125 ;</i> PLAT. <i>Rsp. 411</i> c ; <i>dor</i>. γεγέναμαι <span>[ᾱ]</span> PD. <i>O. 6, 53. Pl.q.pf. 3 sg</i>. ἐγεγένητο, THC. <i>7, 42 ;</i> XÉN. <i>Hell. 6, 5, 16, etc. ; ou</i> γεγένητο, XÉN. <i>Cyr. 3, 2, 24</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *ǵenh₁-, engendrer, se produire, <i>avec redoubl. ; cf. lat</i>. gignō.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γινομαι - γίνομαι</font>\n<br><br>prolongement d'un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n678 fois dans 633 versets de 25 livres bibliques (NT)\n<ul>\n<li>Matthieu (74)</li>\n<li>Marc (54)</li>\n<li>Luc (137)</li>\n<li>Jean (52)</li>\n<li>Actes (127)</li>\n<li>Romains (35)</li>\n<li>1 Corinthiens (42)</li>\n<li>2 Corinthiens (12)</li>\n<li>Galates (12)</li>\n<li>Ephésiens (8)</li>\n<li>Philippiens (7)</li>\n<li>Colossiens (5)</li>\n<li>1 Thessaloniciens (12)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (4)</li>\n<li>2 Timothée (4)</li>\n<li>Tite (1)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (28)</li>\n<li>Jacques (10)</li>\n<li>1 Pierre (7)</li>\n<li>2 Pierre (5)</li>\n<li>1 Jean (1)</li>\n<li>3 Jean (1)</li>\n<li>Apocalypse (38)</li>\n</ul>\n</td></tr>\n</table>","G1097":"<h1>ginosko</h1>\n<p>Strong n° 1097 <i>Prononciation [ghin-oce'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>apprendre à connaître, venir à la connaissance, apercevoir, percevoir, sentir</li>\n<li>savoir, comprendre, avoir la connaissance de</li>\n<li>idiome Juif pour parler de la relation sexuelle entre l'homme et la femme</li>\n<li>avoir des accointances avec, connaître</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γινώσκω</b>, <i>v</i>. γιγνώσκω, <i>fin</i>.<br>\n<b>γιγνώσκω</b> <span>(<i>impf</i>. ἐγίγνωσκον, <i>f</i>. γνώσομαι, <i>ao.2</i> ἔγνων, <i>pf</i>. ἔγνωκα, <i>pl.q.pf</i>. ἐγνώκειν ; <i>pass. f</i>. γνωσθήσομαι, <i>ao</i>. ἐγνώσθην, <i>pf</i>. ἔγνωσμαι)</span><br><b>A<br>   I</b> <i>propr</i>. apprendre à connaître, <i>synon. de</i> ἐπιστήμην λαϐεῖν, PLAT. <i>Theæt. 209</i> e ; <i>p. opp. à</i> δοξάζω, « avoir une opinion faite », PLAT. <i>Rsp. 476</i> d ; εὖ νύ τις αὐτὸν γνώσεται, IL. <i>18, 270,</i> (à sa vaillance et à ses coups) certes il apprendra à le connaître, <i>en parl. d’Achille ;</i> οἵους γνώσεσθε τοὺς ἀνθρώπους, XÉN. <i>An. 1, 7, 4</i> (quand je songe) quels vous apprendrez à connaître ces hommes, <i>càd</i>. quelle opinion vous aurez d’eux, quand vous aurez appris à les connaître ; <span><i>prov</i>. γνῶθι σεαυτόν</span>, ARSTT. <i>Rhet. 2, 21, etc</i>. apprends à te connaître toi-même ;<br><b>   II</b> <i>p. suite,</i> se rendre compte, <i>d’où :</i><br><b>      1</b> comprendre, reconnaître, <i>distinct de</i> εἰδέναι, « savoir » : ἵν' εἰδῆτε ὑμεῖς καὶ γνῶτε ὅτι, DÉM. <i>561, 12,</i> afin que vous sachiez et que vous vous rendiez compte que, <i>etc. ;</i> ἀσπίδι γιγνώσκων, IL. <i>5, 182,</i> (le) reconnaissant à son bouclier ; <i>avec l’acc</i>. γ. τὴν φωνήν, PLAT. <i>Prot. 310</i> b, reconnaître la voix ; γ. ἠμὲν θεὸν ἠδὲ καὶ ἄνδρα, IL. <i>5, 128,</i> discerner un dieu d’avec un homme ; γ. ὄρνιθας, OD. <i>2, 159,</i> connaître le vol des oiseaux, <i>càd</i>. en comprendre la signification ; γιγνώσκω σε, SOPH. <i>Ph. 1388,</i> je te comprends, je te devine ; <i>ou le gén</i>. γ. ἀλλήλων, OD. <i>23, 109,</i> se reconnaître l’un l’autre ; <i>avec un acc. accompagné d’un part</i>. ἔγνων μιν οἰωνὸν ἐόντα, OD. <i>15, 532,</i> je reconnus que c’était un oiseau annonçant un présage ; γνόντες οὐδεμίαν σφίσι τιμωρίαν οὖσαν, THC. <i>1, 25,</i> quand ils se furent rendu compte qu’ils ne pouvaient attendre aucun secours ; <i>avec un part. en relat. avec un gén. s.-e. :</i> ὡς γνῶ χωομένοιο, IL. <i>4, 357,</i> lorsqu’il s’aperçut qu’il se fâchait ; <i>avec un part. en relat. avec le sujet :</i> ἐπειδὰν γνῶσιν ἀπιστούμενοι, XÉN. <i>Cyr. 7, 2, 17,</i> lorsqu’ils s’aperçoivent qu’on se défie d’eux ; ἔγνωκα ἠπατημένη, SOPH. <i>Aj. 807,</i> j’ai compris que j’étais trompée ; <i>cf</i>. XÉN. <i>Cyr. 6, 3, 1 ;</i> AR. <i>Eq. 658 ; avec</i> ὅτι, ESCHL. <i>Pr. 104, etc. ;</i> XÉN. <i>Cyr. 4, 2, 12, etc. ;</i> DÉM. <i>561, 12 ; etc. ; ou</i> ὡς, IL. <i>22, 10 ;</i> OD. <i>21, 209 ;</i> XÉN. <i>Œc. 2, 8 ;</i> AR. <i>Nub. 1095, etc</i>. se rendre compte que ; <i>avec</i> εἰ : γνώμεναι εἴ μιν φοϐέουσι, IL. <i>21, 266,</i> se rendre compte si les dieux sont à sa poursuite ; <i>avec un acc. suivi de</i> ὅτι <i>ou d’un relat</i>. τοὺς Πέρσας γιγνώσκων ὅτι οὕτως ὡπλισμένοι εἰσίν, XÉN. <i>Cyr. 2, 1, 4,</i> se rendant compte que les Perses sont ainsi armés ; τῶν Σωκράτην γιγνωσκόντων οἷος ἦν, XÉN. <i>Mem. 4, 8, 11,</i> ceux qui savent bien ce qu’était Socrate (<i>cf</i>. IL. <i>5, 85 ;</i> PLAT. <i>Rsp. 466</i> c, <i>etc.) ; avec un inf</i>. ἵνα γνῶ τρέφειν, <i>etc</i>. SOPH. <i>Ant. 1089,</i> afin qu’il apprenne à prendre soin de, <i>etc. ; abs</i>. être sensé, être raisonnable : ἔγνως ἄν, SOPH. <i>O.R. 403,</i> tu serais devenu raisonnable ; παθόντα γνῶναι, comprendre <i>ou</i> être mis à la raison à ses dépens, HÉS. <i>O. 218 ;</i> PLAT. <i>Conv. 222</i> b) ; πᾶς ὁ γιγνώσκων, PLAT. <i>Rsp. 347</i> d, tout homme se rendant compte, <i>càd</i>. tout homme prudent ; <i>particul. dans le dialogue :</i> ἔγνων, SOPH. <i>Aj. 36,</i> je comprends, je sais ; ἔγνως, SOPH. <i>Tr. 1221 ;</i> EUR. <i>Andr. 885,</i> tu as compris, <i>càd</i>. tu as raison, tu dis bien ;<br><b>      2</b> <i>p. suite,</i> se faire une opinion, juger, penser, HDT. <i>9, 2 ;</i> ATT. ; <i>p. opp. à</i> οἴομαι « avoir une opinion réfléchie <i>ou</i> non » : εἴ τις οἴεται, οὐκ ὀρθῶς ἔγνωκεν, DÉM. si qqn le pense, il ne juge pas bien ; ὀρθῶς γ. περί τινος, THC. <i>2, 22,</i> juger droitement de qqe ch. ; περὶ τῆς βοηθείας ταῦτα γιγνώσκω, DÉM. <i>14, 18,</i> au sujet du secours, voilà ce que je pense ; οὕτω γ. XÉN. <i>An. 5, 9, 19,</i> penser ainsi ; τἀναντία γ. XÉN. <i>Hell. 2, 3, 38,</i> penser le contraire ;<br><b>      3</b> <i>en gén</i>. prendre une décision, décider, résoudre : σὺ δ' αὐτὸς γνῶθι τίνα πέμπειν δοκεῖ, ESCHL. <i>Sept. 650,</i> mais décide toi-même qui tu crois devoir envoyer ; <i>avec une prop. inf</i>. décider que, <i>etc</i>. HDT. <i>1, 74 et 78 ;</i> THC. <i>1, 43 ;</i> ISOCR. <i>361</i> d, <i>etc. ;</i> ἐγνωσμένον ἐστί, LUC. <i>Nigr. 3,</i> c’est chose décidée ; <i>particul. en parl. de décisions judiciaires, politiques, etc. :</i> κρίσις ἐγνωσμένη ὑπό τινος, ISOCR. <i>121</i> e, jugement rendu par qqn ; <i>cf</i>. DÉM. <i>903, 11 ;</i> χαλεπόν τι γ. περί τινος, DH. <i>54, 7,</i> prendre au sujet de qqn une décision rigoureuse ;<br><b>      4</b> connaître, avoir des relations intimes, CALL. <i>Ep. 58, 3 ;</i> PLUT. <i>Alex. 21 ;</i> NT. <i>Luc. 1, 34 ; Matth. 1, 25, etc. ;</i><br><b>      5</b> <i>postér. synon. de</i> εἰδέναι <i>dans la loc</i>. γ. χάριν, PLUT. <i>Galb. 22 ;</i> DC. <i>39, 9 ; 44, 19, etc</i>. savoir gré ;<br><b>B</b> <i>au sens causal,</i> faire connaître, chanter, célébrer (une divinité, une ville), <i>acc</i>. PD. <i>O. 6, 89 ; 13, 3</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés</i>. γιγνώσκω, IL. <i>11, 651 ;</i> ATT. (ESCHL. <i>Pr. 377 ;</i> SOPH. <i>O.R. 1325 ;</i> THC. <i>2, 48, etc.) ; ion., poét. et de prose réc. à partir d’Aristote,</i> γινώσκω <span>[ῑ]</span> HDT. <i>3, 81 ;</i> THCR. <i>etc. ; 3 pl. dor</i>. γινώσκοντι, PD. <i>O. 6, 97. Dans les inscript. att. seul</i>. γιγνώσκω <i>jusqu’en 325 av. J.C. ; sous l’empire,</i> γιγν- <i>et</i> γιν- ; <i>v. Meisterh. p. 142, 21. — Impf</i>. ἐγίγνωσκον, ATT. (THC. <i>6, 64 ; etc.) ; poét</i>. γίγνωσκον, IL. <i>6, 191 ; ion</i>. ἐγίνωσκον <span>[ῑ]</span> HDT. <i>9, 2. — Fut. 2 sg. ion</i>. γνώσεαι, IL. <i>2, 367 ;</i> THCR. <i>Idyl. 22, 63 ; ou</i> γνώσῃ, IL. <i>2, 365 ;</i> THCR. <i>Idyl. 26, 19 ; att</i>. γνώσει, ESCHL. <i>Ag. 807 ;</i> SOPH. <i>O.C. 852 ;</i> PLAT. <i>Phil. 12, etc. ; opt. 3 pl</i>. γνωσοίατο, SOPH. <i>O.R. 1274. — Ao.1 réc. sbj. 3 pl</i>. γνώσωσι, CALLISTH. <i>3, 22. — Ao.2</i> ἔγνων, IL. <i>13, 72 ;</i> HÉS. <i>O. 218 ;</i> PD. <i>O. 7, 83 ;</i> HDT. <i>8, 92 ;</i> ATT. (ESCHL. <i>Ag. 1106 ;</i> THC. <i>7, 3, etc.) ; épq</i>. γνῶν, IL. <i>4, 357 ;</i> HÉS. <i>Th. 551 ; d’où 3 pl. poét</i>. ἔγνων (<i>p</i>. ἔγνωσαν) HH. <i>Cer. 111 ;</i> PD. <i>P. 9, 79 ; 3 duel</i> γνώτην, OD. <i>21, 36. Impér. 2 sg</i>. γνῶθι, ESCHL. <i>Sept. 652 ;</i> SOPH. <i>O.C. 1025 ;</i> PLAT. <i>Prot. 343</i> b ; <i>2 pl</i>. γνῶτε, IL. <i>19, 84. Sbj</i>. γνῶ, γνῷς, <i>etc</i>. IL. <i>1, 411 ;</i> OD. <i>22, 373 ;</i> ATT. (AR. <i>Ran. 1210 ; etc.) ; épq</i>. γνώω, OD. <i>14, 118 ;</i> THCR. <i>Idyl. 25, 177 ; 2 sg</i>. γνώῃς, IL. <i>23, 487 ; 3 sg</i>. γνώῃ, IL. <i>24, 688 ;</i> OD. <i>17, 556 ; 1 pl</i>. γνώομεν, OD. <i>16, 304 ; 3 pl</i>. γνώωσι, IL. <i>23, 610. Opt</i>. γνοίην, IL. <i>5, 85 ;</i> ATT. (SOPH. <i>Tr. 1118 ;</i> AR. <i>Vesp. 72 ; etc.) ; d’où 1 pl</i>. γνοίημεν, PLAT. <i>Leg. 918, mais</i> γνοῖμεν, PLAT. <i>1 Alc. 129</i> a ; <i>2 pl</i>. γνοίητε, XÉN. <i>Hell. 6, 3, 13 ; 3 pl</i>. γνοίησαν, HPC. <i>622 Littré ;</i> DÉM. <i>897, 7, ou</i> γνοῖεν, IL. <i>18, 125 ;</i> SOPH. <i>Ph. 325 ;</i> XÉN. <i>Cyr. 8, 3, 49 ; etc. Inf</i>. γνῶναι, OD. <i>13, 312 ;</i> ATT. (SOPH. <i>O.C. 137 ;</i> THC. <i>2, 40, etc.) ; épq</i>. γνώμεναι, IL. <i>21, 266. Part</i>. γνούς, HDT. <i>4, 136 ;</i> ATT. (SOPH. <i>El. 731 ;</i> THC. <i>4, 28, etc.). — Pf</i>. ἔγνωκα, PD. <i>P. 4, 287 ;</i> HDT. <i>1, 207 ;</i> ATT. (ESCHL. <i>Pr. 51 ;</i> SOPH. <i>O.C. 96, etc.). — Pl.q.pf</i>. ἐγνώκειν, DÉM. — <i>Pass. f</i>. γνωσθήσομαι, AR. <i>Nub. 918 ;</i> THC. <i>1, 124 ; etc. — Ao</i>. ἐγνώσθην, HDT. <i>4, 42 ;</i> ATT. (ESCHL. <i>Suppl. 7 ;</i> THC. <i>2, 65, etc.). — Pf</i>. ἔγνωσμαι, THC. <i>3, 38 ;</i> EUR. <i>H.f. 1287 ; etc. — Moy. ao. inf</i>. γνώσασθαι, MAN. <i>2, 51</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *ǵneh₃-, reconnaître, connaître, <i>avec redoubl. ; cf. lat</i>. (g)nōscō.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γινωσκω - γινώσκω</font>\n<br><br>prolongement d'un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – une connaissance fondée sur une expérience personnelle\n<br><br> – voir avec les yeux de l'esprit, donc une pure et claire perception mentale\n<br><br> – une connaissance obtenue par la proximité de la chose connue, notre compréhension\n<br><br> – implique une perspicacité naturelle, une connaissance obtenue à travers les cinq sens\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n226 fois dans 208 versets de 20 livres bibliques (NT)\n<ul>\n<li>Matthieu (20)</li>\n<li>Marc (13)</li>\n<li>Luc (29)</li>\n<li>Jean (56)</li>\n<li>Actes (18)</li>\n<li>Romains (9)</li>\n<li>1 Corinthiens (14)</li>\n<li>2 Corinthiens (8)</li>\n<li>Galates (4)</li>\n<li>Ephésiens (3)</li>\n<li>Philippiens (5)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Timothée (3)</li>\n<li>Hébreux (5)</li>\n<li>Jacques (3)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (25)</li>\n<li>2 Jean (1)</li>\n<li>Apocalypse (6)</li>\n</ul>\n</td></tr>\n</table>","G1098":"<h1>gleukos</h1>\n<p>Strong n° 1098 <i>Prononciation [glyoo'-kos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>le jus qui sort de la grappe pressée, le vin doux, vin nouveau</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γλεῦκος, εος-ους (τὸ) :<br>      1</b> vin doux, ARSTT. <i>Meteor. 4, 3, 13 ;</i> NIC. <i>Al. 184, 299 ;</i> GEOP. <i>19, 9 ; etc. ; fig</i>. γλ. τῆς ἡλικίας, CLÉM. <i>178,</i> la fougue de la jeunesse ;<br><b>      2</b> douceur, ARSTT. <i>Probl. 22, 12</i>.<br><span><b>Étym</b>. <i>Cf</i>. γλυκύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γλευκος - γλεῦκος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1099":"<h1>glukus</h1>\n<p>Strong n° 1099 <i>Prononciation [gloo-koos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>doux, douce, sucré</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>γλυκύς, εῖα, ύ</b> <span>[ῠκ]</span> doux, <i>càd. :</i><br><b>   I</b> <i>au pr. :</i><br><b>      1</b> de saveur douce, <i>p. opp. à</i> « amer (πικρός) », HDT. <i>4, 52 ;</i> PLUT. <i>M. 151</i> c, <i>1120</i> e ; <i>à</i> « salé (ἁλμυρός) », ARSTT. <i>Meteor. 2, 2, 12 ; à</i> « piquant (δριμύς) », PLUT. <i>M. 708</i> d ; <i>à</i> « acide (ὀξύς) », HPC. <i>346, 18 ; en parl. d’aliments (figues, etc</i>. LUC. <i>V. auct. 19, etc.) ; particul. de boissons</i> (nectar, IL. <i>1, 598 ; etc</i>.) ; γλ. οἶνος, ANAXANDR. (ATH. <i>131</i> f), <i>ou subst</i>. ὁ γλυκύς, HPC. <i>673, 33 ;</i> ARSTT. <i>Probl. 21, 19 ; ou</i> τὸ γλυκύ, TH. <i>C.P. 6, 17, 2 ;</i> NIC. <i>Al. 386,</i> vin fait de raisins desséchés au soleil ; <i>subst</i>. ἡ γλυκεῖα, réglisse (<i>cf</i>. γλυκύρριζα), TH. <i>H.P. 9, 13, 2 ; par antiphrase,</i> bile (χολή), ATT. <i>selon</i> HELLAD. (PHOT. <i>Bibl. 538, 8 Bekker</i>) ; moutarde, MATR. (ATH. <i>136</i> d) ;<br><b>      2</b> d’odeur douce, ARSTT. <i>An. 2, 9 ;</i> γλυκὺ ὄζειν, CRATÈS, CRAT. exhaler une odeur douce ;<br><b>   II</b> <i>fig. :</i><br><b>      1</b> doux, agréable, charmant, délicieux, <i>en parl. de choses</i> (sommeil, IL. <i>1, 610 ;</i> désir, IL. <i>3, 446 ;</i> son de la voix, IL. <i>1, 249, etc</i>.) ; γλ. αἰών, OD. <i>5, 152,</i> le doux temps de la vie, <i>càd</i>. la jeunesse ; φρὴν γλυκεῖα, PD. <i>P. 6, 52,</i> (son) âme douce ; γλ. καρπὸς φρενός, PD. <i>O. 7, 15,</i> le doux fruit de l’intelligence ; <i>etc. ;</i> γλυκύ ἐστι <i>avec l’inf</i>. ESCHL. <i>Pr. 698 ;</i> SOPH. <i>O.R. 1335, etc</i>. il est doux de, <i>etc. ; en parl. de pers</i>. SOPH. <i>O.C. 106 ; dans le dialogue :</i> ὦ γλυκύτατε, AR. <i>Ach. 462 ;</i> PLAT. <i>Hipparch. 227</i> d, mon très doux ami ! ;<br><b>      2</b> <i>avec une nuance d’ironie,</i> d’humeur douce et facile, simple, bénévole : ὡς γλυκὺς εἶ, PLAT. <i>Hipp. ma. 228</i> b, comme tu es simple !.<br><span>•<i> Cp</i>. γλυκίων, IL. <i>1, 249 ; d’où</i> γλύσσων (= *γλύκϳων ; <i>cf</i>. ἐλάσσων = *ἐλάχϳων), XÉNOPHAN. (EG. <i>301, 14 ;</i> HDN GR. <i>π. μ. λ. 41, 5) ; autres cp</i>. γλυκύτερος, PD. <i>O. 1, 19, 109 ;</i> ATT., <i>et (comme de</i> *γλύκιος) γλυκιότερος (<i>corr. p</i>. γλυκειότερος) <span>[ῑ]</span> ANTH. <i>App. 153</i>. — <i>• Sup</i>. γλύκιστος, EL. <i>N.A. 12, 46, etc. ; ou</i> γλυκύτατος, AR. PLAT. <i>ll. cc. ; etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Béot. neutre</i> γλουκού, COR. <i>fr. 18</i>.<br><span><b>Étym</b>. <i>p.-ê. apparenté avec le lat</i>. dulcis.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">γλυκυς - γλυκύς</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jacques (2)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>"};
